insert into public.content_units(id,part_id,type,data,display_order,metadata) values('3f69fb9a-dc27-4cf2-b33d-bf6036b8c058','692c4161-f1c5-42d0-94e2-fabb45475e11','question_complete_words','{"prompt":"Fill in the missing letters in the paragraph.","text":"Honeybees live together in large groups called colonies. Each {{1}} has {{2}} queen, a {{3}} hundred {{4}}, and {{5}} of {{6}} workers. {{7}} workers {{8}} many {{9}} jobs {{10}} their short lives. Young bees clean the hive and feed the babies, while older bees fly outside to collect nectar and pollen from flowers. When a bee finds a good place full of flowers, it returns to the hive and performs a special dance that shows the other bees where to go.","blanks":[{"id":"1","stem":"col","length":3},{"id":"2","stem":"o","length":2},{"id":"3","stem":"f","length":2},{"id":"4","stem":"ma","length":3},{"id":"5","stem":"thou","length":5},{"id":"6","stem":"fem","length":3},{"id":"7","stem":"T","length":2},{"id":"8","stem":"ha","length":2},{"id":"9","stem":"diff","length":5},{"id":"10","stem":"dur","length":3}],"topic":"life science"}'::jsonb,1,'{"toefl_task":"complete_the_words","original_slug":"cw-practice-1","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('3f69fb9a-dc27-4cf2-b33d-bf6036b8c058','{"blanks":{"1":"ony","2":"ne","3":"ew","4":"les","5":"sands","6":"ale","7":"he","8":"ve","9":"erent","10":"ing"},"stems":{"1":"col","2":"o","3":"f","4":"ma","5":"thou","6":"fem","7":"t","8":"ha","9":"diff","10":"dur"},"words":{"1":"colony","2":"one","3":"few","4":"males","5":"thousands","6":"female","7":"The","8":"have","9":"different","10":"during"}}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Full paragraph: Honeybees live together in large groups called colonies. Each colony has one queen, a few hundred males, and thousands of female workers. The workers have many different jobs during their short lives. Young bees clean the hive and feed the babies, while older bees fly outside to collect nectar and pollen from flowers. When a bee finds a good place full of flowers, it returns to the hive and performs a special dance that shows the other bees where to go."}}'::jsonb) on conflict (content_unit_id) do nothing;
