insert into public.answer_keys(content_unit_id,correct,metadata) values('de03a38f-33c4-489c-9d9e-75a2cfd86ca9','{"blanks":{"1":"ding","2":"t","3":"iet","4":"ere","5":"an","6":"one","7":"rk","8":"oup","9":"rians","10":"ays"},"stems":{"1":"len","2":"i","3":"qu","4":"wh","5":"c","6":"al","7":"wo","8":"gr","9":"libra","10":"alw"},"words":{"1":"lending","2":"it","3":"quiet","4":"where","5":"can","6":"alone","7":"work","8":"group","9":"Librarians","10":"always"}}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Full paragraph: The university library offers many services for new students. Besides lending books, it provides quiet rooms where students can study alone or work on group projects. Librarians are always ready to help people find articles, use the online catalog, or learn how to cite sources correctly. The library also lends laptops and chargers for short periods. Many students say that spending a few hours there each week helps them stay organized and finish their assignments on time."}}'::jsonb) on conflict (content_unit_id) do nothing;
