insert into public.content_units(id,part_id,type,data,display_order,metadata) values('3d8db96b-bbc1-4714-8033-279ed4fb48bd','02e59cd3-3074-4c00-a531-f7aa964d03b3','question_complete_words','{"prompt":"Fill in the missing letters in the paragraph.","text":"Bicycles are becoming more popular in many cities around the world. Riding a {{1}} is {{2}}, quiet, {{3}} good {{4}} your {{5}}. It {{6}} helps {{7}} traffic {{8}} air {{9}} because {{10}} do not burn fuel. Many cities now build special lanes so that riders can travel safely away from cars and buses. Some places even offer public bicycles that people can rent for a short time and then return at a station near their destination.","blanks":[{"id":"1","stem":"bic","length":4},{"id":"2","stem":"ch","length":3},{"id":"3","stem":"a","length":2},{"id":"4","stem":"f","length":2},{"id":"5","stem":"hea","length":3},{"id":"6","stem":"al","length":2},{"id":"7","stem":"red","length":3},{"id":"8","stem":"a","length":2},{"id":"9","stem":"poll","length":5},{"id":"10","stem":"bicy","length":4}],"topic":"transportation"}'::jsonb,1,'{"toefl_task":"complete_the_words","original_slug":"cw-practice-3","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('3d8db96b-bbc1-4714-8033-279ed4fb48bd','{"blanks":{"1":"ycle","2":"eap","3":"nd","4":"or","5":"lth","6":"so","7":"uce","8":"nd","9":"ution","10":"cles"},"stems":{"1":"bic","2":"ch","3":"a","4":"f","5":"hea","6":"al","7":"red","8":"a","9":"poll","10":"bicy"},"words":{"1":"bicycle","2":"cheap","3":"and","4":"for","5":"health","6":"also","7":"reduce","8":"and","9":"pollution","10":"bicycles"}}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Full paragraph: Bicycles are becoming more popular in many cities around the world. Riding a bicycle is cheap, quiet, and good for your health. It also helps reduce traffic and air pollution because bicycles do not burn fuel. Many cities now build special lanes so that riders can travel safely away from cars and buses. Some places even offer public bicycles that people can rent for a short time and then return at a station near their destination."}}'::jsonb) on conflict (content_unit_id) do nothing;
