insert into public.content_units(id,part_id,type,data,display_order,metadata) values('4301d5e2-8cd0-48a3-8eb4-d6c0f9f35d86','08fe6723-cc46-4c2e-bd65-41b88abc9fd8','question_complete_words','{"prompt":"Fill in the missing letters in the paragraph.","text":"Musical instruments produce sound by making something vibrate. In a {{1}}, the {{2}} move {{3}} and {{4}} when {{5}} are {{6}}, and {{7}} hollow {{8}} body {{9}} the {{10}} louder. In a flute, the player blows across a small hole, which causes the air inside the tube to vibrate. Drums work in a similar way, since the stretched skin shakes after it is struck. The size and shape of each instrument decide whether its notes sound high or low.","blanks":[{"id":"1","stem":"gui","length":3},{"id":"2","stem":"str","length":4},{"id":"3","stem":"ba","length":2},{"id":"4","stem":"fo","length":3},{"id":"5","stem":"th","length":2},{"id":"6","stem":"plu","length":4},{"id":"7","stem":"t","length":2},{"id":"8","stem":"woo","length":3},{"id":"9","stem":"ma","length":3},{"id":"10","stem":"so","length":3}],"topic":"music"}'::jsonb,1,'{"toefl_task":"complete_the_words","original_slug":"cw-practice-4","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('4301d5e2-8cd0-48a3-8eb4-d6c0f9f35d86','{"blanks":{"1":"tar","2":"ings","3":"ck","4":"rth","5":"ey","6":"cked","7":"he","8":"den","9":"kes","10":"und"},"stems":{"1":"gui","2":"str","3":"ba","4":"fo","5":"th","6":"plu","7":"t","8":"woo","9":"ma","10":"so"},"words":{"1":"guitar","2":"strings","3":"back","4":"forth","5":"they","6":"plucked","7":"the","8":"wooden","9":"makes","10":"sound"}}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Full paragraph: Musical instruments produce sound by making something vibrate. In a guitar, the strings move back and forth when they are plucked, and the hollow wooden body makes the sound louder. In a flute, the player blows across a small hole, which causes the air inside the tube to vibrate. Drums work in a similar way, since the stretched skin shakes after it is struck. The size and shape of each instrument decide whether its notes sound high or low."}}'::jsonb) on conflict (content_unit_id) do nothing;
