insert into public.content_units(id,part_id,type,data,display_order,metadata) values('66dfdd1b-df23-4f62-98d6-75edd9ac8f64','c8fd6925-042f-4f10-a936-29f19e5ebfe7','question_complete_words','{"prompt":"Fill in the missing letters in the paragraph.","text":"Paper was first developed in China roughly two thousand years ago. Before {{1}} invention, {{2}} wrote {{3}} materials {{4}} as {{5}}, bamboo, {{6}} animal {{7}}, which {{8}} either {{9}} or {{10}}. Early papermakers soaked plant fibers in water, beat them into a thin pulp, and spread the mixture across a screen to dry. The new material was light, cheap, and easy to produce in large amounts. Over many centuries, the technique slowly traveled along trade routes and eventually changed how knowledge was recorded almost everywhere.","blanks":[{"id":"1","stem":"i","length":2},{"id":"2","stem":"peo","length":3},{"id":"3","stem":"o","length":1},{"id":"4","stem":"su","length":2},{"id":"5","stem":"si","length":2},{"id":"6","stem":"a","length":2},{"id":"7","stem":"sk","length":2},{"id":"8","stem":"we","length":2},{"id":"9","stem":"expe","length":5},{"id":"10","stem":"he","length":3}],"topic":"history"}'::jsonb,1,'{"toefl_task":"complete_the_words","original_slug":"cw-practice-5","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('66dfdd1b-df23-4f62-98d6-75edd9ac8f64','{"blanks":{"1":"ts","2":"ple","3":"n","4":"ch","5":"lk","6":"nd","7":"in","8":"re","9":"nsive","10":"avy"},"stems":{"1":"i","2":"peo","3":"o","4":"su","5":"si","6":"a","7":"sk","8":"we","9":"expe","10":"he"},"words":{"1":"its","2":"people","3":"on","4":"such","5":"silk","6":"and","7":"skin","8":"were","9":"expensive","10":"heavy"}}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Full paragraph: Paper was first developed in China roughly two thousand years ago. Before its invention, people wrote on materials such as silk, bamboo, and animal skin, which were either expensive or heavy. Early papermakers soaked plant fibers in water, beat them into a thin pulp, and spread the mixture across a screen to dry. The new material was light, cheap, and easy to produce in large amounts. Over many centuries, the technique slowly traveled along trade routes and eventually changed how knowledge was recorded almost everywhere."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.parts(id,section_id,name,display_order,metadata) values('f3ed0ce0-bf94-421b-8c49-85dce09a0f82','482d51fe-11f1-4a08-a5d3-8ca3de98dfb1','Complete the Words',6,'{"toefl_task":"complete_the_words"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('024b81c8-0a9e-49a2-ae90-b910b06643c0','f3ed0ce0-bf94-421b-8c49-85dce09a0f82','question_complete_words','{"prompt":"Fill in the missing letters in the paragraph.","text":"Many people believe that they can do several tasks at the same time without any loss of quality. Research {{1}}, however, {{2}} the {{3}} usually {{4}} rapidly {{5}} tasks {{6}} than {{7}} them {{8}}. Each {{9}} costs a {{10}} amount of time and attention, and these costs add up over a long day. As a result, a student who reads while checking messages may need more time to finish and may remember less of the material than a student who focuses on one task.","blanks":[{"id":"1","stem":"sugg","length":4},{"id":"2","stem":"th","length":2},{"id":"3","stem":"br","length":3},{"id":"4","stem":"swit","length":4},{"id":"5","stem":"bet","length":4},{"id":"6","stem":"rat","length":3},{"id":"7","stem":"perfo","length":5},{"id":"8","stem":"toge","length":4},{"id":"9","stem":"swi","length":3},{"id":"10","stem":"sm","length":3}],"topic":"psychology"}'::jsonb,1,'{"toefl_task":"complete_the_words","original_slug":"cw-practice-6","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('024b81c8-0a9e-49a2-ae90-b910b06643c0','{"blanks":{"1":"ests","2":"at","3":"ain","4":"ches","5":"ween","6":"her","7":"rming","8":"ther","9":"tch","10":"all"},"stems":{"1":"sugg","2":"th","3":"br","4":"swit","5":"bet","6":"rat","7":"perfo","8":"toge","9":"swi","10":"sm"},"words":{"1":"suggests","2":"that","3":"brain","4":"switches","5":"between","6":"rather","7":"performing","8":"together","9":"switch","10":"small"}}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Full paragraph: Many people believe that they can do several tasks at the same time without any loss of quality. Research suggests, however, that the brain usually switches rapidly between tasks rather than performing them together. Each switch costs a small amount of time and attention, and these costs add up over a long day. As a result, a student who reads while checking messages may need more time to finish and may remember less of the material than a student who focuses on one task."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.parts(id,section_id,name,display_order,metadata) values('5c425dd4-7bb2-4117-a2b2-4ff2aafc0a6a','482d51fe-11f1-4a08-a5d3-8ca3de98dfb1','Complete the Words',7,'{"toefl_task":"complete_the_words"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('2af3d461-774b-4562-acb4-f506cae3701e','5c425dd4-7bb2-4117-a2b2-4ff2aafc0a6a','question_complete_words','{"prompt":"Fill in the missing letters in the paragraph.","text":"Deserts are not always hot places. A {{1}} is {{2}} mainly {{3}} how {{4}} rain {{5}} receives, {{6}} by {{7}} temperature. {{8}} of {{9}} largest {{10}} on the planet are actually located near the poles, where the air is extremely cold and dry. In these regions, snow falls only rarely, and the small amount that does fall may remain on the ground for many years. Plants and animals that live there must survive both freezing winds and a constant shortage of liquid water.","blanks":[{"id":"1","stem":"des","length":3},{"id":"2","stem":"def","length":4},{"id":"3","stem":"b","length":1},{"id":"4","stem":"lit","length":3},{"id":"5","stem":"i","length":1},{"id":"6","stem":"n","length":2},{"id":"7","stem":"i","length":2},{"id":"8","stem":"So","length":2},{"id":"9","stem":"t","length":2},{"id":"10","stem":"des","length":4}],"topic":"geography"}'::jsonb,1,'{"toefl_task":"complete_the_words","original_slug":"cw-practice-7","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('2af3d461-774b-4562-acb4-f506cae3701e','{"blanks":{"1":"ert","2":"ined","3":"y","4":"tle","5":"t","6":"ot","7":"ts","8":"me","9":"he","10":"erts"},"stems":{"1":"des","2":"def","3":"b","4":"lit","5":"i","6":"n","7":"i","8":"so","9":"t","10":"des"},"words":{"1":"desert","2":"defined","3":"by","4":"little","5":"it","6":"not","7":"its","8":"Some","9":"the","10":"deserts"}}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Full paragraph: Deserts are not always hot places. A desert is defined mainly by how little rain it receives, not by its temperature. Some of the largest deserts on the planet are actually located near the poles, where the air is extremely cold and dry. In these regions, snow falls only rarely, and the small amount that does fall may remain on the ground for many years. Plants and animals that live there must survive both freezing winds and a constant shortage of liquid water."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.parts(id,section_id,name,display_order,metadata) values('69e95083-ab5a-40e1-94d4-f5afda0ef798','482d51fe-11f1-4a08-a5d3-8ca3de98dfb1','Complete the Words',8,'{"toefl_task":"complete_the_words"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('85e58853-b471-4e11-b999-d38333354c82','69e95083-ab5a-40e1-94d4-f5afda0ef798','question_complete_words','{"prompt":"Fill in the missing letters in the paragraph.","text":"Urban planners increasingly recognize that the design of public spaces shapes how residents interact. Wide {{1}}, shaded {{2}}, and {{3}} plazas {{4}} people {{5}} linger, {{6}} lingering {{7}} opportunities {{8}} casual {{9}} between {{10}} who might otherwise remain strangers. In contrast, neighborhoods dominated by fast roads and large parking areas tend to discourage walking, which reduces these informal encounters. Over time, such differences may influence not only physical health but also the level of trust that residents feel toward one another.","blanks":[{"id":"1","stem":"side","length":5},{"id":"2","stem":"ben","length":4},{"id":"3","stem":"sm","length":3},{"id":"4","stem":"enco","length":5},{"id":"5","stem":"t","length":1},{"id":"6","stem":"a","length":2},{"id":"7","stem":"cre","length":4},{"id":"8","stem":"f","length":2},{"id":"9","stem":"conver","length":7},{"id":"10","stem":"neig","length":5}],"topic":"urban studies"}'::jsonb,1,'{"toefl_task":"complete_the_words","original_slug":"cw-practice-8","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('85e58853-b471-4e11-b999-d38333354c82','{"blanks":{"1":"walks","2":"ches","3":"all","4":"urage","5":"o","6":"nd","7":"ates","8":"or","9":"sations","10":"hbors"},"stems":{"1":"side","2":"ben","3":"sm","4":"enco","5":"t","6":"a","7":"cre","8":"f","9":"conver","10":"neig"},"words":{"1":"sidewalks","2":"benches","3":"small","4":"encourage","5":"to","6":"and","7":"creates","8":"for","9":"conversations","10":"neighbors"}}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Full paragraph: Urban planners increasingly recognize that the design of public spaces shapes how residents interact. Wide sidewalks, shaded benches, and small plazas encourage people to linger, and lingering creates opportunities for casual conversations between neighbors who might otherwise remain strangers. In contrast, neighborhoods dominated by fast roads and large parking areas tend to discourage walking, which reduces these informal encounters. Over time, such differences may influence not only physical health but also the level of trust that residents feel toward one another."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.parts(id,section_id,name,display_order,metadata) values('60de8c9e-6aa8-4c44-9ef4-e2044d8e84f3','482d51fe-11f1-4a08-a5d3-8ca3de98dfb1','Complete the Words',9,'{"toefl_task":"complete_the_words"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('0bd58db6-3bf3-47fe-9b5d-a97f89cd3475','60de8c9e-6aa8-4c44-9ef4-e2044d8e84f3','question_complete_words','{"prompt":"Fill in the missing letters in the paragraph.","text":"Some plants have evolved remarkable strategies to defend themselves against hungry insects. Rather {{1}} relying {{2}} on {{3}} or {{4}} chemicals, {{5}} species {{6}} particular {{7}} when {{8}} leaves {{9}} damaged. {{10}} airborne signals attract predatory insects that feed on the attackers, effectively recruiting bodyguards from the surrounding environment. Neighboring plants may also detect the scents and begin producing protective compounds before they themselves are attacked. Such interactions reveal that plants respond to their surroundings in ways that are far more active than once assumed.","blanks":[{"id":"1","stem":"th","length":2},{"id":"2","stem":"on","length":2},{"id":"3","stem":"tho","length":3},{"id":"4","stem":"bit","length":3},{"id":"5","stem":"cer","length":4},{"id":"6","stem":"rel","length":4},{"id":"7","stem":"sce","length":3},{"id":"8","stem":"th","length":3},{"id":"9","stem":"a","length":2},{"id":"10","stem":"Th","length":3}],"topic":"ecology"}'::jsonb,1,'{"toefl_task":"complete_the_words","original_slug":"cw-practice-9","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('0bd58db6-3bf3-47fe-9b5d-a97f89cd3475','{"blanks":{"1":"an","2":"ly","3":"rns","4":"ter","5":"tain","6":"ease","7":"nts","8":"eir","9":"re","10":"ese"},"stems":{"1":"th","2":"on","3":"tho","4":"bit","5":"cer","6":"rel","7":"sce","8":"th","9":"a","10":"th"},"words":{"1":"than","2":"only","3":"thorns","4":"bitter","5":"certain","6":"release","7":"scents","8":"their","9":"are","10":"These"}}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Full paragraph: Some plants have evolved remarkable strategies to defend themselves against hungry insects. Rather than relying only on thorns or bitter chemicals, certain species release particular scents when their leaves are damaged. These airborne signals attract predatory insects that feed on the attackers, effectively recruiting bodyguards from the surrounding environment. Neighboring plants may also detect the scents and begin producing protective compounds before they themselves are attacked. Such interactions reveal that plants respond to their surroundings in ways that are far more active than once assumed."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.parts(id,section_id,name,display_order,metadata) values('4777883c-b9cf-4c7c-95d7-f7ca9cd21f69','482d51fe-11f1-4a08-a5d3-8ca3de98dfb1','Complete the Words',10,'{"toefl_task":"complete_the_words"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('e5589580-8b75-4c6b-a4a9-c3d50342e29e','4777883c-b9cf-4c7c-95d7-f7ca9cd21f69','question_complete_words','{"prompt":"Fill in the missing letters in the paragraph.","text":"The development of portable paint tubes transformed the practice of landscape painting. Previously, {{1}} had {{2}} grind {{3}} and {{4}} them {{5}} oil {{6}} their {{7}}, a {{8}} that {{9}} working {{10}} difficult and inconvenient. Once paint could be stored in sealed metal containers, painters were able to carry a full range of colors into fields, forests, and coastal villages. This freedom encouraged them to observe changing light directly, and many began to favor quick, visible brushstrokes over the smooth finish that academic traditions had long demanded.","blanks":[{"id":"1","stem":"art","length":4},{"id":"2","stem":"t","length":1},{"id":"3","stem":"pigm","length":4},{"id":"4","stem":"m","length":2},{"id":"5","stem":"wi","length":2},{"id":"6","stem":"i","length":1},{"id":"7","stem":"stu","length":4},{"id":"8","stem":"pro","length":4},{"id":"9","stem":"ma","length":2},{"id":"10","stem":"outd","length":4}],"topic":"art history"}'::jsonb,1,'{"toefl_task":"complete_the_words","original_slug":"cw-practice-10","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('e5589580-8b75-4c6b-a4a9-c3d50342e29e','{"blanks":{"1":"ists","2":"o","3":"ents","4":"ix","5":"th","6":"n","7":"dios","8":"cess","9":"de","10":"oors"},"stems":{"1":"art","2":"t","3":"pigm","4":"m","5":"wi","6":"i","7":"stu","8":"pro","9":"ma","10":"outd"},"words":{"1":"artists","2":"to","3":"pigments","4":"mix","5":"with","6":"in","7":"studios","8":"process","9":"made","10":"outdoors"}}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Full paragraph: The development of portable paint tubes transformed the practice of landscape painting. Previously, artists had to grind pigments and mix them with oil in their studios, a process that made working outdoors difficult and inconvenient. Once paint could be stored in sealed metal containers, painters were able to carry a full range of colors into fields, forests, and coastal villages. This freedom encouraged them to observe changing light directly, and many began to favor quick, visible brushstrokes over the smooth finish that academic traditions had long demanded."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.sections(id,experience_id,name,display_order,metadata) values('7756ed55-d56e-4ccd-b0bc-94204eea3639','8e65adde-0a8f-4605-975d-f975838a4991','Read in Daily Life',2,'{"format":"toefl-2026","type":"reading","practice_task":"read_daily_life","duration_seconds":1500,"duration_mode":"fixed","item_sets":10}'::jsonb) on conflict (id) do nothing;
insert into public.parts(id,section_id,name,display_order,metadata) values('05bbd477-6263-427e-b2af-050d199f1908','7756ed55-d56e-4ccd-b0bc-94204eea3639','Read in Daily Life',1,'{"toefl_task":"read_daily_life"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('be525498-c5b6-47e4-92d9-c9389300b027','05bbd477-6263-427e-b2af-050d199f1908','reading_passage','{"toefl_stimulus":"daily_life","format":"schedule","title":"Read a schedule.","heading":"Campus Shuttle: Weekday Timetable","text":"The shuttle does not run on weekends or public holidays. Show your student ID card when you board.","table":{"headers":["Stop","Morning","Midday","Evening"],"rows":[["Main Gate","7:30","12:00","17:30"],["Library","7:40","12:10","17:40"],["Sports Center","7:50","12:20","17:50"],["North Dorms","8:05","12:35","18:05"]]}}'::jsonb,1,'{"original_slug":"rdl-practice-1","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","toefl_stimulus":"read_daily_life"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('b8100de4-9419-4f67-822f-abcc3fbacca7','05bbd477-6263-427e-b2af-050d199f1908','question_single_choice','{"prompt":"When does the evening shuttle reach the Sports Center?","options":[{"id":"A","label":"17:30"},{"id":"B","label":"17:40"},{"id":"C","label":"18:05"},{"id":"D","label":"17:50"}]}'::jsonb,2,'{"toefl_task":"read_daily_life","original_slug":"rdl-practice-1","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":1}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('b8100de4-9419-4f67-822f-abcc3fbacca7','{"option_id":"D"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"In the Evening column, the Sports Center row shows 17:50, so D is correct. 17:30 is the Main Gate time (A), 17:40 is the Library time (B) and 18:05 is the North Dorms time (C)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('3da42b39-213e-443e-bf2c-ad6e4f2b8ab9','05bbd477-6263-427e-b2af-050d199f1908','question_single_choice','{"prompt":"What must riders do to use the shuttle?","options":[{"id":"A","label":"Buy a ticket from the driver"},{"id":"B","label":"Book a seat one day in advance"},{"id":"C","label":"Show a student ID card"},{"id":"D","label":"Board only at the Main Gate"}]}'::jsonb,3,'{"toefl_task":"read_daily_life","original_slug":"rdl-practice-1","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":2}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('3da42b39-213e-443e-bf2c-ad6e4f2b8ab9','{"option_id":"C"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The note says to show your student ID card when you board, so C is correct. Tickets (A) and bookings (B) are not mentioned, and the timetable lists four stops where riders can board, not only the Main Gate (D)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.parts(id,section_id,name,display_order,metadata) values('bf05107b-bc13-4753-966c-220dc4a65a67','7756ed55-d56e-4ccd-b0bc-94204eea3639','Read in Daily Life',2,'{"toefl_task":"read_daily_life"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('d07c7103-4dcb-4365-9174-136a7eee2f26','bf05107b-bc13-4753-966c-220dc4a65a67','reading_passage','{"toefl_stimulus":"daily_life","format":"advertisement","title":"Read an advertisement.","heading":"Room Available: Share a Quiet House Near Campus","text":"Friendly two-person household looking for a third housemate from September 1. The room is furnished (bed, desk, wardrobe) and gets lots of morning sun. Rent is $520 a month, utilities and internet included. The house is a 10-minute walk from the east side of campus and right next to a grocery store.\n\nWe''re both graduate students, so we''re looking for someone who is tidy and keeps the noise down on weeknights. Sorry, no pets: one of us is allergic. Weekend get-togethers are welcome, though!\n\nInterested? Send a short message about yourself to arrange a viewing.\nPhone: 555-0147"}'::jsonb,1,'{"original_slug":"rdl-practice-2","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","toefl_stimulus":"read_daily_life"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('2c6676c5-d5fa-4157-b26a-98a8f9d6021f','bf05107b-bc13-4753-966c-220dc4a65a67','question_single_choice','{"prompt":"What is included in the rent?","options":[{"id":"A","label":"Internet service"},{"id":"B","label":"Weekly cleaning"},{"id":"C","label":"A parking space"},{"id":"D","label":"Grocery delivery"}]}'::jsonb,2,'{"toefl_task":"read_daily_life","original_slug":"rdl-practice-2","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":1}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('2c6676c5-d5fa-4157-b26a-98a8f9d6021f','{"option_id":"A"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The ad says rent includes ''utilities and internet'', so A is correct. Cleaning (B) and parking (C) are not mentioned, and the grocery store is only described as being nearby (D)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('f889b12f-4671-4178-8ddf-ae4129998b9a','bf05107b-bc13-4753-966c-220dc4a65a67','question_single_choice','{"prompt":"Why are pets not allowed?","options":[{"id":"A","label":"The landlord does not permit them."},{"id":"B","label":"The house is too small."},{"id":"C","label":"One of the current residents has an allergy."},{"id":"D","label":"The neighbors have complained."}]}'::jsonb,3,'{"toefl_task":"read_daily_life","original_slug":"rdl-practice-2","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":2}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('f889b12f-4671-4178-8ddf-ae4129998b9a','{"option_id":"C"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The ad says ''no pets: one of us is allergic'', so C is correct. A landlord (A), the size of the house (B) and neighbors (D) are never mentioned."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('3e6c6ebe-91f3-4cbe-9598-01e31716f1bb','bf05107b-bc13-4753-966c-220dc4a65a67','question_single_choice','{"prompt":"What kind of housemate are the residents most likely hoping to find?","options":[{"id":"A","label":"Someone who wants to host large parties on weeknights"},{"id":"B","label":"Someone who is considerate about noise during the week"},{"id":"C","label":"Someone who works night shifts"},{"id":"D","label":"Someone who can bring their own furniture"}]}'::jsonb,4,'{"toefl_task":"read_daily_life","original_slug":"rdl-practice-2","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":3}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('3e6c6ebe-91f3-4cbe-9598-01e31716f1bb','{"option_id":"B"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"They want someone tidy who ''keeps the noise down on weeknights'', so B is correct. A contradicts this request. Night shifts (C) are not mentioned, and the room is already furnished, so D is unnecessary."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.parts(id,section_id,name,display_order,metadata) values('b2f101a3-f1ae-41fb-a8d7-7a5f8a49415d','7756ed55-d56e-4ccd-b0bc-94204eea3639','Read in Daily Life',3,'{"toefl_task":"read_daily_life"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('db9b7be7-7de9-46c1-a023-e6858da9f440','b2f101a3-f1ae-41fb-a8d7-7a5f8a49415d','reading_passage','{"toefl_stimulus":"daily_life","format":"receipt","title":"Read a receipt.","heading":"GreenLeaf Hardware: Receipt","text":"Date: 14 May    Time: 16:22\nPaid by: card\nReturns accepted within 30 days with this receipt.","table":{"headers":["Item","Qty","Price"],"rows":[["Paint brush set","1","$8.99"],["Wall paint, white (1 gallon)","2","$45.98"],["Masking tape","3","$6.00"],["Subtotal","","$60.97"],["Member discount (10%)","","-$6.10"],["Total","","$54.87"]]}}'::jsonb,1,'{"original_slug":"rdl-practice-3","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","toefl_stimulus":"read_daily_life"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('c6220800-7e3d-4231-9a1f-16ce70e9d8ae','b2f101a3-f1ae-41fb-a8d7-7a5f8a49415d','question_single_choice','{"prompt":"How many rolls of masking tape did the customer buy?","options":[{"id":"A","label":"1"},{"id":"B","label":"2"},{"id":"C","label":"3"},{"id":"D","label":"6"}]}'::jsonb,2,'{"toefl_task":"read_daily_life","original_slug":"rdl-practice-3","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":1}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('c6220800-7e3d-4231-9a1f-16ce70e9d8ae','{"option_id":"C"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The Qty column shows 3 for masking tape, so C is correct. 1 is the quantity of brush sets (A), 2 is the number of paint cans (B), and 6 is the price in dollars, not the quantity (D)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('69b39732-72f1-4261-a559-065b9645ceab','b2f101a3-f1ae-41fb-a8d7-7a5f8a49415d','question_single_choice','{"prompt":"What is true about this purchase?","options":[{"id":"A","label":"The customer paid in cash."},{"id":"B","label":"The items cannot be returned."},{"id":"C","label":"The paint was the cheapest item."},{"id":"D","label":"The customer received a discount."}]}'::jsonb,3,'{"toefl_task":"read_daily_life","original_slug":"rdl-practice-3","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":2}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('69b39732-72f1-4261-a559-065b9645ceab','{"option_id":"D"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The receipt shows a 10% member discount of $6.10, so D is correct. The customer paid by card (A), returns are accepted within 30 days (B), and the paint was the most expensive item, not the cheapest (C)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.parts(id,section_id,name,display_order,metadata) values('7e275ac0-bc33-4fca-b99e-8aa2999167c5','7756ed55-d56e-4ccd-b0bc-94204eea3639','Read in Daily Life',4,'{"toefl_task":"read_daily_life"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('8cc742f7-94b9-4ea3-b472-e7f7d61f1800','7e275ac0-bc33-4fca-b99e-8aa2999167c5','reading_passage','{"toefl_stimulus":"daily_life","format":"email","title":"Read an email.","heading":null,"text":"Hi all,\n\nJust a heads-up before Saturday. The delivery truck that usually arrives Friday night has been pushed back to Saturday morning, so the first hour of our shift will be pretty hectic. If you can come in at 8:30 instead of 9:00, I''d really appreciate it, but no pressure if that doesn''t work for you.\n\nAlso, a reminder that closed-toe shoes are a must on the warehouse floor. Last week a couple of people showed up in sandals and had to sit out the sorting, which was a shame.\n\nFinally, we''re short on drivers for the afternoon home deliveries. If you have a valid license and are comfortable driving a van, reply to this email and I''ll add you to the roster.\n\nCheers,\nMarcus","email":{"from":"Marcus Ojo, Volunteer Coordinator, Eastside Food Bank","to":"Weekend volunteer team","subject":"Saturday sorting shift: heads-up"}}'::jsonb,1,'{"original_slug":"rdl-practice-4","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","toefl_stimulus":"read_daily_life"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('07740d17-4b7d-4a13-9944-ff5442d6ad3e','7e275ac0-bc33-4fca-b99e-8aa2999167c5','question_single_choice','{"prompt":"What is the main reason Marcus wrote this email?","options":[{"id":"A","label":"To cancel Saturday''s shift"},{"id":"B","label":"To prepare volunteers for changes and needs related to Saturday"},{"id":"C","label":"To complain about volunteers who arrived late last week"},{"id":"D","label":"To announce that the food bank has hired a new delivery company"}]}'::jsonb,2,'{"toefl_task":"read_daily_life","original_slug":"rdl-practice-4","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":1}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('07740d17-4b7d-4a13-9944-ff5442d6ad3e','{"option_id":"B"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Marcus explains the delayed truck, reminds volunteers about shoes and asks for drivers, all for Saturday, so B is correct. The shift is still happening (A). Last week''s problem was sandals, not lateness (C), and no new company is mentioned (D)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('834b47bb-32f6-4df2-8200-e9bae6efd144','7e275ac0-bc33-4fca-b99e-8aa2999167c5','question_single_choice','{"prompt":"What does Marcus mean when he writes ''no pressure if that doesn''t work for you''?","options":[{"id":"A","label":"Coming in early is optional."},{"id":"B","label":"The work will be easy."},{"id":"C","label":"Volunteers must explain why they cannot come early."},{"id":"D","label":"The shift has been shortened."}]}'::jsonb,3,'{"toefl_task":"read_daily_life","original_slug":"rdl-practice-4","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":2}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('834b47bb-32f6-4df2-8200-e9bae6efd144','{"option_id":"A"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"''No pressure'' means volunteers should not feel forced, so arriving at 8:30 is optional (A). Marcus actually says the first hour will be ''hectic'', so B is wrong. He asks for no explanations (C), and the shift is not shortened (D)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('f7a31f40-0f5d-439e-b49a-6756ac17d8b8','7e275ac0-bc33-4fca-b99e-8aa2999167c5','question_single_choice','{"prompt":"What can be inferred about the volunteers who wore sandals last week?","options":[{"id":"A","label":"They were asked to drive vans instead."},{"id":"B","label":"They left before the truck arrived."},{"id":"C","label":"They were given shoes by the food bank."},{"id":"D","label":"They could not take part in the sorting."}]}'::jsonb,4,'{"toefl_task":"read_daily_life","original_slug":"rdl-practice-4","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":3}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('f7a31f40-0f5d-439e-b49a-6756ac17d8b8','{"option_id":"D"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"To ''sit out'' an activity means not to participate, so they could not help with sorting (D). Driving (A), leaving early (B) and receiving shoes (C) are not mentioned in connection with these volunteers."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.parts(id,section_id,name,display_order,metadata) values('cae5f8b1-0f8e-401e-9a76-64b0402d9ac5','7756ed55-d56e-4ccd-b0bc-94204eea3639','Read in Daily Life',5,'{"toefl_task":"read_daily_life"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('26ace097-eb28-4cb5-a4e6-507c9aae6aa3','cae5f8b1-0f8e-401e-9a76-64b0402d9ac5','reading_passage','{"toefl_stimulus":"daily_life","format":"text_messages","title":"Read a chain of text messages.","heading":null,"text":"","messages":[{"sender":"Sam","time":"21:14","text":"Did you take the laundry out of the machine? It''s been sitting there since this afternoon."},{"sender":"Ji-woo","time":"21:20","text":"Oops, totally slipped my mind. I''m at the library till 10."},{"sender":"Sam","time":"21:21","text":"No worries, I''ll hang it up. But we''re out of detergent btw."},{"sender":"Ji-woo","time":"21:22","text":"My bad. I''ll grab some on my way home. Anything else we need?"},{"sender":"Sam","time":"21:23","text":"Milk and bread, if the shop''s still open."},{"sender":"Ji-woo","time":"21:24","text":"On it."}]}'::jsonb,1,'{"original_slug":"rdl-practice-5","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","toefl_stimulus":"read_daily_life"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('3e4c3969-0828-41fb-b6a1-80c7c5198ff7','cae5f8b1-0f8e-401e-9a76-64b0402d9ac5','question_single_choice','{"prompt":"What does Ji-woo mean when she writes ''totally slipped my mind''?","options":[{"id":"A","label":"She did the laundry incorrectly."},{"id":"B","label":"She was too tired to do it."},{"id":"C","label":"She forgot to do it."},{"id":"D","label":"She did not know how to do it."}]}'::jsonb,2,'{"toefl_task":"read_daily_life","original_slug":"rdl-practice-5","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":1}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('3e4c3969-0828-41fb-b6a1-80c7c5198ff7','{"option_id":"C"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"If something ''slips your mind'', you forget it, so C is correct. Ji-woo says nothing about doing it badly (A), being tired (B) or not knowing how (D)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('d04776e6-e400-4e8e-b244-364ef450c451','cae5f8b1-0f8e-401e-9a76-64b0402d9ac5','question_single_choice','{"prompt":"What will Ji-woo probably do on her way home?","options":[{"id":"A","label":"Buy detergent and possibly some food"},{"id":"B","label":"Hang up the laundry"},{"id":"C","label":"Return books to the library"},{"id":"D","label":"Meet Sam at the shop"}]}'::jsonb,3,'{"toefl_task":"read_daily_life","original_slug":"rdl-practice-5","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":2}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('d04776e6-e400-4e8e-b244-364ef450c451','{"option_id":"A"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Ji-woo says she will ''grab some'' detergent, and when Sam adds milk and bread she replies ''On it'', so A is correct. Sam will hang up the laundry (B). Returning books (C) and meeting Sam (D) are not mentioned."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.parts(id,section_id,name,display_order,metadata) values('53a62ab2-ab5c-417c-b8df-098d42b2fc35','7756ed55-d56e-4ccd-b0bc-94204eea3639','Read in Daily Life',6,'{"toefl_task":"read_daily_life"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('d4ed90de-e1d8-406d-85c5-f07c259692d7','53a62ab2-ab5c-417c-b8df-098d42b2fc35','reading_passage','{"toefl_stimulus":"daily_life","format":"form","title":"Read a form.","heading":"Riverside Community Center: Class Registration Form","text":"Participant name: Amara Okafor\nAge group: Adult (18+)\nClass: Beginner Pottery (Tuesdays, 18:00-20:00)\nStart date: 7 October\nNumber of sessions: 8\nFee: $96 (materials included)\nPayment: [ ] Full payment now   [x] Two installments\nRiverside resident: [x] Yes   [ ] No\nEmergency contact: Chidi Okafor (brother)\n\nNote: Residents receive a 15% discount, applied at the second payment. Classes with fewer than 5 registrations by 30 September will be canceled and fully refunded."}'::jsonb,1,'{"original_slug":"rdl-practice-6","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","toefl_stimulus":"read_daily_life"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('ee9b1cd5-103d-4f84-8683-9f4fe0a868eb','53a62ab2-ab5c-417c-b8df-098d42b2fc35','question_single_choice','{"prompt":"On which day does Amara''s class meet?","options":[{"id":"A","label":"Monday"},{"id":"B","label":"Wednesday"},{"id":"C","label":"Saturday"},{"id":"D","label":"Tuesday"}]}'::jsonb,2,'{"toefl_task":"read_daily_life","original_slug":"rdl-practice-6","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":1}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('ee9b1cd5-103d-4f84-8683-9f4fe0a868eb','{"option_id":"D"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The form lists the class as ''Beginner Pottery (Tuesdays, 18:00-20:00)'', so D is correct. Monday (A), Wednesday (B) and Saturday (C) do not appear on the form."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('f4c6a19f-f523-4281-8b1c-49b9e5b846df','53a62ab2-ab5c-417c-b8df-098d42b2fc35','question_single_choice','{"prompt":"How did Amara choose to pay?","options":[{"id":"A","label":"In full when registering"},{"id":"B","label":"In two separate payments"},{"id":"C","label":"By having her brother pay"},{"id":"D","label":"After the class ends"}]}'::jsonb,3,'{"toefl_task":"read_daily_life","original_slug":"rdl-practice-6","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":2}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('f4c6a19f-f523-4281-8b1c-49b9e5b846df','{"option_id":"B"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The box marked with an x is ''Two installments'', so B is correct. ''Full payment now'' is not marked (A). Her brother is only her emergency contact (C), and nothing says she pays after the class (D)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('b7c7e915-3e60-4619-a651-441c7f0d02b9','53a62ab2-ab5c-417c-b8df-098d42b2fc35','question_single_choice','{"prompt":"What will happen if only three people register by 30 September?","options":[{"id":"A","label":"The class will move to a smaller room."},{"id":"B","label":"The fee will be raised."},{"id":"C","label":"Amara will get all of her money back."},{"id":"D","label":"Residents will receive a larger discount."}]}'::jsonb,4,'{"toefl_task":"read_daily_life","original_slug":"rdl-practice-6","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":3}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('b7c7e915-3e60-4619-a651-441c7f0d02b9','{"option_id":"C"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Classes with fewer than five registrations by 30 September are canceled and ''fully refunded'', so C is correct. The form does not mention changing rooms (A), raising the fee (B) or increasing the discount (D)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.parts(id,section_id,name,display_order,metadata) values('a2b67360-430a-479a-9c80-932d0223d57c','7756ed55-d56e-4ccd-b0bc-94204eea3639','Read in Daily Life',7,'{"toefl_task":"read_daily_life"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('f64e70e5-95be-4810-9057-a34f5421baab','a2b67360-430a-479a-9c80-932d0223d57c','reading_passage','{"toefl_stimulus":"daily_life","format":"invoice","title":"Read an invoice.","heading":"Invoice 2219: Northfield Print and Design","text":"Bill to: Lakeside Youth Theater\nInvoice date: 2 November\nPayment due: within 21 days of the invoice date\nA late fee of 5% is added to any balance unpaid after the due date. A deposit of $150 was received on 15 October.","table":{"headers":["Service","Quantity","Amount"],"rows":[["Poster design","1","$180.00"],["Poster printing (A2)","40","$120.00"],["Program booklets","200","$250.00"],["Total charges","","$550.00"],["Less deposit","","-$150.00"],["Balance due","","$400.00"]]}}'::jsonb,1,'{"original_slug":"rdl-practice-7","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","toefl_stimulus":"read_daily_life"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('1117ca23-291c-4f7d-8345-f54384032141','a2b67360-430a-479a-9c80-932d0223d57c','question_single_choice','{"prompt":"By what date must the theater pay to avoid a late fee?","options":[{"id":"A","label":"15 October"},{"id":"B","label":"2 November"},{"id":"C","label":"23 November"},{"id":"D","label":"30 November"}]}'::jsonb,2,'{"toefl_task":"read_daily_life","original_slug":"rdl-practice-7","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":1}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('1117ca23-291c-4f7d-8345-f54384032141','{"option_id":"C"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Payment is due within 21 days of the 2 November invoice date, which is 23 November, so C is correct. 15 October is when the deposit was paid (A), 2 November is the invoice date itself (B), and 30 November is later than the deadline (D)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('e15bc728-4236-445b-b581-37452e541666','a2b67360-430a-479a-9c80-932d0223d57c','question_single_choice','{"prompt":"If the theater pays the remaining balance one week after the due date, how much will it owe?","options":[{"id":"A","label":"$400.00"},{"id":"B","label":"$420.00"},{"id":"C","label":"$550.00"},{"id":"D","label":"$577.50"}]}'::jsonb,3,'{"toefl_task":"read_daily_life","original_slug":"rdl-practice-7","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":2}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('e15bc728-4236-445b-b581-37452e541666','{"option_id":"B"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The unpaid balance is $400, and a 5% late fee adds $20, giving $420 (B). A ignores the late fee. C is the total before the deposit, and D adds 5% to the total charges instead of to the remaining balance."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.parts(id,section_id,name,display_order,metadata) values('e42c0b56-ed6b-47cb-8a72-855545db6cc9','7756ed55-d56e-4ccd-b0bc-94204eea3639','Read in Daily Life',8,'{"toefl_task":"read_daily_life"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('c18dec70-d67f-4381-bd47-58b2f7897428','e42c0b56-ed6b-47cb-8a72-855545db6cc9','reading_passage','{"toefl_stimulus":"daily_life","format":"schedule","title":"Read a schedule.","heading":"Regional Teaching Conference: Day 2 (Saturday)","text":"Sessions marked * require advance registration because space is limited. Lunch is served only to participants wearing a conference badge. Room changes will be posted on the screen in the lobby.","table":{"headers":["Time","Session","Room"],"rows":[["9:00-10:00","Keynote: Feedback That Students Actually Use","Main Hall"],["10:15-11:30","Workshop*: Designing Group Projects","Room 204"],["10:15-11:30","Panel: Teaching in Multilingual Classrooms","Main Hall"],["11:30-12:30","Lunch","Courtyard"],["12:30-13:45","Workshop*: Low-Cost Science Experiments","Lab B"],["14:00-15:00","Closing Discussion","Main Hall"]]}}'::jsonb,1,'{"original_slug":"rdl-practice-8","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","toefl_stimulus":"read_daily_life"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('1e3eee27-73eb-4893-9e74-d250454eb406','e42c0b56-ed6b-47cb-8a72-855545db6cc9','question_single_choice','{"prompt":"Which two sessions take place at the same time?","options":[{"id":"A","label":"The group projects workshop and the multilingual classrooms panel"},{"id":"B","label":"The keynote and the closing discussion"},{"id":"C","label":"Lunch and the science experiments workshop"},{"id":"D","label":"The panel and the closing discussion"}]}'::jsonb,2,'{"toefl_task":"read_daily_life","original_slug":"rdl-practice-8","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":1}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('1e3eee27-73eb-4893-9e74-d250454eb406','{"option_id":"A"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Both the group projects workshop and the multilingual classrooms panel run from 10:15 to 11:30, so A is correct. The keynote and closing discussion are at 9:00 and 14:00 (B). Lunch ends at 12:30, when the science workshop starts (C), and the panel ends long before the closing discussion (D)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('e67712c4-e372-4b46-8179-4e3100f4bfc3','e42c0b56-ed6b-47cb-8a72-855545db6cc9','question_single_choice','{"prompt":"A teacher who has not registered in advance wants to attend a session after lunch. Which session can she attend?","options":[{"id":"A","label":"Designing Group Projects"},{"id":"B","label":"Low-Cost Science Experiments"},{"id":"C","label":"Feedback That Students Actually Use"},{"id":"D","label":"Closing Discussion"}]}'::jsonb,3,'{"toefl_task":"read_daily_life","original_slug":"rdl-practice-8","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":2}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('e67712c4-e372-4b46-8179-4e3100f4bfc3','{"option_id":"D"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The Closing Discussion is after lunch and has no asterisk, so no registration is needed (D). The science workshop is after lunch but requires registration (B). The group projects workshop also requires registration and is before lunch (A), and the keynote is before lunch (C)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('1396015d-485d-4465-9ad0-f1de9ef563d3','e42c0b56-ed6b-47cb-8a72-855545db6cc9','question_single_choice','{"prompt":"Where should participants look to find out whether a session has moved to a different room?","options":[{"id":"A","label":"In the courtyard"},{"id":"B","label":"On a screen in the lobby"},{"id":"C","label":"On their conference badge"},{"id":"D","label":"In Room 204"}]}'::jsonb,4,'{"toefl_task":"read_daily_life","original_slug":"rdl-practice-8","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":3}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('1396015d-485d-4465-9ad0-f1de9ef563d3','{"option_id":"B"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The schedule says room changes will be posted on the screen in the lobby, so B is correct. The courtyard is where lunch is served (A), badges are needed for lunch (C), and Room 204 is just one session room (D)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.parts(id,section_id,name,display_order,metadata) values('c2d957e7-71e9-45e6-94c6-03b80bf0957d','7756ed55-d56e-4ccd-b0bc-94204eea3639','Read in Daily Life',9,'{"toefl_task":"read_daily_life"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('a1bf7d6a-9cc2-4308-8aa6-a7653099adda','c2d957e7-71e9-45e6-94c6-03b80bf0957d','reading_passage','{"toefl_stimulus":"daily_life","format":"menu","title":"Read a menu.","heading":"Spice Route Food Truck: Today''s Menu","text":"Open 11:00-15:00 in the Central Park parking lot. Items marked (V) are vegetarian. Cash and card accepted.","table":{"headers":["Dish","Price"],"rows":[["Chicken rice bowl","$8"],["Lentil soup (V)","$5"],["Falafel wrap (V)","$7"],["Beef dumplings (6 pieces)","$6"],["Mango lassi (drink)","$3"]]}}'::jsonb,1,'{"original_slug":"rdl-practice-9","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","toefl_stimulus":"read_daily_life"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('4a2154b0-f386-45f8-b3d3-d0ac1b240627','c2d957e7-71e9-45e6-94c6-03b80bf0957d','question_single_choice','{"prompt":"Which of these items is marked as vegetarian?","options":[{"id":"A","label":"Chicken rice bowl"},{"id":"B","label":"Lentil soup"},{"id":"C","label":"Beef dumplings"},{"id":"D","label":"Mango lassi"}]}'::jsonb,2,'{"toefl_task":"read_daily_life","original_slug":"rdl-practice-9","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":1}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('4a2154b0-f386-45f8-b3d3-d0ac1b240627','{"option_id":"B"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Only the lentil soup and the falafel wrap have the (V) mark, and of these options only the lentil soup appears, so B is correct. The chicken bowl (A) and beef dumplings (C) contain meat, and the mango lassi (D) is not marked (V)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('18027bf2-ae13-4ac0-8937-fde6f575b097','c2d957e7-71e9-45e6-94c6-03b80bf0957d','question_single_choice','{"prompt":"When can customers buy food from the truck today?","options":[{"id":"A","label":"Before 11:00"},{"id":"B","label":"Only after 15:00"},{"id":"C","label":"In the evening"},{"id":"D","label":"Between 11:00 and 15:00"}]}'::jsonb,3,'{"toefl_task":"read_daily_life","original_slug":"rdl-practice-9","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":2}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('18027bf2-ae13-4ac0-8937-fde6f575b097','{"option_id":"D"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The truck is open from 11:00 to 15:00, so D is correct. It is not open before 11:00 (A), after 15:00 (B) or in the evening (C)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.parts(id,section_id,name,display_order,metadata) values('0db5b7e8-a27c-460b-a304-e3923aa9ab4a','7756ed55-d56e-4ccd-b0bc-94204eea3639','Read in Daily Life',10,'{"toefl_task":"read_daily_life"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('1c553cbb-03d1-47a8-a355-d05623abfe0a','0db5b7e8-a27c-460b-a304-e3923aa9ab4a','reading_passage','{"toefl_stimulus":"daily_life","format":"notice","title":"Read a notice.","heading":"Water Shut-Off: Maple Court Apartments","text":"To all residents of Buildings A and B:\n\nThe city will replace a section of the main water pipe on Wednesday, 12 June. Water will be turned off in both buildings from 9:00 a.m. to approximately 3:00 p.m. Building C will not be affected.\n\nWe recommend filling containers with drinking water the night before. Please avoid using washing machines and dishwashers on Tuesday night, since water pressure may drop.\n\nWhen the water comes back on, it may look cloudy for a few minutes. This is normal; simply run the cold tap until the water is clear.\n\nQuestions? Contact the building office at extension 210.\nMaple Court Management"}'::jsonb,1,'{"original_slug":"rdl-practice-10","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","toefl_stimulus":"read_daily_life"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('531bc69e-048e-43de-a4e6-2bf7c69e29c5','0db5b7e8-a27c-460b-a304-e3923aa9ab4a','question_single_choice','{"prompt":"Who is the notice mainly intended for?","options":[{"id":"A","label":"Residents of Buildings A and B"},{"id":"B","label":"Residents of Building C"},{"id":"C","label":"City pipe workers"},{"id":"D","label":"Building office staff"}]}'::jsonb,2,'{"toefl_task":"read_daily_life","original_slug":"rdl-practice-10","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":1}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('531bc69e-048e-43de-a4e6-2bf7c69e29c5','{"option_id":"A"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The notice is addressed ''To all residents of Buildings A and B'', whose water will be shut off, so A is correct. Building C ''will not be affected'' (B). City workers (C) and office staff (D) are mentioned but are not the audience."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('38655d40-0517-4215-860a-5ac9c5fb4ddc','0db5b7e8-a27c-460b-a304-e3923aa9ab4a','question_single_choice','{"prompt":"Why are residents asked not to use dishwashers on Tuesday night?","options":[{"id":"A","label":"The machines will be repaired."},{"id":"B","label":"The water pressure might be lower."},{"id":"C","label":"The water will be cloudy."},{"id":"D","label":"The machines would be too noisy."}]}'::jsonb,3,'{"toefl_task":"read_daily_life","original_slug":"rdl-practice-10","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":2}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('38655d40-0517-4215-860a-5ac9c5fb4ddc','{"option_id":"B"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The notice says to avoid these machines ''since water pressure may drop'', so B is correct. No repairs to machines are mentioned (A). Cloudy water is expected after the work, not on Tuesday night (C), and noise is not mentioned (D)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('6a200557-73f3-4637-a56f-252e53df0835','0db5b7e8-a27c-460b-a304-e3923aa9ab4a','question_single_choice','{"prompt":"What should residents do if their water looks cloudy after the work?","options":[{"id":"A","label":"Call the city immediately"},{"id":"B","label":"Stop using the water for a whole day"},{"id":"C","label":"Let the cold water run for a while"},{"id":"D","label":"Get water from Building C"}]}'::jsonb,4,'{"toefl_task":"read_daily_life","original_slug":"rdl-practice-10","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":3}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('6a200557-73f3-4637-a56f-252e53df0835','{"option_id":"C"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The notice says cloudy water is normal and to ''run the cold tap until the water is clear'', so C is correct. There is no need to call the city (A) or stop using water for a day (B), and Building C is only mentioned as unaffected (D)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.sections(id,experience_id,name,display_order,metadata) values('2ab7e64b-be14-4b3c-944c-a8a64e2a11b1','8e65adde-0a8f-4605-975d-f975838a4991','Read an Academic Passage',3,'{"format":"toefl-2026","type":"reading","practice_task":"read_academic_passage","duration_seconds":3000,"duration_mode":"fixed","item_sets":10}'::jsonb) on conflict (id) do nothing;
insert into public.parts(id,section_id,name,display_order,metadata) values('cd449b7d-4695-497b-8085-ead668f03ebd','2ab7e64b-be14-4b3c-944c-a8a64e2a11b1','Read an Academic Passage',1,'{"toefl_task":"read_academic_passage"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('d3126b80-d6b0-4a87-a1ac-2a4797aa80b2','cd449b7d-4695-497b-8085-ead668f03ebd','reading_passage','{"toefl_stimulus":"academic_passage","title":"Railways and the Standardization of Time","text":"Until the nineteenth century, most towns set their clocks by the sun. Noon was the moment when the sun stood highest in the sky, and because this moment arrives slightly later as one travels west, neighboring towns often kept times that differed by several minutes. For people who rarely traveled far, these small differences hardly mattered.\n\nThe spread of railways changed this situation dramatically. A train could pass through dozens of towns in a single day, and each station might display its own local time. Printed timetables became confusing, and passengers sometimes missed connections because they misunderstood which time a schedule referred to. More seriously, when trains shared a single track, an error of a few minutes could put two of them on a collision course.\n\nTo solve these problems, railway companies began adopting a common time for all their lines, usually based on the clock of a major city. Telegraph wires, which often ran beside the tracks, allowed the reference time to be sent quickly to distant stations. At first, many towns resisted, and some public clocks showed two sets of hands, one for local time and one for railway time. Gradually, however, the convenience of a shared standard won out.","subject":"history"}'::jsonb,1,'{"original_slug":"ap-practice-1","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","toefl_stimulus":"read_academic_passage"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('466d6ca5-8b3e-4b54-9cd7-b29a36f96599','cd449b7d-4695-497b-8085-ead668f03ebd','question_single_choice','{"prompt":"According to paragraph 1, why did neighboring towns keep slightly different times?","options":[{"id":"A","label":"Each town based its noon on the position of the sun."},{"id":"B","label":"Towns could not afford accurate clocks."},{"id":"C","label":"Local governments disagreed about the length of an hour."},{"id":"D","label":"Clocks were set according to train arrivals."}]}'::jsonb,2,'{"toefl_task":"read_academic_passage","original_slug":"ap-practice-1","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":1,"skill":"factual"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('466d6ca5-8b3e-4b54-9cd7-b29a36f96599','{"option_id":"A"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Towns set their clocks by the sun, and local noon arrives later farther west, so A is correct. The cost of clocks (B) and the length of an hour (C) are not mentioned, and setting clocks by trains (D) came later, with the railways."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('a3d83c34-2df6-4c35-a5ad-bb15395b465e','cd449b7d-4695-497b-8085-ead668f03ebd','question_single_choice','{"prompt":"The word ''dramatically'' in the passage is closest in meaning to","options":[{"id":"A","label":"theatrically"},{"id":"B","label":"temporarily"},{"id":"C","label":"greatly"},{"id":"D","label":"quietly"}]}'::jsonb,3,'{"toefl_task":"read_academic_passage","original_slug":"ap-practice-1","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":2,"skill":"vocabulary"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('a3d83c34-2df6-4c35-a5ad-bb15395b465e','{"option_id":"C"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Railways changed the situation ''dramatically'', that is, to a great degree, so C is correct. ''Theatrically'' (A) relates to drama on a stage, not to the size of a change. The change was lasting, not temporary (B), and ''quietly'' (D) does not fit a major change."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('bda32898-6da9-4442-81fe-5ace71dd7cd7','cd449b7d-4695-497b-8085-ead668f03ebd','question_single_choice','{"prompt":"What can be inferred about the public clocks with two sets of hands?","options":[{"id":"A","label":"They were installed by telegraph companies."},{"id":"B","label":"They reflected a period when both local time and railway time were in use."},{"id":"C","label":"They showed the time in two different countries."},{"id":"D","label":"They were designed for passengers who could not read timetables."}]}'::jsonb,4,'{"toefl_task":"read_academic_passage","original_slug":"ap-practice-1","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":3,"skill":"inference"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('bda32898-6da9-4442-81fe-5ace71dd7cd7','{"option_id":"B"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"These clocks showed local time and railway time at once while towns were still resisting the change, which suggests both systems were used during a transition (B). Telegraph companies (A), other countries (C) and passengers who could not read (D) are not mentioned."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('f8f9562f-a646-42b1-9398-bc6570a4d77b','cd449b7d-4695-497b-8085-ead668f03ebd','question_single_choice','{"prompt":"How is paragraph 3 related to paragraph 2?","options":[{"id":"A","label":"It gives further examples of the confusion described in paragraph 2."},{"id":"B","label":"It argues that the problems in paragraph 2 were exaggerated."},{"id":"C","label":"It describes the effects of railways on town populations."},{"id":"D","label":"It explains how the problems described in paragraph 2 were addressed."}]}'::jsonb,5,'{"toefl_task":"read_academic_passage","original_slug":"ap-practice-1","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":4,"skill":"relationship"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('f8f9562f-a646-42b1-9398-bc6570a4d77b','{"option_id":"D"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Paragraph 3 begins ''To solve these problems'' and describes the adoption of a common railway time, so D is correct. It describes a solution, not more confusion (A). It does not say the problems were exaggerated (B), and town populations are not discussed (C)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('029406c5-8645-4223-9495-35a65ad08048','cd449b7d-4695-497b-8085-ead668f03ebd','question_single_choice','{"prompt":"Why does the author mention trains that shared a single track?","options":[{"id":"A","label":"To show that railways were cheaper than other forms of transport"},{"id":"B","label":"To explain why telegraph wires ran beside the tracks"},{"id":"C","label":"To emphasize that time differences could create real danger"},{"id":"D","label":"To describe how passengers missed their connections"}]}'::jsonb,6,'{"toefl_task":"read_academic_passage","original_slug":"ap-practice-1","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":5,"skill":"purpose"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('029406c5-8645-4223-9495-35a65ad08048','{"option_id":"C"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The author says ''More seriously'' and explains that a few minutes'' error could cause a collision, showing that time differences could be dangerous (C). Cost (A) is not discussed. Telegraph wires are mentioned later for a different reason (B), and missed connections are a separate, less serious problem (D)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.parts(id,section_id,name,display_order,metadata) values('f169ad69-95ab-4e8f-9307-95e3e87d407f','2ab7e64b-be14-4b3c-944c-a8a64e2a11b1','Read an Academic Passage',2,'{"toefl_task":"read_academic_passage"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('6bcfb001-69b6-4137-a4e2-4ada2fdc64ea','f169ad69-95ab-4e8f-9307-95e3e87d407f','reading_passage','{"toefl_stimulus":"academic_passage","title":"Painting on Wet Walls","text":"A fresco is a painting made directly on a freshly plastered wall. The word comes from an Italian term meaning ''fresh'', and it describes the most demanding feature of the method: the artist must apply paint while the plaster is still damp. Pigments mixed only with water are brushed onto the surface, and as the plaster dries, a chemical reaction binds the color into the wall itself.\n\nBecause wet plaster stays workable for only a limited number of hours, painters divided large compositions into sections that could be completed in a single day. Each morning, an assistant spread a new patch of plaster just large enough for that day''s work. Careful observers can sometimes still see the faint seams where one day''s section meets the next, revealing the order in which a wall was painted.\n\nThe technique offered an important advantage: since the color becomes part of the wall, a well-made fresco can survive for centuries without peeling. Yet the method was unforgiving. Mistakes could not simply be painted over; the artist had to chip away the plaster and begin that section again. For this reason, fresco painters typically prepared detailed full-size drawings in advance and transferred the outlines to the wall before beginning.","subject":"art"}'::jsonb,1,'{"original_slug":"ap-practice-2","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","toefl_stimulus":"read_academic_passage"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('34166ea8-5682-4968-9317-42972b0e1719','f169ad69-95ab-4e8f-9307-95e3e87d407f','question_single_choice','{"prompt":"According to paragraph 1, what causes the color to become part of the wall?","options":[{"id":"A","label":"A layer of varnish applied after painting"},{"id":"B","label":"A chemical reaction that happens as the plaster dries"},{"id":"C","label":"Oil that is mixed with the pigments"},{"id":"D","label":"Heat from lamps placed near the wall"}]}'::jsonb,2,'{"toefl_task":"read_academic_passage","original_slug":"ap-practice-2","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":1,"skill":"factual"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('34166ea8-5682-4968-9317-42972b0e1719','{"option_id":"B"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The passage states that ''as the plaster dries, a chemical reaction binds the color into the wall'', so B is correct. Varnish (A) and lamps (D) are not mentioned, and the pigments are mixed ''only with water'', not oil (C)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('eb660985-584d-4a12-ba6c-89b273918f0d','f169ad69-95ab-4e8f-9307-95e3e87d407f','question_single_choice','{"prompt":"The word ''unforgiving'' in the passage is closest in meaning to","options":[{"id":"A","label":"allowing little room for error"},{"id":"B","label":"unfriendly toward assistants"},{"id":"C","label":"extremely slow"},{"id":"D","label":"very expensive"}]}'::jsonb,3,'{"toefl_task":"read_academic_passage","original_slug":"ap-practice-2","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":2,"skill":"vocabulary"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('eb660985-584d-4a12-ba6c-89b273918f0d','{"option_id":"A"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The next sentence explains that mistakes could not simply be painted over, so ''unforgiving'' means it allowed little room for error (A). The passage says nothing about how assistants were treated (B), and speed (C) and cost (D) are not the point of the sentence."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('edf0353f-319a-49d6-b942-2a64c0210429','f169ad69-95ab-4e8f-9307-95e3e87d407f','question_single_choice','{"prompt":"What can be inferred from paragraph 2 about the faint seams visible in some frescoes?","options":[{"id":"A","label":"They were added later to repair damage."},{"id":"B","label":"They show exactly where an artist made mistakes."},{"id":"C","label":"They were painted deliberately as decoration."},{"id":"D","label":"They can help experts work out how a painting was made."}]}'::jsonb,4,'{"toefl_task":"read_academic_passage","original_slug":"ap-practice-2","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":3,"skill":"inference"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('edf0353f-319a-49d6-b942-2a64c0210429','{"option_id":"D"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The seams reveal ''the order in which a wall was painted'', so they help experts reconstruct the process (D). They come from the daily patches of plaster, not from repairs (A) or decoration (C), and they mark day boundaries rather than mistakes (B)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('8078f226-63c6-4fb9-aa82-fa4984eca7b6','f169ad69-95ab-4e8f-9307-95e3e87d407f','question_single_choice','{"prompt":"What is the relationship between the mistakes described in paragraph 3 and the drawings prepared in advance?","options":[{"id":"A","label":"The drawings were made after the mistakes had been corrected."},{"id":"B","label":"The drawings caused most of the mistakes."},{"id":"C","label":"The drawings were a way to reduce the chance of costly mistakes."},{"id":"D","label":"The drawings and the mistakes are unrelated."}]}'::jsonb,5,'{"toefl_task":"read_academic_passage","original_slug":"ap-practice-2","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":4,"skill":"relationship"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('8078f226-63c6-4fb9-aa82-fa4984eca7b6','{"option_id":"C"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Because mistakes meant chipping away plaster, painters ''for this reason'' prepared drawings beforehand, so the drawings helped prevent errors (C). They were made before painting, not after (A). Nothing says they caused errors (B), and the phrase ''For this reason'' shows the two are connected (D)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('d14ff091-a1c9-4d5f-aae9-549c99dafdcb','f169ad69-95ab-4e8f-9307-95e3e87d407f','question_single_choice','{"prompt":"What is the main purpose of the passage?","options":[{"id":"A","label":"To explain how the fresco method works and what it demanded of artists"},{"id":"B","label":"To argue that frescoes are better than all other kinds of painting"},{"id":"C","label":"To describe the life of a famous fresco painter"},{"id":"D","label":"To compare Italian and non-Italian painting traditions"}]}'::jsonb,6,'{"toefl_task":"read_academic_passage","original_slug":"ap-practice-2","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":5,"skill":"purpose"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('d14ff091-a1c9-4d5f-aae9-549c99dafdcb','{"option_id":"A"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The passage describes the steps of fresco painting, its daily sections, its advantage and its difficulties, so A is correct. It mentions one advantage but does not claim frescoes are best (B). No individual painter is described (C), and the Italian word is mentioned only to explain the name (D)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.parts(id,section_id,name,display_order,metadata) values('8e1709d4-08e0-42d7-a310-ffb12a7a9308','2ab7e64b-be14-4b3c-944c-a8a64e2a11b1','Read an Academic Passage',3,'{"toefl_task":"read_academic_passage"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('85ab2867-c7de-4545-83d8-659beac1b193','8e1709d4-08e0-42d7-a310-ffb12a7a9308','reading_passage','{"toefl_stimulus":"academic_passage","title":"Why Stores Sell Some Items at a Loss","text":"Most businesses want to earn money on everything they sell. However, some stores sometimes sell certain products for less than they paid for them. A supermarket, for example, might sell eggs or milk at a very low price, even though it loses a little money on each carton. Products sold this way are called loss leaders.\n\nThe idea behind a loss leader is simple. The low price attracts customers into the store. Once they are inside, most shoppers do not buy only the cheap item. They also pick up bread, fruit, cleaning products, and other things they need. The store earns a profit on these extra items, and this profit is usually much larger than the small loss on the advertised product. Stores often choose items that people buy regularly, so that shoppers notice the good price and remember it.\n\nLoss leaders do not always work, however. Some shoppers, sometimes called ''cherry pickers'', visit several stores and buy only the items that are on sale. If too many customers behave this way, the store simply loses money. For this reason, some stores limit how many discounted items each customer can buy during a single visit.","subject":"business"}'::jsonb,1,'{"original_slug":"ap-practice-3","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","toefl_stimulus":"read_academic_passage"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('657d1b6d-2d24-4dee-9e62-045964d7969c','8e1709d4-08e0-42d7-a310-ffb12a7a9308','question_single_choice','{"prompt":"According to paragraph 2, how does a store make money with a loss leader?","options":[{"id":"A","label":"It raises the price of the item after a few weeks."},{"id":"B","label":"It sells the item only to its regular customers."},{"id":"C","label":"It earns profits on other products that customers buy."},{"id":"D","label":"It receives payments from the companies that make the item."}]}'::jsonb,2,'{"toefl_task":"read_academic_passage","original_slug":"ap-practice-3","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":1,"skill":"factual"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('657d1b6d-2d24-4dee-9e62-045964d7969c','{"option_id":"C"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Shoppers also buy other items, and ''the store earns a profit on these extra items'', so C is correct. Raising prices later (A), selling only to regular customers (B) and payments from producers (D) are not mentioned."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('117ac8d2-d988-49e0-a2bc-1f577f89195e','8e1709d4-08e0-42d7-a310-ffb12a7a9308','question_single_choice','{"prompt":"The word ''attracts'' in the passage is closest in meaning to","options":[{"id":"A","label":"warns"},{"id":"B","label":"confuses"},{"id":"C","label":"charges"},{"id":"D","label":"draws"}]}'::jsonb,3,'{"toefl_task":"read_academic_passage","original_slug":"ap-practice-3","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":2,"skill":"vocabulary"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('117ac8d2-d988-49e0-a2bc-1f577f89195e','{"option_id":"D"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The low price ''attracts customers into the store'', meaning it draws them in (D). Warning (A) or confusing (B) customers would not bring them into the store, and ''charges'' (C) means asking for payment."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('af5517f0-dddb-497a-ab0c-a5c75938a455','8e1709d4-08e0-42d7-a310-ffb12a7a9308','question_single_choice','{"prompt":"What can be inferred about the ''cherry pickers'' mentioned in paragraph 3?","options":[{"id":"A","label":"They make loss leaders less profitable for stores."},{"id":"B","label":"They usually shop at only one store."},{"id":"C","label":"They prefer to buy expensive products."},{"id":"D","label":"They are employees who choose the discounted items."}]}'::jsonb,4,'{"toefl_task":"read_academic_passage","original_slug":"ap-practice-3","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":3,"skill":"inference"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('af5517f0-dddb-497a-ab0c-a5c75938a455','{"option_id":"A"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Cherry pickers buy only sale items, so the store does not earn profits on extra purchases and can lose money (A). They visit ''several stores'' (B), they look for sale items rather than expensive ones (C), and they are described as shoppers, not employees (D)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('692a0671-62ae-4074-9437-5f1da34a5a96','8e1709d4-08e0-42d7-a310-ffb12a7a9308','question_single_choice','{"prompt":"How does paragraph 3 relate to paragraph 2?","options":[{"id":"A","label":"It gives more examples of items used as loss leaders."},{"id":"B","label":"It describes a problem with the strategy explained in paragraph 2."},{"id":"C","label":"It explains why eggs and milk are popular."},{"id":"D","label":"It repeats the main idea of paragraph 2 in simpler words."}]}'::jsonb,5,'{"toefl_task":"read_academic_passage","original_slug":"ap-practice-3","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":4,"skill":"relationship"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('692a0671-62ae-4074-9437-5f1da34a5a96','{"option_id":"B"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Paragraph 2 explains how loss leaders earn money, and paragraph 3 starts ''Loss leaders do not always work'', describing a weakness, so B is correct. It gives no new items (A), does not discuss eggs and milk (C), and adds a new idea rather than repeating one (D)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('6503caf6-429d-4311-b109-ca5ff73e2a97','8e1709d4-08e0-42d7-a310-ffb12a7a9308','question_single_choice','{"prompt":"Why does the author mention that some stores limit how many discounted items each customer can buy?","options":[{"id":"A","label":"To show that loss leaders are against the law"},{"id":"B","label":"To explain why stores choose eggs and milk"},{"id":"C","label":"To suggest that most shoppers dislike discounts"},{"id":"D","label":"To give an example of how stores protect themselves from losses"}]}'::jsonb,6,'{"toefl_task":"read_academic_passage","original_slug":"ap-practice-3","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":5,"skill":"purpose"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('6503caf6-429d-4311-b109-ca5ff73e2a97','{"option_id":"D"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The limit is introduced ''For this reason'', that is, to prevent cherry pickers from causing losses, so D is correct. Laws (A) are not mentioned, the choice of eggs and milk is explained elsewhere (B), and nothing suggests shoppers dislike discounts (C)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.parts(id,section_id,name,display_order,metadata) values('4a62cdf9-43e3-4e8d-bc1e-8167f6b0281e','2ab7e64b-be14-4b3c-944c-a8a64e2a11b1','Read an Academic Passage',4,'{"toefl_task":"read_academic_passage"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('b7c5e51f-228e-4b6d-b4fd-928198b9cda3','4a62cdf9-43e3-4e8d-bc1e-8167f6b0281e','reading_passage','{"toefl_stimulus":"academic_passage","title":"The Internal Clocks of Plants","text":"Anyone who watches certain plants over the course of a day may notice that their leaves rise in the morning and droop at night. It would be natural to assume that these movements are simply responses to changing light. Yet when such plants are moved into a room kept in constant darkness, the leaves continue to rise and fall on a roughly daily cycle for several days. This persistence indicates that the rhythm is generated within the plant itself.\n\nBiologists now know that plants, like animals, possess internal timekeeping systems built from interacting genes whose activity rises and falls in a regular pattern. These internal clocks allow a plant to anticipate dawn rather than merely react to it. A plant that begins producing the molecules needed for photosynthesis shortly before sunrise can start capturing energy as soon as light appears, gaining an advantage over a neighbor that waits.\n\nAn internal clock is useful, however, only if it stays synchronized with the actual environment. Because the timing of sunrise shifts across the seasons, plants continually reset their clocks using signals such as light and temperature. Experiments have shown that plants whose internal cycle matches the length of the external day grow larger and survive better than genetically altered plants whose cycles are noticeably longer or shorter.","subject":"life science"}'::jsonb,1,'{"original_slug":"ap-practice-4","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","toefl_stimulus":"read_academic_passage"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('d7b401c9-30bc-4bde-8d5a-95dfcb85bef9','4a62cdf9-43e3-4e8d-bc1e-8167f6b0281e','question_single_choice','{"prompt":"According to paragraph 3, what signals do plants use to reset their internal clocks?","options":[{"id":"A","label":"Soil moisture and wind"},{"id":"B","label":"Sounds made by animals"},{"id":"C","label":"Movements of their own leaves"},{"id":"D","label":"Light and temperature"}]}'::jsonb,2,'{"toefl_task":"read_academic_passage","original_slug":"ap-practice-4","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":1,"skill":"factual"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('d7b401c9-30bc-4bde-8d5a-95dfcb85bef9','{"option_id":"D"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Paragraph 3 says plants reset their clocks ''using signals such as light and temperature'', so D is correct. Soil moisture and wind (A) and animal sounds (B) are not mentioned, and leaf movements are a result of the clock, not a signal used to reset it (C)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('bc7b1e7c-f5ee-49a0-a928-5fd6fb68c4fa','4a62cdf9-43e3-4e8d-bc1e-8167f6b0281e','question_single_choice','{"prompt":"The word ''anticipate'' in the passage is closest in meaning to","options":[{"id":"A","label":"resist"},{"id":"B","label":"remember"},{"id":"C","label":"prepare for in advance"},{"id":"D","label":"slow down"}]}'::jsonb,3,'{"toefl_task":"read_academic_passage","original_slug":"ap-practice-4","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":2,"skill":"vocabulary"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('bc7b1e7c-f5ee-49a0-a928-5fd6fb68c4fa','{"option_id":"C"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The passage contrasts anticipating dawn with ''merely reacting'' to it, and gives the example of preparing molecules before sunrise, so ''anticipate'' means prepare for in advance (C). Resisting (A), remembering (B) and slowing down (D) do not fit this contrast."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('f2f397c4-0df2-47e9-b0e5-a512a380c928','4a62cdf9-43e3-4e8d-bc1e-8167f6b0281e','question_single_choice','{"prompt":"What can be inferred about the genetically altered plants described in paragraph 3?","options":[{"id":"A","label":"They grew faster because their cycles were longer."},{"id":"B","label":"Their internal timing did not match the real day well."},{"id":"C","label":"They could no longer move their leaves."},{"id":"D","label":"They no longer needed light for photosynthesis."}]}'::jsonb,4,'{"toefl_task":"read_academic_passage","original_slug":"ap-practice-4","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":3,"skill":"inference"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('f2f397c4-0df2-47e9-b0e5-a512a380c928','{"option_id":"B"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Their cycles were ''noticeably longer or shorter'' than the external day, so their timing was out of step with the environment (B). They grew less well, not faster (A), and leaf movement (C) and a lack of need for light (D) are not mentioned."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('7900e03f-fb49-4bf1-924f-ce3fea39fc1a','4a62cdf9-43e3-4e8d-bc1e-8167f6b0281e','question_single_choice','{"prompt":"What is the relationship between the experiment in paragraph 1 and the claim that the rhythm ''is generated within the plant itself''?","options":[{"id":"A","label":"The experiment provides evidence for the claim."},{"id":"B","label":"The experiment contradicts the claim."},{"id":"C","label":"The claim explains why the experiment failed."},{"id":"D","label":"The claim is unrelated to the experiment."}]}'::jsonb,5,'{"toefl_task":"read_academic_passage","original_slug":"ap-practice-4","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":4,"skill":"relationship"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('7900e03f-fb49-4bf1-924f-ce3fea39fc1a','{"option_id":"A"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Because the leaves keep moving in constant darkness, light cannot be the cause, which supports the idea of an internal rhythm (A). The experiment supports rather than contradicts the claim (B), it did not fail (C), and the word ''persistence'' directly links the two (D)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('eb1678ca-b645-4465-b8a2-a59d151883bc','4a62cdf9-43e3-4e8d-bc1e-8167f6b0281e','question_single_choice','{"prompt":"Why does the author describe a plant that produces photosynthesis molecules shortly before sunrise?","options":[{"id":"A","label":"To argue that plants are more advanced than animals"},{"id":"B","label":"To illustrate a benefit of anticipating changes in the environment"},{"id":"C","label":"To explain why leaves droop at night"},{"id":"D","label":"To describe how plants grow in constant darkness"}]}'::jsonb,6,'{"toefl_task":"read_academic_passage","original_slug":"ap-practice-4","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":5,"skill":"purpose"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('eb1678ca-b645-4465-b8a2-a59d151883bc','{"option_id":"B"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The example shows how a plant with an internal clock gains ''an advantage over a neighbor that waits'', illustrating the benefit of anticipation (B). Plants are compared with animals only to say both have clocks (A), drooping leaves are not explained here (C), and constant darkness belongs to the experiment in paragraph 1 (D)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.parts(id,section_id,name,display_order,metadata) values('41cc5217-9ec2-4c49-8890-a23d0582778b','2ab7e64b-be14-4b3c-944c-a8a64e2a11b1','Read an Academic Passage',5,'{"toefl_task":"read_academic_passage"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('3cea402f-f405-4b0b-9b1e-a774ab4e7b4b','41cc5217-9ec2-4c49-8890-a23d0582778b','reading_passage','{"toefl_stimulus":"academic_passage","title":"Why Sunsets Turn Red","text":"Sunlight appears white, but it is actually a mixture of many colors, each corresponding to a different wavelength. When this light enters the atmosphere, it collides with tiny gas molecules. These molecules scatter short wavelengths, such as blue and violet, far more strongly than longer wavelengths, such as red and orange. As a result, blue light is bounced in all directions across the sky, which is why a clear sky at midday looks blue from almost anywhere we stand.\n\nAt sunrise and sunset, the situation changes. The sun is low on the horizon, so its light must pass through a much thicker layer of air before reaching our eyes. Along this longer path, most of the blue light is scattered away to the sides long before it arrives. The light that remains is dominated by the longer wavelengths, giving the sun and nearby clouds their familiar orange and red colors.\n\nParticles in the air can intensify this effect. After dust storms, large fires, or volcanic eruptions, extra particles may remain in the atmosphere for days or even months. They scatter additional light and can produce unusually vivid sunsets far from the original event. Painters and photographers have long noticed these striking evening skies, often without knowing their cause.","subject":"physical science"}'::jsonb,1,'{"original_slug":"ap-practice-5","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","toefl_stimulus":"read_academic_passage"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('ab7739f4-37c3-44de-af22-ea68bf212c3a','41cc5217-9ec2-4c49-8890-a23d0582778b','question_single_choice','{"prompt":"According to paragraph 1, why does the midday sky look blue?","options":[{"id":"A","label":"Gas molecules scatter blue light more strongly than red light."},{"id":"B","label":"The sun gives off more blue light at midday."},{"id":"C","label":"Clouds absorb every color except blue."},{"id":"D","label":"Blue light travels a longer path through the air."}]}'::jsonb,2,'{"toefl_task":"read_academic_passage","original_slug":"ap-practice-5","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":1,"skill":"factual"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('ab7739f4-37c3-44de-af22-ea68bf212c3a','{"option_id":"A"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Paragraph 1 says molecules scatter short wavelengths such as blue ''far more strongly'' than red, spreading blue across the sky, so A is correct. The sun''s output does not change at midday (B), clouds absorbing colors is not mentioned (C), and the longer path is part of the sunset explanation (D)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('f695df7a-b95b-48d9-a4e0-1074d9c28ed2','41cc5217-9ec2-4c49-8890-a23d0582778b','question_single_choice','{"prompt":"The word ''intensify'' in the passage is closest in meaning to","options":[{"id":"A","label":"explain"},{"id":"B","label":"strengthen"},{"id":"C","label":"hide"},{"id":"D","label":"delay"}]}'::jsonb,3,'{"toefl_task":"read_academic_passage","original_slug":"ap-practice-5","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":2,"skill":"vocabulary"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('f695df7a-b95b-48d9-a4e0-1074d9c28ed2','{"option_id":"B"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Extra particles produce ''unusually vivid sunsets'', so they make the effect stronger (B). Particles do not explain (A), hide (C) or delay (D) the colors."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('b4766044-486a-4a18-9024-50f6224d6f1e','41cc5217-9ec2-4c49-8890-a23d0582778b','question_single_choice','{"prompt":"What can be inferred about a sunset seen some weeks after a large volcanic eruption?","options":[{"id":"A","label":"It will probably look completely blue."},{"id":"B","label":"It will happen earlier in the evening than usual."},{"id":"C","label":"It may be more colorful than an ordinary sunset."},{"id":"D","label":"It can be seen only very close to the volcano."}]}'::jsonb,4,'{"toefl_task":"read_academic_passage","original_slug":"ap-practice-5","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":3,"skill":"inference"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('b4766044-486a-4a18-9024-50f6224d6f1e','{"option_id":"C"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Particles can remain for months and cause ''unusually vivid sunsets far from the original event'', so C is correct. Nothing suggests a blue sunset (A) or a change in timing (B), and the effect can appear far away, not only nearby (D)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('12dc0ca3-8db7-4c4f-accb-dc939496fa51','41cc5217-9ec2-4c49-8890-a23d0582778b','question_single_choice','{"prompt":"How does paragraph 2 relate to paragraph 1?","options":[{"id":"A","label":"It rejects the explanation given in paragraph 1."},{"id":"B","label":"It describes a separate effect that has nothing to do with scattering."},{"id":"C","label":"It lists the colors that make up white light."},{"id":"D","label":"It applies the principle from paragraph 1 to a different situation."}]}'::jsonb,5,'{"toefl_task":"read_academic_passage","original_slug":"ap-practice-5","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":4,"skill":"relationship"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('12dc0ca3-8db7-4c4f-accb-dc939496fa51','{"option_id":"D"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Paragraph 2 uses the same idea, that blue light is scattered more, to explain sunrise and sunset colors, so D is correct. It builds on paragraph 1 rather than rejecting it (A), it is based on scattering (B), and the colors of white light are introduced in paragraph 1 (C)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('a6b2cdae-2936-4810-80ea-ab5ffc0dc222','41cc5217-9ec2-4c49-8890-a23d0582778b','question_single_choice','{"prompt":"Why does the author mention painters and photographers in paragraph 3?","options":[{"id":"A","label":"To argue that artists understand science better than scientists"},{"id":"B","label":"To explain how scientists measure the colors of sunsets"},{"id":"C","label":"To point out that people have observed these vivid skies for a long time"},{"id":"D","label":"To suggest that photographs make sunsets look redder than they are"}]}'::jsonb,6,'{"toefl_task":"read_academic_passage","original_slug":"ap-practice-5","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":5,"skill":"purpose"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('a6b2cdae-2936-4810-80ea-ab5ffc0dc222','{"option_id":"C"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The author says painters and photographers ''have long noticed these striking evening skies'', showing that the effect has been observed for a long time (C). In fact, they often did not know the cause, so A is wrong. Measuring colors (B) and photographs changing colors (D) are not discussed."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.parts(id,section_id,name,display_order,metadata) values('04500a9d-f0bc-44ec-86dd-bb0a8fa0f78b','2ab7e64b-be14-4b3c-944c-a8a64e2a11b1','Read an Academic Passage',6,'{"toefl_task":"read_academic_passage"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('67d5c75c-82c1-4681-8d39-4a83dd88cea0','04500a9d-f0bc-44ec-86dd-bb0a8fa0f78b','reading_passage','{"toefl_stimulus":"academic_passage","title":"Color Words Across Languages","text":"Languages differ considerably in how they divide the range of visible colors into named categories. Some languages use a single basic term for what English speakers would call both blue and green, while others distinguish two shades of blue as firmly as English distinguishes red from pink. Such variation raises a long-debated question: does the vocabulary of a language influence how its speakers perceive the world?\n\nEarly research tended to emphasize the universality of color perception. Investigators found that speakers of very different languages, when asked to select the best example of a color category, often chose remarkably similar shades. This suggested that human vision provides common reference points, regardless of the words available.\n\nMore recent experiments, however, have detected subtle effects of language. In one type of study, participants judge as quickly as possible whether two colored squares are identical. When the two shades fall on opposite sides of a boundary that the participants'' language names, responses are slightly faster than when both shades belong to the same named category, even if the physical difference is equal. Notably, this advantage tends to disappear when participants must simultaneously repeat a string of numbers, a task that occupies verbal memory. The finding implies that language does not reshape vision itself but can influence judgments when words are readily available.","subject":"social science"}'::jsonb,1,'{"original_slug":"ap-practice-6","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","toefl_stimulus":"read_academic_passage"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('37568de7-3eee-418d-9eb0-85bffcfc691f','04500a9d-f0bc-44ec-86dd-bb0a8fa0f78b','question_single_choice','{"prompt":"According to paragraph 2, what did early researchers find?","options":[{"id":"A","label":"Speakers of different languages could not agree on any color names."},{"id":"B","label":"People from different language groups often chose similar shades as the best examples of colors."},{"id":"C","label":"Languages with more color words produced sharper eyesight."},{"id":"D","label":"Most languages have no word for green."}]}'::jsonb,2,'{"toefl_task":"read_academic_passage","original_slug":"ap-practice-6","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":1,"skill":"factual"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('37568de7-3eee-418d-9eb0-85bffcfc691f','{"option_id":"B"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Paragraph 2 says speakers of very different languages ''often chose remarkably similar shades'' as the best examples of a category, so B is correct. Disagreement on names (A), better eyesight (C) and missing words for green (D) are not reported."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('4649aed2-fd1a-4c3c-8102-d8373e7f0244','04500a9d-f0bc-44ec-86dd-bb0a8fa0f78b','question_single_choice','{"prompt":"The word ''subtle'' in the passage is closest in meaning to","options":[{"id":"A","label":"obvious"},{"id":"B","label":"harmful"},{"id":"C","label":"permanent"},{"id":"D","label":"slight"}]}'::jsonb,3,'{"toefl_task":"read_academic_passage","original_slug":"ap-practice-6","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":2,"skill":"vocabulary"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('4649aed2-fd1a-4c3c-8102-d8373e7f0244','{"option_id":"D"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The effects found were small, with responses only ''slightly faster'', so ''subtle'' means slight (D). ''Obvious'' (A) is the opposite. Nothing suggests the effects were harmful (B), and they disappear under some conditions, so they are not permanent (C)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('5e9a943d-5e25-47d6-97f7-65cf65d7696c','04500a9d-f0bc-44ec-86dd-bb0a8fa0f78b','question_single_choice','{"prompt":"What can be inferred from the result involving repeating numbers?","options":[{"id":"A","label":"The faster responses depend on participants being able to use language during the task."},{"id":"B","label":"Repeating numbers improves people''s ability to see colors."},{"id":"C","label":"Participants who repeated numbers could not see the squares at all."},{"id":"D","label":"The color boundaries are the same in every language."}]}'::jsonb,4,'{"toefl_task":"read_academic_passage","original_slug":"ap-practice-6","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":3,"skill":"inference"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('5e9a943d-5e25-47d6-97f7-65cf65d7696c','{"option_id":"A"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The advantage disappears when verbal memory is busy, which suggests that it depends on access to words during the task (A). Repeating numbers removes an advantage rather than improving vision (B), participants could still judge the squares (C), and the passage says languages draw boundaries differently (D)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('d36ad18a-f1f2-46c2-b8e7-1bc4e4a2c634','04500a9d-f0bc-44ec-86dd-bb0a8fa0f78b','question_single_choice','{"prompt":"How do the findings in paragraph 3 relate to the findings in paragraph 2?","options":[{"id":"A","label":"They prove that the findings in paragraph 2 came from faulty equipment."},{"id":"B","label":"They repeat the findings in paragraph 2 using different languages."},{"id":"C","label":"They add a qualification to the view suggested by the findings in paragraph 2."},{"id":"D","label":"They are unrelated to the findings in paragraph 2."}]}'::jsonb,5,'{"toefl_task":"read_academic_passage","original_slug":"ap-practice-6","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":4,"skill":"relationship"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('d36ad18a-f1f2-46c2-b8e7-1bc4e4a2c634','{"option_id":"C"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Paragraph 2 suggests color perception is universal, and paragraph 3 (''however'') shows that language still has small effects on judgments, adding a qualification to that view (C). No equipment problems are mentioned (A), the findings are different, not repeated (B), and both paragraphs address the same question (D)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('0e9a7200-d0e9-4267-b83e-ae350857c0c3','04500a9d-f0bc-44ec-86dd-bb0a8fa0f78b','question_single_choice','{"prompt":"Why does the author mention languages that use a single term for blue and green?","options":[{"id":"A","label":"To illustrate how languages can divide colors differently"},{"id":"B","label":"To argue that these languages are less precise than English"},{"id":"C","label":"To explain why some people cannot see the color green"},{"id":"D","label":"To show that all languages share the same basic color terms"}]}'::jsonb,6,'{"toefl_task":"read_academic_passage","original_slug":"ap-practice-6","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":5,"skill":"purpose"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('0e9a7200-d0e9-4267-b83e-ae350857c0c3','{"option_id":"A"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The example supports the first sentence, which says languages differ in how they divide colors into categories (A). The author makes no judgment about precision (B), does not discuss inability to see green (C), and the example shows difference, not sameness (D)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.parts(id,section_id,name,display_order,metadata) values('93110e3c-782a-42ac-bc66-b7745d889222','2ab7e64b-be14-4b3c-944c-a8a64e2a11b1','Read an Academic Passage',7,'{"toefl_task":"read_academic_passage"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('22f63089-27c0-4546-a68d-02fe0774eb78','93110e3c-782a-42ac-bc66-b7745d889222','reading_passage','{"toefl_stimulus":"academic_passage","title":"Spacing Out Study Time","text":"Many students prepare for exams by studying for many hours the night before. This habit, often called cramming, can help a student remember facts the next morning. However, research on memory shows that information learned this way is often forgotten within a few days.\n\nA more effective method is called spaced practice. Instead of studying a topic once for a long time, the learner studies it several times in shorter sessions, with breaks of a day or more in between. For example, a student might review new vocabulary for twenty minutes on Monday, Wednesday, and Saturday rather than for one hour on Saturday only. Although the total study time is the same, the student who spreads out the sessions usually remembers more words several weeks later.\n\nWhy does spacing help? One explanation is that each time we return to information we have partly forgotten, our brain must work harder to recall it. This extra effort makes the memory stronger. Spaced practice can feel more difficult at first, and some students think it is not working. In fact, that feeling of difficulty is often a sign that real learning is taking place.","subject":"education"}'::jsonb,1,'{"original_slug":"ap-practice-7","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","toefl_stimulus":"read_academic_passage"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('c66933b4-c460-455f-9264-2cbbac40fe54','93110e3c-782a-42ac-bc66-b7745d889222','question_single_choice','{"prompt":"According to paragraph 1, what is a problem with cramming?","options":[{"id":"A","label":"It takes more time than other methods."},{"id":"B","label":"It makes students too tired to take the exam."},{"id":"C","label":"Students often forget the information within a few days."},{"id":"D","label":"It does not help students remember anything the next morning."}]}'::jsonb,2,'{"toefl_task":"read_academic_passage","original_slug":"ap-practice-7","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":1,"skill":"factual"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('c66933b4-c460-455f-9264-2cbbac40fe54','{"option_id":"C"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Paragraph 1 says information learned by cramming ''is often forgotten within a few days'', so C is correct. Time (A) and tiredness (B) are not mentioned as problems, and the passage says cramming can help students remember facts the next morning, so D is wrong."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('ceec4d33-1a34-47c2-8298-dc1a4fa35f6c','93110e3c-782a-42ac-bc66-b7745d889222','question_single_choice','{"prompt":"The word ''effective'' in the passage is closest in meaning to","options":[{"id":"A","label":"successful"},{"id":"B","label":"popular"},{"id":"C","label":"expensive"},{"id":"D","label":"relaxing"}]}'::jsonb,3,'{"toefl_task":"read_academic_passage","original_slug":"ap-practice-7","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":2,"skill":"vocabulary"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('ceec4d33-1a34-47c2-8298-dc1a4fa35f6c','{"option_id":"A"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Spaced practice is called ''more effective'' because students remember more, so it is more successful (A). The passage does not say it is more popular (B), costly (C) or relaxing (D); in fact, it can feel more difficult."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('74bbedbb-764d-4877-b0d8-ec8a061dfbba','93110e3c-782a-42ac-bc66-b7745d889222','question_single_choice','{"prompt":"What can be inferred about a student who finds spaced practice difficult at first?","options":[{"id":"A","label":"The student should go back to cramming."},{"id":"B","label":"The student is studying the wrong subject."},{"id":"C","label":"The student needs longer breaks between sessions."},{"id":"D","label":"The student may still be learning well."}]}'::jsonb,4,'{"toefl_task":"read_academic_passage","original_slug":"ap-practice-7","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":3,"skill":"inference"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('74bbedbb-764d-4877-b0d8-ec8a061dfbba','{"option_id":"D"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The passage says the feeling of difficulty ''is often a sign that real learning is taking place'', so D is correct. The author does not recommend cramming (A), and nothing is said about the subject (B) or the length of breaks (C)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('2cf74fa5-3b91-4cd6-bc34-22abe58815cd','93110e3c-782a-42ac-bc66-b7745d889222','question_single_choice','{"prompt":"How does the example of the vocabulary student in paragraph 2 relate to the description of spaced practice?","options":[{"id":"A","label":"It shows that spaced practice requires more total study time."},{"id":"B","label":"It illustrates how spaced practice can be used."},{"id":"C","label":"It contrasts spaced practice with group study."},{"id":"D","label":"It explains why vocabulary is difficult to learn."}]}'::jsonb,5,'{"toefl_task":"read_academic_passage","original_slug":"ap-practice-7","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":4,"skill":"relationship"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('2cf74fa5-3b91-4cd6-bc34-22abe58815cd','{"option_id":"B"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The example begins ''For example'' and shows a real schedule of spaced sessions, so B is correct. The total time is ''the same'', not greater (A). Group study (C) and the difficulty of vocabulary (D) are not discussed."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('68a00036-179a-4127-b6a5-24927cc15c4f','93110e3c-782a-42ac-bc66-b7745d889222','question_single_choice','{"prompt":"What is the main purpose of paragraph 3?","options":[{"id":"A","label":"To describe the history of memory research"},{"id":"B","label":"To warn students about studying too often"},{"id":"C","label":"To compare different kinds of exams"},{"id":"D","label":"To explain why spaced practice works"}]}'::jsonb,6,'{"toefl_task":"read_academic_passage","original_slug":"ap-practice-7","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":5,"skill":"purpose"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('68a00036-179a-4127-b6a5-24927cc15c4f','{"option_id":"D"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Paragraph 3 begins ''Why does spacing help?'' and gives an explanation, so D is correct. It does not discuss the history of research (A), warn against frequent study (B) or compare exams (C)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.parts(id,section_id,name,display_order,metadata) values('6cb5956a-38a3-416c-8256-54736a083ab3','2ab7e64b-be14-4b3c-944c-a8a64e2a11b1','Read an Academic Passage',8,'{"toefl_task":"read_academic_passage"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('bd4f69ab-0fb3-422f-8576-8924827fcd15','6cb5956a-38a3-416c-8256-54736a083ab3','reading_passage','{"toefl_stimulus":"academic_passage","title":"How Limestone Caves Form","text":"Many of the world''s largest caves have been carved out of limestone, a rock composed mainly of the remains of ancient sea creatures. What makes limestone special is that it slowly dissolves in weak acid. Rainwater becomes slightly acidic as it falls through the air and seeps through soil, where it absorbs carbon dioxide released by decaying plants.\n\nWhen this acidic water reaches limestone, it trickles into tiny cracks and gradually enlarges them. Over thousands of years, narrow fractures widen into channels, and channels merge into passages large enough for a person to walk through. The process is fastest just below the water table, the level beneath which the ground is completely filled with water. If the water table later drops, perhaps because a nearby river cuts its valley deeper, the passages drain and become air-filled caves.\n\nOnce a cave is filled with air, a new process can begin. Water dripping from the ceiling loses some of its carbon dioxide to the cave air, and as a result it can no longer hold all of its dissolved rock. Tiny amounts of mineral are left behind with each drop. Over time, these deposits build long, pointed formations hanging from the ceiling and matching columns rising from the floor.","subject":"earth science"}'::jsonb,1,'{"original_slug":"ap-practice-8","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","toefl_stimulus":"read_academic_passage"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('4c5281ed-e3f9-4c28-9d77-3f8f9d9e84b6','6cb5956a-38a3-416c-8256-54736a083ab3','question_single_choice','{"prompt":"According to paragraph 1, how does rainwater become acidic?","options":[{"id":"A","label":"By flowing over limestone"},{"id":"B","label":"By mixing with seawater"},{"id":"C","label":"By freezing inside cracks"},{"id":"D","label":"By absorbing carbon dioxide from the air and soil"}]}'::jsonb,2,'{"toefl_task":"read_academic_passage","original_slug":"ap-practice-8","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":1,"skill":"factual"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('4c5281ed-e3f9-4c28-9d77-3f8f9d9e84b6','{"option_id":"D"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Rainwater becomes acidic as it falls through the air and seeps through soil, where it absorbs carbon dioxide, so D is correct. Flowing over limestone dissolves the rock rather than making the water acidic (A), and seawater (B) and freezing (C) are not mentioned."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('30c45804-e823-4acd-b8e2-2b01c55c0572','6cb5956a-38a3-416c-8256-54736a083ab3','question_single_choice','{"prompt":"The word ''merge'' in the passage is closest in meaning to","options":[{"id":"A","label":"break apart"},{"id":"B","label":"join together"},{"id":"C","label":"dry out"},{"id":"D","label":"become narrower"}]}'::jsonb,3,'{"toefl_task":"read_academic_passage","original_slug":"ap-practice-8","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":2,"skill":"vocabulary"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('30c45804-e823-4acd-b8e2-2b01c55c0572','{"option_id":"B"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Channels ''merge into passages large enough for a person'', meaning they join together into larger spaces (B). ''Break apart'' (A) and ''become narrower'' (D) are the opposite of growing larger, and drying out (C) happens later when the water table drops."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('0d51a27f-ba1a-4f4e-aab3-a2a978f6d1be','6cb5956a-38a3-416c-8256-54736a083ab3','question_single_choice','{"prompt":"What can be inferred about a cave passage that is still below the water table?","options":[{"id":"A","label":"It already contains many hanging formations."},{"id":"B","label":"It has stopped growing."},{"id":"C","label":"It is filled with water rather than air."},{"id":"D","label":"It was formed by a river valley."}]}'::jsonb,4,'{"toefl_task":"read_academic_passage","original_slug":"ap-practice-8","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":3,"skill":"inference"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('0d51a27f-ba1a-4f4e-aab3-a2a978f6d1be','{"option_id":"C"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Below the water table the ground is completely filled with water, and passages become air-filled only after it drops, so C is correct. Hanging formations need an air-filled cave (A). Growth is fastest below the water table, not stopped (B), and the river only lowers the water table rather than forming the passage (D)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('fa0fabb2-9ac0-46e9-923d-77d9ebbc8a47','6cb5956a-38a3-416c-8256-54736a083ab3','question_single_choice','{"prompt":"How does the process described in paragraph 3 relate to the process described in paragraph 2?","options":[{"id":"A","label":"It builds up rock, whereas the earlier process removes it."},{"id":"B","label":"It happens before the process in paragraph 2."},{"id":"C","label":"It causes the drop in the water table."},{"id":"D","label":"It is identical to the process in paragraph 2."}]}'::jsonb,5,'{"toefl_task":"read_academic_passage","original_slug":"ap-practice-8","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":4,"skill":"relationship"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('fa0fabb2-9ac0-46e9-923d-77d9ebbc8a47','{"option_id":"A"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"In paragraph 2 acidic water dissolves limestone, while in paragraph 3 dripping water leaves mineral deposits behind, so one removes rock and the other adds it (A). Paragraph 3''s process begins only after the cave fills with air (B), a river is given as a cause of the drop (C), and the two processes are opposite rather than identical (D)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('9eec4bfa-d6dc-488c-8907-c3de79a5ea62','6cb5956a-38a3-416c-8256-54736a083ab3','question_single_choice','{"prompt":"Why does the author mention a river cutting its valley deeper?","options":[{"id":"A","label":"To explain how limestone was first created"},{"id":"B","label":"To give a possible reason the water table might fall"},{"id":"C","label":"To show that rivers flow through most caves"},{"id":"D","label":"To describe how cave formations grow"}]}'::jsonb,6,'{"toefl_task":"read_academic_passage","original_slug":"ap-practice-8","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":5,"skill":"purpose"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('9eec4bfa-d6dc-488c-8907-c3de79a5ea62','{"option_id":"B"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The river is introduced with ''perhaps because'' as one possible cause of a falling water table, so B is correct. Limestone comes from sea creatures (A), the passage does not claim rivers flow through most caves (C), and formations are explained in paragraph 3 (D)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.parts(id,section_id,name,display_order,metadata) values('a50749bc-3683-4a91-abff-23d33a8e8576','2ab7e64b-be14-4b3c-944c-a8a64e2a11b1','Read an Academic Passage',9,'{"toefl_task":"read_academic_passage"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('5ad59833-1e51-409f-bc81-0ca0302a547e','a50749bc-3683-4a91-abff-23d33a8e8576','reading_passage','{"toefl_stimulus":"academic_passage","title":"Why the Moon Shows One Face","text":"Observers on Earth always see essentially the same face of the Moon. This is not because the Moon fails to rotate; rather, it turns on its axis exactly once in the time it takes to complete one orbit around Earth. Astronomers describe a body in this condition as tidally locked, and the phenomenon is common among moons throughout the solar system.\n\nThe explanation lies in the uneven pull of gravity. Because gravity weakens with distance, Earth pulls more strongly on the near side of the Moon than on its far side, stretching the Moon slightly into two bulges, one facing toward Earth and one facing away. Long ago, when the young Moon spun more rapidly, its rotation kept carrying these bulges out of line with Earth. Earth''s gravity tugged back on them, acting like a gentle brake that gradually slowed the Moon''s spin.\n\nThe braking stopped only when the rotation period matched the orbital period, so that the bulges stayed aligned with Earth. The same mechanism also works in reverse: tides raised by the Moon are lengthening Earth''s day by a tiny fraction of a second each century. In principle, Earth could eventually become locked to the Moon as well, though this would take far longer than the expected lifetime of the Sun.","subject":"astronomy"}'::jsonb,1,'{"original_slug":"ap-practice-9","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","toefl_stimulus":"read_academic_passage"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('3f78e557-5072-47cb-9e64-f710d657c180','a50749bc-3683-4a91-abff-23d33a8e8576','question_single_choice','{"prompt":"According to paragraph 2, why does Earth pull more strongly on the near side of the Moon?","options":[{"id":"A","label":"Gravitational attraction becomes weaker with distance."},{"id":"B","label":"The near side contains more heavy rock."},{"id":"C","label":"The far side is shielded by the Moon''s bulges."},{"id":"D","label":"The Moon rotates faster on its near side."}]}'::jsonb,2,'{"toefl_task":"read_academic_passage","original_slug":"ap-practice-9","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":1,"skill":"factual"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('3f78e557-5072-47cb-9e64-f710d657c180','{"option_id":"A"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The passage states, ''Because gravity weakens with distance, Earth pulls more strongly on the near side'', so A is correct. The composition of the rock (B), shielding by the bulges (C) and different rotation speeds for each side (D) are not mentioned."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('6628bbf3-ebb6-4ae7-b6df-c26567b84ff2','a50749bc-3683-4a91-abff-23d33a8e8576','question_single_choice','{"prompt":"The word ''aligned'' in the passage is closest in meaning to","options":[{"id":"A","label":"compared"},{"id":"B","label":"colliding"},{"id":"C","label":"lined up"},{"id":"D","label":"equal in weight"}]}'::jsonb,3,'{"toefl_task":"read_academic_passage","original_slug":"ap-practice-9","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":2,"skill":"vocabulary"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('6628bbf3-ebb6-4ae7-b6df-c26567b84ff2','{"option_id":"C"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Earlier the bulges were ''out of line with Earth''; once braking stopped, they ''stayed aligned'', meaning lined up with Earth (C). The bulges are not compared (A) or colliding with Earth (B), and weight (D) is not the point."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('c1c7a9e0-7ee7-49df-bc1a-584002495ee6','a50749bc-3683-4a91-abff-23d33a8e8576','question_single_choice','{"prompt":"Which of the following can be inferred about the Moon''s rotation in the distant past?","options":[{"id":"A","label":"It was slower than it is today."},{"id":"B","label":"It took less time than one orbit around Earth."},{"id":"C","label":"It had already stopped completely."},{"id":"D","label":"It was controlled by the Sun rather than by Earth."}]}'::jsonb,4,'{"toefl_task":"read_academic_passage","original_slug":"ap-practice-9","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":3,"skill":"inference"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('c1c7a9e0-7ee7-49df-bc1a-584002495ee6','{"option_id":"B"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The young Moon ''spun more rapidly'' and was slowed until rotation matched the orbit, so earlier one rotation took less time than one orbit (B). It was faster, not slower (A), the Moon still rotates today (C), and the braking came from Earth''s gravity, not the Sun (D)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('b99929c4-ac16-4d32-923d-46bb3b9d065d','a50749bc-3683-4a91-abff-23d33a8e8576','question_single_choice','{"prompt":"What is the relationship between the bulges described in paragraph 2 and the slowing of the Moon''s spin?","options":[{"id":"A","label":"The slowing of the spin created the bulges for the first time."},{"id":"B","label":"The bulges prevented Earth''s gravity from affecting the Moon."},{"id":"C","label":"The bulges and the slowing happened on different moons."},{"id":"D","label":"Earth''s pull on the out-of-line bulges caused the spin to slow."}]}'::jsonb,5,'{"toefl_task":"read_academic_passage","original_slug":"ap-practice-9","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":4,"skill":"relationship"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('b99929c4-ac16-4d32-923d-46bb3b9d065d','{"option_id":"D"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Earth''s gravity tugged on the misaligned bulges, ''acting like a gentle brake'', so the bulges were the means by which the spin slowed (D). The bulges came from uneven gravity, not from the slowing (A). They allowed Earth''s gravity to act rather than preventing it (B), and both refer to our Moon (C)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('bd3718f9-7223-4634-b020-48c34b6e935f','a50749bc-3683-4a91-abff-23d33a8e8576','question_single_choice','{"prompt":"Why does the author mention that Earth''s day is getting longer?","options":[{"id":"A","label":"To show that the same process also affects Earth"},{"id":"B","label":"To argue that the Moon will soon stop orbiting Earth"},{"id":"C","label":"To explain why the Moon has two bulges"},{"id":"D","label":"To prove that the Moon does not rotate"}]}'::jsonb,6,'{"toefl_task":"read_academic_passage","original_slug":"ap-practice-9","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":5,"skill":"purpose"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('bd3718f9-7223-4634-b020-48c34b6e935f','{"option_id":"A"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The author introduces this point by saying ''The same mechanism also works in reverse'', showing that tidal braking acts on Earth too (A). Nothing says the Moon will stop orbiting (B), the bulges are explained earlier (C), and the passage states that the Moon does rotate (D)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.parts(id,section_id,name,display_order,metadata) values('c9e82016-3839-439f-9e59-d917f121a3a8','2ab7e64b-be14-4b3c-944c-a8a64e2a11b1','Read an Academic Passage',10,'{"toefl_task":"read_academic_passage"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('9998b30f-41d1-4587-8355-ccceed661477','c9e82016-3839-439f-9e59-d917f121a3a8','reading_passage','{"toefl_stimulus":"academic_passage","title":"Drums That Speak","text":"In parts of West Africa, some drums are used not only to make music but also to send messages. These instruments are often called talking drums. A common type is shaped like an hourglass and has strings running from one end to the other. When the player squeezes the strings under one arm, the drum skin becomes tighter and the sound becomes higher. Relaxing the arm makes the sound lower.\n\nThe drums can ''talk'' because many languages in the region are tonal. In a tonal language, the pitch of the voice can change the meaning of a word. Two words may have the same sounds but different meanings, depending on whether they are spoken with a high or a low tone. A skilled drummer copies the rise and fall of spoken words, so listeners who know the language can understand the message.\n\nBecause many words share the same tone pattern, drummers often add extra words or familiar phrases to make the meaning clear. In the past, talking drums announced important events, called people to meetings, and carried news between villages. Today they are still played at celebrations, and many young musicians are learning to play them.","subject":"music"}'::jsonb,1,'{"original_slug":"ap-practice-10","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","toefl_stimulus":"read_academic_passage"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('16595099-718c-40b4-a466-008baf7ea2d3','c9e82016-3839-439f-9e59-d917f121a3a8','question_single_choice','{"prompt":"According to paragraph 1, how does a player make the drum sound higher?","options":[{"id":"A","label":"By hitting the drum harder"},{"id":"B","label":"By turning the drum upside down"},{"id":"C","label":"By squeezing the strings to tighten the skin"},{"id":"D","label":"By relaxing the arm"}]}'::jsonb,2,'{"toefl_task":"read_academic_passage","original_slug":"ap-practice-10","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":1,"skill":"factual"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('16595099-718c-40b4-a466-008baf7ea2d3','{"option_id":"C"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Squeezing the strings makes the skin tighter and the sound higher, so C is correct. Hitting harder (A) and turning the drum over (B) are not mentioned, and relaxing the arm makes the sound lower, not higher (D)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('7e5237c2-53d0-4e40-9d07-b0bac7643c41','c9e82016-3839-439f-9e59-d917f121a3a8','question_single_choice','{"prompt":"The word ''skilled'' in the passage is closest in meaning to","options":[{"id":"A","label":"young"},{"id":"B","label":"famous"},{"id":"C","label":"loud"},{"id":"D","label":"expert"}]}'::jsonb,3,'{"toefl_task":"read_academic_passage","original_slug":"ap-practice-10","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":2,"skill":"vocabulary"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('7e5237c2-53d0-4e40-9d07-b0bac7643c41','{"option_id":"D"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"A ''skilled'' drummer is one who has the expert ability to copy the tones of speech, so D is correct. ''Young'' (A), ''famous'' (B) and ''loud'' (C) describe other qualities that are not about ability."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('9dd1945f-7a99-4a7d-aac7-dcd88eb55e34','c9e82016-3839-439f-9e59-d917f121a3a8','question_single_choice','{"prompt":"What can be inferred about a listener who does not know the local language?","options":[{"id":"A","label":"The listener would probably not understand the drum''s message."},{"id":"B","label":"The listener could understand the message more easily than local people."},{"id":"C","label":"The listener would hear only high sounds."},{"id":"D","label":"The listener would be able to play the drum."}]}'::jsonb,4,'{"toefl_task":"read_academic_passage","original_slug":"ap-practice-10","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":3,"skill":"inference"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('9dd1945f-7a99-4a7d-aac7-dcd88eb55e34','{"option_id":"A"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Only ''listeners who know the language can understand the message'', so someone who does not know it probably would not understand (A). B is the opposite of what the passage suggests. The drum makes both high and low sounds (C), and nothing links listening with playing (D)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('eab319a8-5250-4e20-99ab-c9089129cb6e','c9e82016-3839-439f-9e59-d917f121a3a8','question_single_choice','{"prompt":"How does paragraph 2 relate to paragraph 1?","options":[{"id":"A","label":"It describes a different instrument from the one in paragraph 1."},{"id":"B","label":"It explains why the changes in pitch described in paragraph 1 can carry meaning."},{"id":"C","label":"It argues against the description in paragraph 1."},{"id":"D","label":"It gives the history of the drum makers mentioned in paragraph 1."}]}'::jsonb,5,'{"toefl_task":"read_academic_passage","original_slug":"ap-practice-10","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":4,"skill":"relationship"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('eab319a8-5250-4e20-99ab-c9089129cb6e','{"option_id":"B"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Paragraph 1 explains how the drum makes high and low sounds, and paragraph 2 explains that these pitches matter because the local languages are tonal (B). It discusses the same drums (A), supports rather than argues against paragraph 1 (C), and no drum makers are mentioned (D)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('a86f3bf9-e88c-4e98-8503-6f7bec77ca87','c9e82016-3839-439f-9e59-d917f121a3a8','question_single_choice','{"prompt":"Why does the author mention that drummers add extra words or familiar phrases?","options":[{"id":"A","label":"To show that drum messages are always very long"},{"id":"B","label":"To explain why young musicians enjoy the drums"},{"id":"C","label":"To describe how drummers avoid confusion between words with the same tones"},{"id":"D","label":"To compare drums with written letters"}]}'::jsonb,6,'{"toefl_task":"read_academic_passage","original_slug":"ap-practice-10","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":5,"skill":"purpose"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('a86f3bf9-e88c-4e98-8503-6f7bec77ca87','{"option_id":"C"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Because many words share a tone pattern, the extra words ''make the meaning clear'', so C is correct. The passage does not say messages are always long (A), give reasons young musicians enjoy the drums (B), or compare drums with letters (D)."}}'::jsonb) on conflict (content_unit_id) do nothing;
