insert into public.answer_keys(content_unit_id,correct,metadata) values('91b9eede-caed-4940-8251-fbd9e0f7a106','{"transcript":[{"speaker":"Narrator","text":"Listen to a conversation between a student and an employee at the campus recreation center."},{"speaker":"Man","text":"Hi, I wanted to sign up for the beginner swimming class, but the website says it''s full."},{"speaker":"Woman","text":"Yes, the Tuesday class filled up in a day. But we keep a waiting list."},{"speaker":"Man","text":"Do people actually drop out?"},{"speaker":"Woman","text":"Usually two or three every term. And we''re adding a Saturday morning class next month."},{"speaker":"Man","text":"Saturday could work. Can I sign up for that now?"},{"speaker":"Woman","text":"Not yet. Registration opens on the first. If you join the waiting list, though, we''ll email you before it opens."},{"speaker":"Man","text":"Okay, put me on the list, then."}]}'::jsonb,'{"source":"original-schood-toefl-2026"}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('5519a8c7-5fc3-4281-9bc1-91ea790bfb87','7c97a31e-b625-478b-8801-f87dee1a48fa','question_single_choice','{"prompt":"Why does the man talk to the woman?","options":[{"id":"A","label":"He wants to join a class that is full."},{"id":"B","label":"He wants to become a swimming instructor."},{"id":"C","label":"He wants a refund for a class."},{"id":"D","label":"He lost something at the pool."}]}'::jsonb,2,'{"toefl_task":"listen_conversation","original_slug":"conv-practice-2","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":1}'::jsonb) on conflict (id) do nothing;
