insert into public.content_units(id,part_id,type,data,display_order,metadata) values('6ca18335-37ea-46d8-996d-e8d8d4895037','7c97a31e-b625-478b-8801-f87dee1a48fa','question_single_choice','{"prompt":"What is one advantage of joining the waiting list?","options":[{"id":"A","label":"Members get a discount on classes."},{"id":"B","label":"Members can choose any instructor."},{"id":"C","label":"Members can swim on Tuesdays right away."},{"id":"D","label":"Members hear about the new class early."}]}'::jsonb,3,'{"toefl_task":"listen_conversation","original_slug":"conv-practice-2","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":2}'::jsonb) on conflict (id) do nothing;
