insert into public.content_units(id,part_id,type,data,display_order,metadata) values('e2ea275d-363a-4997-bbe8-7c8fb5fcdc0c','5e8f2515-1e1c-4a02-aaf0-c8bd8b21cb7c','audio','{"url":"/media/toefl-2026/conv-practice-3.mp3","duration_seconds":39.9,"play_once":true,"auto_start":true,"toefl_stimulus":"listen_conversation","speakers":["f_us2","m_us3"],"context":"Listen to a conversation between two students."}'::jsonb,1,'{"toefl_stimulus":"listen_conversation","original_slug":"conv-practice-3"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('e2ea275d-363a-4997-bbe8-7c8fb5fcdc0c','{"transcript":[{"speaker":"Narrator","text":"Listen to a conversation between two students."},{"speaker":"Woman","text":"I saw a flyer saying the campus radio station needs volunteers. Want to apply with me?"},{"speaker":"Man","text":"Maybe. What would we actually do?"},{"speaker":"Woman","text":"Mostly help with the evening news show. Writing short stories, checking facts, that kind of thing."},{"speaker":"Man","text":"I''m a journalism minor, so that could look good on my resume."},{"speaker":"Woman","text":"Exactly. And after a semester, volunteers can host their own show."},{"speaker":"Man","text":"Now that''s tempting. Is there an interview?"},{"speaker":"Woman","text":"Just a short writing test on Friday afternoon."},{"speaker":"Man","text":"Hmm, I''ve got a lab until four on Fridays. I''ll ask if there''s another time."}]}'::jsonb,'{"source":"original-schood-toefl-2026"}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('3a9847e1-2296-496b-87fc-3821908feb91','5e8f2515-1e1c-4a02-aaf0-c8bd8b21cb7c','question_single_choice','{"prompt":"What is the woman trying to do?","options":[{"id":"A","label":"Find out where the radio station is"},{"id":"B","label":"Persuade the man to volunteer with her"},{"id":"C","label":"Ask the man to help her write a story"},{"id":"D","label":"Get the man to listen to her show"}]}'::jsonb,2,'{"toefl_task":"listen_conversation","original_slug":"conv-practice-3","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":1}'::jsonb) on conflict (id) do nothing;
