insert into public.content_units(id,part_id,type,data,display_order,metadata) values('21c26c34-1c5a-41dd-b7df-d5f849a52a9e','5e8f2515-1e1c-4a02-aaf0-c8bd8b21cb7c','question_single_choice','{"prompt":"What problem does the man mention?","options":[{"id":"A","label":"He has no experience in journalism."},{"id":"B","label":"He doesn''t like the evening news."},{"id":"C","label":"He has a schedule conflict with the test."},{"id":"D","label":"He has already applied somewhere else."}]}'::jsonb,3,'{"toefl_task":"listen_conversation","original_slug":"conv-practice-3","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":2}'::jsonb) on conflict (id) do nothing;
