insert into public.content_units(id,part_id,type,data,display_order,metadata) values('77ba9b22-9570-4e83-a6a8-d042f9ddcb8e','06a26769-7e32-4fae-94b0-8f163b463128','audio','{"url":"/media/toefl-2026/conv-practice-4.mp3","duration_seconds":42.5,"play_once":true,"auto_start":true,"toefl_stimulus":"listen_conversation","speakers":["f_us1","m_us2"],"context":"Listen to a conversation between a student and her professor."}'::jsonb,1,'{"toefl_stimulus":"listen_conversation","original_slug":"conv-practice-4"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('77ba9b22-9570-4e83-a6a8-d042f9ddcb8e','{"transcript":[{"speaker":"Narrator","text":"Listen to a conversation between a student and her professor."},{"speaker":"Woman","text":"Professor Hale, do you have a minute? It''s about the research proposal."},{"speaker":"Man","text":"Of course. Come in."},{"speaker":"Woman","text":"I''ve been reading for weeks, but my topic keeps getting bigger. Every article leads to three more."},{"speaker":"Man","text":"That''s a common trap. You''re casting the net too wide. What''s the one question you really care about?"},{"speaker":"Woman","text":"I guess how bilingual signs affect tourism in small towns."},{"speaker":"Man","text":"There you go. Focus on that, and set aside anything that doesn''t speak to it directly."},{"speaker":"Woman","text":"So I don''t need to cover every angle?"},{"speaker":"Man","text":"Not in a proposal. Pick one town, and come back with an outline next week."}]}'::jsonb,'{"source":"original-schood-toefl-2026"}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('a19f31ac-5ec5-4e0d-acb7-d310d2519272','06a26769-7e32-4fae-94b0-8f163b463128','question_single_choice','{"prompt":"What is the student''s problem?","options":[{"id":"A","label":"She can''t find enough articles."},{"id":"B","label":"She missed the proposal deadline."},{"id":"C","label":"She disagrees with the professor''s comments."},{"id":"D","label":"Her research topic has become too broad."}]}'::jsonb,2,'{"toefl_task":"listen_conversation","original_slug":"conv-practice-4","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":1}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('a19f31ac-5ec5-4e0d-acb7-d310d2519272','{"option_id":"D"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"She says her topic keeps getting bigger because every article leads to more."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('3cce3105-1730-45d1-a4af-e049b4b9495b','06a26769-7e32-4fae-94b0-8f163b463128','question_single_choice','{"prompt":"What does the professor mean when he says the student is casting the net too wide?","options":[{"id":"A","label":"She is trying to include too much."},{"id":"B","label":"She should read more articles."},{"id":"C","label":"She is working too quickly."},{"id":"D","label":"She needs to visit more towns."}]}'::jsonb,3,'{"toefl_task":"listen_conversation","original_slug":"conv-practice-4","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":2}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('3cce3105-1730-45d1-a4af-e049b4b9495b','{"option_id":"A"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The expression means trying to cover too much; he then tells her to focus on one question and one town."}}'::jsonb) on conflict (content_unit_id) do nothing;
