insert into public.answer_keys(content_unit_id,correct,metadata) values('eef28585-9b59-42ee-a275-ea94bcd7c423','{"transcript":[{"speaker":"Narrator","text":"Listen to a conversation between two friends."},{"speaker":"Man","text":"Are we still going hiking on Saturday?"},{"speaker":"Woman","text":"I hope so, but I just checked the weather. It might rain in the afternoon."},{"speaker":"Man","text":"Then let''s start early. If we leave at seven, we''ll be back by noon."},{"speaker":"Woman","text":"Seven is early, but okay. Should we take the bus to the park?"},{"speaker":"Man","text":"My cousin can lend me his car, so we can drive."},{"speaker":"Woman","text":"Even better. I''ll bring sandwiches and water."},{"speaker":"Man","text":"Great. Don''t forget a rain jacket, just in case."}]}'::jsonb,'{"source":"original-schood-toefl-2026"}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('b7b06606-f08d-42b9-aac0-9621f2835b7b','efc0fb46-a51d-44bf-9292-f42e6b870da0','question_single_choice','{"prompt":"Why do the speakers decide to leave early?","options":[{"id":"A","label":"The bus leaves at seven."},{"id":"B","label":"The park closes at noon."},{"id":"C","label":"Rain is expected later in the day."},{"id":"D","label":"The man has to work in the afternoon."}]}'::jsonb,2,'{"toefl_task":"listen_conversation","original_slug":"conv-practice-5","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":1}'::jsonb) on conflict (id) do nothing;
