insert into public.content_units(id,part_id,type,data,display_order,metadata) values('4f1f3156-6cdc-46c7-b54a-c945d274682a','efc0fb46-a51d-44bf-9292-f42e6b870da0','question_single_choice','{"prompt":"How will the speakers get to the park?","options":[{"id":"A","label":"By bus"},{"id":"B","label":"By bike"},{"id":"C","label":"On foot"},{"id":"D","label":"By car"}]}'::jsonb,3,'{"toefl_task":"listen_conversation","original_slug":"conv-practice-5","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":2}'::jsonb) on conflict (id) do nothing;
