insert into public.content_units(id,part_id,type,data,display_order,metadata) values('c1a68e86-128e-4a2c-b05c-dec0247060b5','17927484-b657-4bd8-b37f-2d61e0c364f2','audio','{"url":"/media/toefl-2026/conv-practice-6.mp3","duration_seconds":35.5,"play_once":true,"auto_start":true,"toefl_stimulus":"listen_conversation","speakers":["f_uk","m_us3"],"context":"Listen to a conversation between a student and a technology help desk worker."}'::jsonb,1,'{"toefl_stimulus":"listen_conversation","original_slug":"conv-practice-6"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('c1a68e86-128e-4a2c-b05c-dec0247060b5','{"transcript":[{"speaker":"Narrator","text":"Listen to a conversation between a student and a technology help desk worker."},{"speaker":"Woman","text":"Hi, I can''t log into the course website. It keeps saying my password is wrong."},{"speaker":"Man","text":"Did you change your password recently?"},{"speaker":"Woman","text":"Yes, last week. The system told me to."},{"speaker":"Man","text":"Ah, the course site sometimes takes a while to update. Try logging in with your old password."},{"speaker":"Woman","text":"Really? Let me see. Oh, it worked!"},{"speaker":"Man","text":"Good. It should switch over to the new one by tomorrow. If it doesn''t, come back and I''ll reset it."},{"speaker":"Woman","text":"Thanks. I was worried I''d miss tonight''s quiz."}]}'::jsonb,'{"source":"original-schood-toefl-2026"}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('321b49f8-bff6-4789-9eb4-177f38f7daad','17927484-b657-4bd8-b37f-2d61e0c364f2','question_single_choice','{"prompt":"What is the woman''s problem?","options":[{"id":"A","label":"She can''t get into a course website."},{"id":"B","label":"She forgot to take a quiz."},{"id":"C","label":"Her laptop is broken."},{"id":"D","label":"She doesn''t know her new password."}]}'::jsonb,2,'{"toefl_task":"listen_conversation","original_slug":"conv-practice-6","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":1}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('321b49f8-bff6-4789-9eb4-177f38f7daad','{"option_id":"A"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"She can''t log into the course website. She knows her new password; the site simply hasn''t updated."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('64b96d34-2cb1-410b-9e2e-342440d33dc0','17927484-b657-4bd8-b37f-2d61e0c364f2','question_single_choice','{"prompt":"Why does the woman''s old password still work?","options":[{"id":"A","label":"The man reset her account."},{"id":"B","label":"The course site hasn''t updated yet."},{"id":"C","label":"She never actually changed it."},{"id":"D","label":"The quiz uses a different system."}]}'::jsonb,3,'{"toefl_task":"listen_conversation","original_slug":"conv-practice-6","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":2}'::jsonb) on conflict (id) do nothing;
