insert into public.answer_keys(content_unit_id,correct,metadata) values('bdd11b1a-539d-4e8e-9bee-dd54a8966c44','{"transcript":[{"speaker":"Narrator","text":"Listen to a conversation between two students."},{"speaker":"Man","text":"I''m thinking of moving off campus next year. Rent in town is cheaper than the dorms."},{"speaker":"Woman","text":"On paper, maybe. Have you added up utilities, internet, and the bus pass?"},{"speaker":"Man","text":"Not really. I just compared the monthly rent."},{"speaker":"Woman","text":"When I moved out, my heating bill alone was a nasty surprise. And I had to buy furniture."},{"speaker":"Man","text":"So you''re saying it''s not the bargain it looks like."},{"speaker":"Woman","text":"It can be, if you share with a couple of roommates. Just do the math first."},{"speaker":"Man","text":"Okay. I''ll make a full budget before I sign anything."}]}'::jsonb,'{"source":"original-schood-toefl-2026"}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('853ef1a8-8778-4581-9f56-38c3e3059f8e','f22bf716-b1a3-48e4-a8fa-745d2037ea30','question_single_choice','{"prompt":"What is the woman''s attitude toward the man''s plan?","options":[{"id":"A","label":"She thinks it''s a terrible idea."},{"id":"B","label":"She thinks he should consider all the costs."},{"id":"C","label":"She wants to move in with him."},{"id":"D","label":"She thinks the dorms are too expensive."}]}'::jsonb,2,'{"toefl_task":"listen_conversation","original_slug":"conv-practice-7","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":1}'::jsonb) on conflict (id) do nothing;
