insert into public.content_units(id,part_id,type,data,display_order,metadata) values('66427a5d-2426-41b4-b45b-317182b93355','f22bf716-b1a3-48e4-a8fa-745d2037ea30','question_single_choice','{"prompt":"What will the man probably do next?","options":[{"id":"A","label":"Sign a lease in town"},{"id":"B","label":"Buy furniture"},{"id":"C","label":"Ask for a cheaper dorm room"},{"id":"D","label":"Calculate his total living costs"}]}'::jsonb,3,'{"toefl_task":"listen_conversation","original_slug":"conv-practice-7","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":2}'::jsonb) on conflict (id) do nothing;
