insert into public.answer_keys(content_unit_id,correct,metadata) values('1c44f47b-3d6b-4f50-bf21-11fa38969583','{"transcript":[{"speaker":"Narrator","text":"Listen to a conversation between a student and a clerk at the campus bookstore."},{"speaker":"Woman","text":"Hi, I''d like to return this book. I bought it for a class I ended up dropping."},{"speaker":"Man","text":"Sure. Do you have the receipt?"},{"speaker":"Woman","text":"Yes, here it is."},{"speaker":"Man","text":"Hmm, it says you bought it five weeks ago. Our full refund period is only three weeks."},{"speaker":"Woman","text":"Oh. Is there anything I can do?"},{"speaker":"Man","text":"We can give you store credit instead. Or you could try the buyback program at the end of the term, but you''d get less."},{"speaker":"Woman","text":"Store credit is fine. I still need supplies for my art class."}]}'::jsonb,'{"source":"original-schood-toefl-2026"}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('5de3054e-2dca-43c8-b879-bb072c3c04e5','a14d8e2a-abfa-41c0-ada6-fffbb176e175','question_single_choice','{"prompt":"Why can''t the woman get a full refund?","options":[{"id":"A","label":"She lost the receipt."},{"id":"B","label":"The book is damaged."},{"id":"C","label":"She bought it at a different store."},{"id":"D","label":"Too much time has passed since she bought it."}]}'::jsonb,2,'{"toefl_task":"listen_conversation","original_slug":"conv-practice-8","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":1}'::jsonb) on conflict (id) do nothing;
