insert into public.content_units(id,part_id,type,data,display_order,metadata) values('62a47e48-b832-44e1-a2fc-be87fef16b5f','a14d8e2a-abfa-41c0-ada6-fffbb176e175','question_single_choice','{"prompt":"What will the woman probably use the store credit for?","options":[{"id":"A","label":"Art supplies"},{"id":"B","label":"A new textbook for the class she dropped"},{"id":"C","label":"The buyback program"},{"id":"D","label":"A gift card for a friend"}]}'::jsonb,3,'{"toefl_task":"listen_conversation","original_slug":"conv-practice-8","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":2}'::jsonb) on conflict (id) do nothing;
