insert into public.answer_keys(content_unit_id,correct,metadata) values('e9b43b6b-c22d-47f9-8846-0ec9315774fa','{"transcript":[{"speaker":"Narrator","text":"Listen to a conversation between two students."},{"speaker":"Woman","text":"You''re in the photography club, right?"},{"speaker":"Man","text":"Yes, I joined last year. Why?"},{"speaker":"Woman","text":"I just got a camera for my birthday, and I''d like to learn how to use it."},{"speaker":"Man","text":"You should come to our next meeting. It''s on Wednesday evening in the art building."},{"speaker":"Woman","text":"Do I need to be good at photography?"},{"speaker":"Man","text":"Not at all. Most new members are beginners. We go on photo walks around town on weekends, too."},{"speaker":"Woman","text":"That sounds fun. I''ll be there on Wednesday."}]}'::jsonb,'{"source":"original-schood-toefl-2026"}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('bfec50de-faea-48e7-a1b0-b55df6409da1','03032288-4b64-406b-9259-aca3f8e2108b','question_single_choice','{"prompt":"Why is the woman interested in the club?","options":[{"id":"A","label":"She wants to sell her photos."},{"id":"B","label":"Her friends are members."},{"id":"C","label":"She wants to learn to use her new camera."},{"id":"D","label":"She needs it for an art class."}]}'::jsonb,2,'{"toefl_task":"listen_conversation","original_slug":"conv-practice-9","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":1}'::jsonb) on conflict (id) do nothing;
