insert into public.answer_keys(content_unit_id,correct,metadata) values('27573d93-5eb2-4024-965c-29650011e20c','{"transcript":[{"speaker":"Narrator","text":"Listen to a conversation between a student and an academic advisor."},{"speaker":"Man","text":"I need one more science course to graduate, and I''m stuck between astronomy and geology."},{"speaker":"Woman","text":"Both count toward the requirement. What''s making it hard to choose?"},{"speaker":"Man","text":"Astronomy sounds more interesting, but it has a night lab on Thursdays."},{"speaker":"Woman","text":"Do you work in the evenings?"},{"speaker":"Man","text":"Yes, at a hotel downtown, three nights a week, including Thursday."},{"speaker":"Woman","text":"Could you swap that shift?"},{"speaker":"Man","text":"Maybe. My manager''s pretty flexible."},{"speaker":"Woman","text":"Then talk to her before registration closes on Friday. If it doesn''t work out, geology''s a solid backup."}]}'::jsonb,'{"source":"original-schood-toefl-2026"}'::jsonb) on conflict (content_unit_id) do nothing;
