insert into public.answer_keys(content_unit_id,correct,metadata) values('d248f18b-732c-4ee3-89e3-d5ae1ab93efa','{"transcript":[{"speaker":"Narrator","text":"Listen to an announcement from campus transportation services."},{"speaker":"Speaker","text":"This is a message from campus transportation. Because of road work on Elm Street, the blue shuttle line will skip the north parking lot stop for the next two weeks. Riders who usually board there can walk to the stop outside the stadium, about five minutes away. The shuttle will also run every fifteen minutes instead of every twenty during the morning rush, to make up for the detour."}]}'::jsonb,'{"source":"original-schood-toefl-2026"}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('ff8cfb5a-842f-4dcf-8844-9cc1de83ef06','de025cb4-419a-4ed9-9fcb-501d0665caad','question_single_choice','{"prompt":"Why is the shuttle route changing?","options":[{"id":"A","label":"The north parking lot is being expanded."},{"id":"B","label":"There are not enough drivers."},{"id":"C","label":"A new stadium stop has opened."},{"id":"D","label":"There is construction on a street."}]}'::jsonb,2,'{"toefl_task":"listen_announcement","original_slug":"ann-practice-2","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":1}'::jsonb) on conflict (id) do nothing;
