insert into public.answer_keys(content_unit_id,correct,metadata) values('793a6fbe-fd8f-4637-97fe-0c8c8a2fa98f','{"transcript":[{"speaker":"Narrator","text":"Listen to an announcement in a business class."},{"speaker":"Speaker","text":"Okay, listen up. For the final project, you''ll work in groups of four. I''ve already assigned the groups, and you''ll find the list on the course website this afternoon. Each group will choose a local business and analyze how it uses social media. Your first task is to meet with your group before next Monday and agree on which business to study. Send me your choice by email so I can make sure there aren''t any duplicates."}]}'::jsonb,'{"source":"original-schood-toefl-2026"}'::jsonb) on conflict (content_unit_id) do nothing;
