insert into public.answer_keys(content_unit_id,correct,metadata) values('1f0b87a5-445a-456c-9f09-2b1a348b0517','{"transcript":[{"speaker":"Narrator","text":"Listen to an announcement from the campus career center."},{"speaker":"Speaker","text":"Just a heads-up for anyone thinking about summer internships. The fall career fair is coming up on the twelfth in the student union ballroom, and over sixty employers have registered. Recruiters tend to remember students who''ve done their homework, so look at the employer list beforehand and pick a handful to target rather than wandering from table to table. We''re also running resume checks all next week. Walk-ins are welcome, but the lines get long toward the end of the week."}]}'::jsonb,'{"source":"original-schood-toefl-2026"}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('e1c33a93-cb75-4f5d-83e0-01573a81c293','8c1a0f7c-a272-4b00-a934-7d8b99630b0e','question_single_choice','{"prompt":"What advice does the speaker give about the career fair?","options":[{"id":"A","label":"Arrive early to avoid long lines"},{"id":"B","label":"Visit as many tables as possible"},{"id":"C","label":"Research employers and choose a few in advance"},{"id":"D","label":"Bring several copies of a cover letter"}]}'::jsonb,2,'{"toefl_task":"listen_announcement","original_slug":"ann-practice-4","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":1}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('e1c33a93-cb75-4f5d-83e0-01573a81c293','{"option_id":"C"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"He advises looking at the employer list beforehand and targeting a handful instead of wandering. The long lines refer to resume checks."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('5ed243a8-e274-40c5-bd4d-6ba239cf83ed','8c1a0f7c-a272-4b00-a934-7d8b99630b0e','question_single_choice','{"prompt":"What can be inferred about the resume checks?","options":[{"id":"A","label":"They require an appointment."},{"id":"B","label":"They are only for seniors."},{"id":"C","label":"They take place at the career fair."},{"id":"D","label":"Students should go earlier in the week."}]}'::jsonb,3,'{"toefl_task":"listen_announcement","original_slug":"ann-practice-4","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":2}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('5ed243a8-e274-40c5-bd4d-6ba239cf83ed','{"option_id":"D"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Since lines get long toward the end of the week, going earlier is the better choice. Walk-ins are welcome, so no appointment is needed."}}'::jsonb) on conflict (content_unit_id) do nothing;
