insert into public.answer_keys(content_unit_id,correct,metadata) values('7e022751-7e36-48c3-b55e-d24ddefe08e0','{"transcript":[{"speaker":"Narrator","text":"Listen to an announcement in a classroom."},{"speaker":"Speaker","text":"Hello, class. Starting next week, we won''t meet in this room anymore. Our new room is two oh five in the Carter Building, right across from the library. The room is bigger and has better computers. The class time stays the same, ten in the morning. Please check the course website if you forget the room number."}]}'::jsonb,'{"source":"original-schood-toefl-2026"}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('a267602d-eefc-45ff-91d0-b720836f4fe0','bc79315c-c5d7-4109-8c0d-fec6a83d0ca0','question_single_choice','{"prompt":"What is the main purpose of the announcement?","options":[{"id":"A","label":"To tell students about a new classroom"},{"id":"B","label":"To change the class time"},{"id":"C","label":"To introduce new computers"},{"id":"D","label":"To describe the library"}]}'::jsonb,2,'{"toefl_task":"listen_announcement","original_slug":"ann-practice-5","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":1}'::jsonb) on conflict (id) do nothing;
