insert into public.answer_keys(content_unit_id,correct,metadata) values('c7c29ad0-55f2-4fa7-8a2a-a9c007613c19','{"transcript":[{"speaker":"Narrator","text":"Listen to an announcement on the campus radio station."},{"speaker":"Speaker","text":"The student health center is holding a blood drive next Tuesday and Wednesday in the gym lobby. Donating takes about forty-five minutes, including a short health check. Please eat a full meal and drink plenty of water beforehand. You can book a time online, but walk-ins are welcome. Every donor gets a free T-shirt, and the residence hall with the most donors will win a pizza party."}]}'::jsonb,'{"source":"original-schood-toefl-2026"}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('621bfe52-2ba5-4c2e-9b1e-0592216417ef','79eb64d9-2c2e-43f0-8b37-8f6ef4100f0c','question_single_choice','{"prompt":"What should donors do before giving blood?","options":[{"id":"A","label":"Skip breakfast"},{"id":"B","label":"Book a time online"},{"id":"C","label":"Visit the health center"},{"id":"D","label":"Eat a meal and drink water"}]}'::jsonb,2,'{"toefl_task":"listen_announcement","original_slug":"ann-practice-6","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":1}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('621bfe52-2ba5-4c2e-9b1e-0592216417ef','{"option_id":"D"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Donors are asked to eat a full meal and drink plenty of water. Booking online is optional because walk-ins are welcome."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('2d3c59a9-6c3d-4e18-8127-de41f4c4d9bb','79eb64d9-2c2e-43f0-8b37-8f6ef4100f0c','question_single_choice','{"prompt":"Why might residence halls compete with each other?","options":[{"id":"A","label":"To win free T-shirts"},{"id":"B","label":"To win a pizza party"},{"id":"C","label":"To host the next blood drive"},{"id":"D","label":"To get extra health checks"}]}'::jsonb,3,'{"toefl_task":"listen_announcement","original_slug":"ann-practice-6","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":2}'::jsonb) on conflict (id) do nothing;
