insert into public.content_units(id,part_id,type,data,display_order,metadata) values('d683bea2-854b-4541-b692-a5c0149e11f0','73e8a4d1-7f9f-40dd-a8cb-88172a31386d','audio','{"url":"/media/toefl-2026/ann-practice-7.mp3","duration_seconds":25.7,"play_once":true,"auto_start":true,"toefl_stimulus":"listen_announcement","speakers":["f_uk"],"context":"Listen to an announcement in a history class."}'::jsonb,1,'{"toefl_stimulus":"listen_announcement","original_slug":"ann-practice-7"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('d683bea2-854b-4541-b692-a5c0149e11f0','{"transcript":[{"speaker":"Narrator","text":"Listen to an announcement in a history class."},{"speaker":"Speaker","text":"A couple of you have asked whether the review session on Sunday is worth giving up a weekend afternoon for. I won''t take attendance, and I won''t introduce anything new. That said, the teaching assistant who runs it also helps write the exam, so she has a pretty good sense of where people tend to slip up. Draw your own conclusions. It''s from two to four in room one twelve, and you''re welcome to drop in for part of it."}]}'::jsonb,'{"source":"original-schood-toefl-2026"}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('aeb2f792-6b47-4675-bfa5-8733af98684c','73e8a4d1-7f9f-40dd-a8cb-88172a31386d','question_single_choice','{"prompt":"What is the speaker mainly talking about?","options":[{"id":"A","label":"Why attendance is required on Sunday"},{"id":"B","label":"New material that will be on the exam"},{"id":"C","label":"Whether students should attend a review session"},{"id":"D","label":"How the teaching assistant grades exams"}]}'::jsonb,2,'{"toefl_task":"listen_announcement","original_slug":"ann-practice-7","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":1}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('aeb2f792-6b47-4675-bfa5-8733af98684c','{"option_id":"C"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"She is answering students who asked whether the Sunday review session is worth attending. Attendance is not taken, and nothing new is introduced."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('63d54e60-55af-48d0-8c1b-477f94cd5307','73e8a4d1-7f9f-40dd-a8cb-88172a31386d','question_single_choice','{"prompt":"What does the speaker imply about the review session?","options":[{"id":"A","label":"It would probably be useful for the exam."},{"id":"B","label":"It will cover topics not taught in class."},{"id":"C","label":"It is mainly for students who missed lectures."},{"id":"D","label":"It might be cancelled."}]}'::jsonb,3,'{"toefl_task":"listen_announcement","original_slug":"ann-practice-7","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":2}'::jsonb) on conflict (id) do nothing;
