insert into public.answer_keys(content_unit_id,correct,metadata) values('726eb481-94ca-4f92-a3b4-f0714957495b','{"transcript":[{"speaker":"Narrator","text":"Listen to an announcement in a residence hall."},{"speaker":"Speaker","text":"Good evening, residents. Starting this month, our building is joining the campus composting program. You''ll find small green bins in every kitchen for food scraps like fruit peels and coffee grounds. Please don''t put plastic or meat in them. The bins are emptied every Monday and Thursday. If your bin is missing or damaged, let the front desk know, and we''ll replace it."}]}'::jsonb,'{"source":"original-schood-toefl-2026"}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('176c98d1-fef3-4cf3-be75-0ab8f12d9908','755ef22b-6044-459c-ba0c-b768c78981dd','question_single_choice','{"prompt":"What is the announcement mainly about?","options":[{"id":"A","label":"A new recycling bin for plastics"},{"id":"B","label":"A new food waste program in the building"},{"id":"C","label":"Kitchen cleaning rules"},{"id":"D","label":"A change in trash collection days"}]}'::jsonb,2,'{"toefl_task":"listen_announcement","original_slug":"ann-practice-8","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":1}'::jsonb) on conflict (id) do nothing;
