insert into public.content_units(id,part_id,type,data,display_order,metadata) values('a6794591-6c18-4f92-a3fb-ae45c04e7777','97ea1b63-a241-48aa-8023-50bd977f366f','audio','{"url":"/media/toefl-2026/ann-practice-9.mp3","duration_seconds":31.7,"play_once":true,"auto_start":true,"toefl_stimulus":"listen_announcement","speakers":["f_us1"],"context":"Listen to an announcement in a sociology class."}'::jsonb,1,'{"toefl_stimulus":"listen_announcement","original_slug":"ann-practice-9"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('a6794591-6c18-4f92-a3fb-ae45c04e7777','{"transcript":[{"speaker":"Narrator","text":"Listen to an announcement in a sociology class."},{"speaker":"Speaker","text":"I want to clarify something about participation, since there''s been some confusion. It''s not about how often you speak; it''s about whether what you say moves the discussion forward. Someone who makes one thoughtful point that builds on a classmate''s idea will do better than someone who talks constantly without engaging. And if speaking up in a big group isn''t your strong suit, our online forum counts just as much. Next week I''ll post an example of a strong forum reply."}]}'::jsonb,'{"source":"original-schood-toefl-2026"}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('da701f80-16da-48ef-ab8b-e421f1310ee2','97ea1b63-a241-48aa-8023-50bd977f366f','question_single_choice','{"prompt":"What is the main point of the announcement?","options":[{"id":"A","label":"Participation is judged by quality rather than quantity."},{"id":"B","label":"Students must speak in every class."},{"id":"C","label":"The online forum is being closed."},{"id":"D","label":"Participation is no longer part of the grade."}]}'::jsonb,2,'{"toefl_task":"listen_announcement","original_slug":"ann-practice-9","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":1}'::jsonb) on conflict (id) do nothing;
