insert into public.answer_keys(content_unit_id,correct,metadata) values('c598db65-c22e-477e-9cb2-4af9fb3f80a0','{"transcript":[{"speaker":"Narrator","text":"Listen to an announcement from the campus art gallery."},{"speaker":"Speaker","text":"The campus gallery invites everyone to the opening of this year''s student art exhibition on Friday at six. More than forty students are showing paintings, photographs, and sculptures. Several pieces will be for sale, and the money goes directly to the artists. Light snacks will be served. The exhibition stays open for three weeks, but the artists will only be there to talk about their work on opening night."}]}'::jsonb,'{"source":"original-schood-toefl-2026"}'::jsonb) on conflict (content_unit_id) do nothing;
