insert into public.content_units(id,part_id,type,data,display_order,metadata) values('8bef8db1-af1e-4a9f-a93a-b2150f3e45b3','9ccda00e-ad52-406e-ac83-a3311a51a8c2','question_single_choice','{"prompt":"Why might someone want to attend on Friday in particular?","options":[{"id":"A","label":"Admission is free only on Friday."},{"id":"B","label":"The artwork will be cheaper that night."},{"id":"C","label":"The artists will be there to discuss their work."},{"id":"D","label":"Snacks are served every day except Friday."}]}'::jsonb,3,'{"toefl_task":"listen_announcement","original_slug":"ann-practice-10","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":2}'::jsonb) on conflict (id) do nothing;
