insert into public.content_units(id,part_id,type,data,display_order,metadata) values('75cfa9ad-ff79-4aeb-be2a-8f885c7e02f1','1cb382fb-603c-43a3-bab5-e185b0d97f69','audio','{"url":"/media/toefl-2026/talk-practice-1.mp3","duration_seconds":67.4,"play_once":true,"auto_start":true,"toefl_stimulus":"listen_academic_talk","speakers":["f_uk"],"context":"Listen to a talk in an art history class."}'::jsonb,1,'{"toefl_stimulus":"listen_academic_talk","original_slug":"talk-practice-1"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('75cfa9ad-ff79-4aeb-be2a-8f885c7e02f1','{"transcript":[{"speaker":"Narrator","text":"Listen to a talk in an art history class."},{"speaker":"Speaker","text":"Today we''re looking at a painting technique called true fresco, used in many of the great wall paintings of Renaissance Italy. In true fresco, the artist paints onto wet plaster. As the plaster dries, a chemical reaction locks the pigment into the wall itself, so the color becomes part of the surface rather than sitting on top of it. That''s why some frescoes have lasted for five hundred years. But this technique put enormous pressure on the painter. Plaster stays workable for only about a day, so artists spread fresh plaster over just the section they could finish before it dried. Art historians call each of these sections a giornata, which is Italian for a day''s work. If you look closely at some famous ceilings, you can actually see faint lines where one day''s patch meets the next, and by counting them, scholars can estimate how long a painting took. Mistakes were also hard to fix. An error couldn''t simply be painted over. The painter had to chip away the plaster and redo that section. Some artists added final details on dry plaster for convenience, but those touches tend to flake off over the centuries."}]}'::jsonb,'{"source":"original-schood-toefl-2026"}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('3f337a90-ef28-4c18-ab9d-900b8d2252e2','1cb382fb-603c-43a3-bab5-e185b0d97f69','question_single_choice','{"prompt":"What is the talk mainly about?","options":[{"id":"A","label":"The life of a Renaissance painter"},{"id":"B","label":"How frescoes are restored today"},{"id":"C","label":"A painting technique that uses wet plaster"},{"id":"D","label":"Why Italian ceilings are curved"}]}'::jsonb,2,'{"toefl_task":"listen_academic_talk","original_slug":"talk-practice-1","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":1}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('3f337a90-ef28-4c18-ab9d-900b8d2252e2','{"option_id":"C"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The talk describes true fresco, painting onto wet plaster, and the challenges it created."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('d90dd5ad-7edc-4353-b481-b65d882c72ee','1cb382fb-603c-43a3-bab5-e185b0d97f69','question_single_choice','{"prompt":"Why have some true frescoes lasted so long?","options":[{"id":"A","label":"They were covered with a protective varnish."},{"id":"B","label":"They were painted indoors away from sunlight."},{"id":"C","label":"Artists used unusually thick paint."},{"id":"D","label":"The pigment became part of the wall as the plaster dried."}]}'::jsonb,3,'{"toefl_task":"listen_academic_talk","original_slug":"talk-practice-1","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":2}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('d90dd5ad-7edc-4353-b481-b65d882c72ee','{"option_id":"D"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"A chemical reaction locks the pigment into the wall, so the color becomes part of the surface."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('38f0c23a-6fa1-4305-a1f1-c9583692b30a','1cb382fb-603c-43a3-bab5-e185b0d97f69','question_single_choice','{"prompt":"Why does the speaker mention the faint lines visible on some ceilings?","options":[{"id":"A","label":"To show that the plaster was of poor quality"},{"id":"B","label":"To explain how scholars estimate the time a painting took"},{"id":"C","label":"To describe a mistake made by a famous artist"},{"id":"D","label":"To argue that dry plaster is better"}]}'::jsonb,4,'{"toefl_task":"listen_academic_talk","original_slug":"talk-practice-1","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":3}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('38f0c23a-6fa1-4305-a1f1-c9583692b30a','{"option_id":"B"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Each line marks a day''s section, so counting them lets scholars estimate how long the painting took."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('9fe42a14-088d-4eb5-b734-1b4e9f47b4bb','1cb382fb-603c-43a3-bab5-e185b0d97f69','question_single_choice','{"prompt":"What can be inferred about details added on dry plaster?","options":[{"id":"A","label":"They are less durable than the rest of the fresco."},{"id":"B","label":"They were added only by assistants."},{"id":"C","label":"They took longer to paint."},{"id":"D","label":"They were forbidden in some cities."}]}'::jsonb,5,'{"toefl_task":"listen_academic_talk","original_slug":"talk-practice-1","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":4}'::jsonb) on conflict (id) do nothing;
