insert into public.content_units(id,part_id,type,data,display_order,metadata) values('dfd6f94d-b87c-473b-bca6-b0d2d94a00ba','1acdd00b-9c9f-496c-b77f-552448e7aace','audio','{"url":"/media/toefl-2026/talk-practice-2.mp3","duration_seconds":65.8,"play_once":true,"auto_start":true,"toefl_stimulus":"listen_academic_talk","speakers":["m_us2"],"context":"Listen to a talk in a music class."}'::jsonb,1,'{"toefl_stimulus":"listen_academic_talk","original_slug":"talk-practice-2"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('dfd6f94d-b87c-473b-bca6-b0d2d94a00ba','{"transcript":[{"speaker":"Narrator","text":"Listen to a talk in a music class."},{"speaker":"Speaker","text":"Have you ever wondered why, at the start of a concert, the whole orchestra tunes to a single note played by the oboe? There are a few reasons, and they''re partly practical and partly historical. First, the practical side. The oboe has a bright, penetrating sound that cuts through the room, so every player can hear it clearly, even from the back of the stage. Its pitch is also quite stable. Many string instruments drift out of tune as the hall warms up, but the oboe is less affected, and it''s hard for an oboist to adjust its pitch much anyway. So it makes sense for everyone else to match the oboe rather than the other way around. Now the historical side. In the seventeenth century, when orchestras were taking shape, the oboe was one of the few wind instruments commonly included, and it often played the main melody. It became the natural reference point, and the habit stuck. Interestingly, when an orchestra performs with a piano, the situation changes. A piano can''t be retuned in the middle of a concert, so the oboist tunes to the piano first and then passes that note on to everyone else."}]}'::jsonb,'{"source":"original-schood-toefl-2026"}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('569ac358-6692-466a-b916-dd848aaaf5b6','1acdd00b-9c9f-496c-b77f-552448e7aace','question_single_choice','{"prompt":"What is the talk mainly about?","options":[{"id":"A","label":"Why orchestras tune to the oboe"},{"id":"B","label":"How oboes are made"},{"id":"C","label":"The history of the piano"},{"id":"D","label":"How to become a professional oboist"}]}'::jsonb,2,'{"toefl_task":"listen_academic_talk","original_slug":"talk-practice-2","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":1}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('569ac358-6692-466a-b916-dd848aaaf5b6','{"option_id":"A"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The speaker gives practical and historical reasons that orchestras tune to the oboe."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('80a6ec05-0067-4018-a217-738c66ab4595','1acdd00b-9c9f-496c-b77f-552448e7aace','question_single_choice','{"prompt":"According to the speaker, why is the oboe''s sound useful for tuning?","options":[{"id":"A","label":"It is very quiet and soft."},{"id":"B","label":"It is bright and easy for everyone to hear."},{"id":"C","label":"It changes with the temperature of the hall."},{"id":"D","label":"It sounds like a piano."}]}'::jsonb,3,'{"toefl_task":"listen_academic_talk","original_slug":"talk-practice-2","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":2}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('80a6ec05-0067-4018-a217-738c66ab4595','{"option_id":"B"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The oboe has a bright, penetrating sound that every player can hear clearly. String instruments, not the oboe, drift as the hall warms up."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('509af30d-df56-46d9-b2b0-4ef93f4e5ae9','1acdd00b-9c9f-496c-b77f-552448e7aace','question_single_choice','{"prompt":"Why does the speaker mention the seventeenth century?","options":[{"id":"A","label":"To describe when the piano was invented"},{"id":"B","label":"To explain when oboes became cheaper"},{"id":"C","label":"To show that orchestras were once much larger"},{"id":"D","label":"To give historical background for the tuning tradition"}]}'::jsonb,4,'{"toefl_task":"listen_academic_talk","original_slug":"talk-practice-2","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":3}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('509af30d-df56-46d9-b2b0-4ef93f4e5ae9','{"option_id":"D"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"In that period the oboe was a common wind instrument that often played the melody, so it became the reference point."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('c79c0a79-a9d1-41c0-862f-e16431a6f6c9','1acdd00b-9c9f-496c-b77f-552448e7aace','question_single_choice','{"prompt":"What can be inferred about a concert that includes a piano?","options":[{"id":"A","label":"The oboe is not played at all."},{"id":"B","label":"The piano is retuned to match the oboe."},{"id":"C","label":"The piano becomes the main reference for tuning."},{"id":"D","label":"Each musician tunes separately."}]}'::jsonb,5,'{"toefl_task":"listen_academic_talk","original_slug":"talk-practice-2","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":4}'::jsonb) on conflict (id) do nothing;
