insert into public.parts(id,section_id,name,display_order,metadata) values('c0663c54-7347-45c1-ad54-419acc09bea6','755a64ee-f865-46c4-ae7a-3ca9d1c3b38f','Listen to an Academic Talk',3,'{"toefl_task":"listen_academic_talk"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('b8d7363e-abf3-4dc3-94d6-9d57a5f443d1','c0663c54-7347-45c1-ad54-419acc09bea6','audio','{"url":"/media/toefl-2026/talk-practice-3.mp3","duration_seconds":77.4,"play_once":true,"auto_start":true,"toefl_stimulus":"listen_academic_talk","speakers":["f_us1"],"context":"Listen to a talk in an urban studies class."}'::jsonb,1,'{"toefl_stimulus":"listen_academic_talk","original_slug":"talk-practice-3"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('b8d7363e-abf3-4dc3-94d6-9d57a5f443d1','{"transcript":[{"speaker":"Narrator","text":"Listen to a talk in an urban studies class."},{"speaker":"Speaker","text":"Walk across almost any college campus and you''ll find narrow dirt trails cutting across the grass, often right next to a paved sidewalk. Urban planners have a name for these: desire paths. They form when enough people decide that the official route isn''t the one they actually want to take, usually because it''s longer or less direct. Over time, the grass wears away and a path appears. For a long time, planners treated desire paths as a nuisance. They put up fences or planted bushes to block them. But more recently, many designers have started to see them as free information. A desire path is basically a record of how people really move through a space, which is something no survey can capture quite as honestly. Some universities have taken this idea to its logical conclusion. When they build a new quad, they plant grass everywhere and wait a year before laying any sidewalks. Then they pave the paths that students have worn into the ground. The result is a layout that matches real behavior, and people tend to stay on those sidewalks. Of course, not every desire path should be paved. Some cut through areas that are dangerous or ecologically sensitive, and there, redirecting people still makes sense."}]}'::jsonb,'{"source":"original-schood-toefl-2026"}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('c88900a3-8652-4777-804c-9fdf802f8e0b','c0663c54-7347-45c1-ad54-419acc09bea6','question_single_choice','{"prompt":"What is the talk mainly about?","options":[{"id":"A","label":"How to plant grass that resists damage"},{"id":"B","label":"Why students prefer paved sidewalks"},{"id":"C","label":"The history of college campus design"},{"id":"D","label":"What informal walking paths reveal and how planners respond to them"}]}'::jsonb,2,'{"toefl_task":"listen_academic_talk","original_slug":"talk-practice-3","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":1}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('c88900a3-8652-4777-804c-9fdf802f8e0b','{"option_id":"D"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The talk explains desire paths, what they show about real movement, and how planners now use or block them."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('42e0f8e3-9376-47bf-8092-18e6702f5bcc','c0663c54-7347-45c1-ad54-419acc09bea6','question_single_choice','{"prompt":"According to the speaker, why do desire paths usually form?","options":[{"id":"A","label":"The official route is longer or less direct."},{"id":"B","label":"The sidewalks are in poor condition."},{"id":"C","label":"Planners create them on purpose."},{"id":"D","label":"Students are not allowed on the grass."}]}'::jsonb,3,'{"toefl_task":"listen_academic_talk","original_slug":"talk-practice-3","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":2}'::jsonb) on conflict (id) do nothing;
