insert into public.content_units(id,part_id,type,data,display_order,metadata) values('acfe6831-458b-48cd-8804-d898a62929e6','c0663c54-7347-45c1-ad54-419acc09bea6','question_single_choice','{"prompt":"Why does the speaker mention universities that wait a year before building sidewalks?","options":[{"id":"A","label":"To criticize a slow construction process"},{"id":"B","label":"To show that grass grows better without sidewalks"},{"id":"C","label":"To give an example of using desire paths in design"},{"id":"D","label":"To explain why students ignore sidewalks"}]}'::jsonb,4,'{"toefl_task":"listen_academic_talk","original_slug":"talk-practice-3","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":3}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('acfe6831-458b-48cd-8804-d898a62929e6','{"option_id":"C"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"These universities pave the paths students wear into the grass, using desire paths as design information."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('5361bfb0-f605-49a5-9dd2-611e2ccdc969','c0663c54-7347-45c1-ad54-419acc09bea6','question_single_choice','{"prompt":"What does the speaker imply about blocking desire paths?","options":[{"id":"A","label":"It is never a good idea."},{"id":"B","label":"It may still be appropriate in some situations."},{"id":"C","label":"It is the most effective solution."},{"id":"D","label":"It is required by law."}]}'::jsonb,5,'{"toefl_task":"listen_academic_talk","original_slug":"talk-practice-3","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":4}'::jsonb) on conflict (id) do nothing;
