insert into public.parts(id,section_id,name,display_order,metadata) values('191a13db-8402-423f-a67a-0500d5d14ade','755a64ee-f865-46c4-ae7a-3ca9d1c3b38f','Listen to an Academic Talk',4,'{"toefl_task":"listen_academic_talk"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('7f9089c1-9537-453e-b148-e8250d39d42c','191a13db-8402-423f-a67a-0500d5d14ade','audio','{"url":"/media/toefl-2026/talk-practice-4.mp3","duration_seconds":67.8,"play_once":true,"auto_start":true,"toefl_stimulus":"listen_academic_talk","speakers":["m_us3"],"context":"Listen to a talk in a geology class."}'::jsonb,1,'{"toefl_stimulus":"listen_academic_talk","original_slug":"talk-practice-4"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('7f9089c1-9537-453e-b148-e8250d39d42c','{"transcript":[{"speaker":"Narrator","text":"Listen to a talk in a geology class."},{"speaker":"Speaker","text":"So where do caves come from? Most of the large cave systems in the world form in limestone, and the main tool that carves them is surprisingly gentle: rainwater. As rain falls through the air and soaks through soil, it picks up carbon dioxide, which turns it into a very weak acid. On its own, this water wouldn''t harm most kinds of rock. But limestone is different. It dissolves slowly in weak acid. The water seeps into tiny cracks in the limestone and widens them, very gradually. We''re talking about a process that can take hundreds of thousands of years. Eventually, the cracks become channels, and the channels become passages large enough to walk through. Now, once a cave has formed, the process can partly run in reverse. When water carrying dissolved limestone drips from a cave ceiling, it releases some of its carbon dioxide into the air. That makes it deposit a tiny bit of the mineral it was carrying. Drip by drip, those deposits build up into the icicle-shaped formations called stalactites. Where the drops hit the floor, matching columns called stalagmites grow upward. So the same water that hollows out a cave also decorates it."}]}'::jsonb,'{"source":"original-schood-toefl-2026"}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('0a7518b8-3f0d-4017-8eaf-d84204ac42a9','191a13db-8402-423f-a67a-0500d5d14ade','question_single_choice','{"prompt":"What is the talk mainly about?","options":[{"id":"A","label":"The dangers of exploring caves"},{"id":"B","label":"How limestone caves and their formations develop"},{"id":"C","label":"Why rainwater is harmful to soil"},{"id":"D","label":"The difference between limestone and other rocks"}]}'::jsonb,2,'{"toefl_task":"listen_academic_talk","original_slug":"talk-practice-4","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":1}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('0a7518b8-3f0d-4017-8eaf-d84204ac42a9','{"option_id":"B"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The talk explains how rainwater carves limestone caves and then builds stalactites and stalagmites."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('0d3505c3-984e-4f2b-870c-77738b129f78','191a13db-8402-423f-a67a-0500d5d14ade','question_single_choice','{"prompt":"What makes rainwater able to dissolve limestone?","options":[{"id":"A","label":"It contains salt from the ocean."},{"id":"B","label":"It is heated underground."},{"id":"C","label":"It absorbs carbon dioxide and becomes slightly acidic."},{"id":"D","label":"It moves very quickly through cracks."}]}'::jsonb,3,'{"toefl_task":"listen_academic_talk","original_slug":"talk-practice-4","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":2}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('0d3505c3-984e-4f2b-870c-77738b129f78','{"option_id":"C"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Rain picks up carbon dioxide from the air and soil, which turns it into a weak acid that dissolves limestone."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('73060d93-1d68-4dde-872a-3c6612968559','191a13db-8402-423f-a67a-0500d5d14ade','question_single_choice','{"prompt":"According to the speaker, why does water dripping from a cave ceiling leave a mineral deposit?","options":[{"id":"A","label":"It releases some carbon dioxide into the air."},{"id":"B","label":"It freezes in the cold cave air."},{"id":"C","label":"It mixes with water from the floor."},{"id":"D","label":"It absorbs more limestone from the ceiling."}]}'::jsonb,4,'{"toefl_task":"listen_academic_talk","original_slug":"talk-practice-4","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":3}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('73060d93-1d68-4dde-872a-3c6612968559','{"option_id":"A"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"When the dripping water releases carbon dioxide, it deposits some of the mineral it was carrying."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('d93c7a54-e746-41b4-b72a-4741bc8c9686','191a13db-8402-423f-a67a-0500d5d14ade','question_single_choice','{"prompt":"What does the speaker mean by saying the process can ''partly run in reverse''?","options":[{"id":"A","label":"Caves can close up completely over time."},{"id":"B","label":"Water can flow back up into the ceiling."},{"id":"C","label":"Rainwater becomes less acidic underground."},{"id":"D","label":"Water can add rock to a cave as well as remove it."}]}'::jsonb,5,'{"toefl_task":"listen_academic_talk","original_slug":"talk-practice-4","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":4}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('d93c7a54-e746-41b4-b72a-4741bc8c9686','{"option_id":"D"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The same water that dissolved limestone also deposits it to form stalactites and stalagmites, so it ''decorates'' the cave too."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.parts(id,section_id,name,display_order,metadata) values('4f480322-a8a4-4255-add1-0de19a9cc2c7','755a64ee-f865-46c4-ae7a-3ca9d1c3b38f','Listen to an Academic Talk',5,'{"toefl_task":"listen_academic_talk"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('fe2268ed-2caf-4928-8d74-3db406a4bdb8','4f480322-a8a4-4255-add1-0de19a9cc2c7','audio','{"url":"/media/toefl-2026/talk-practice-5.mp3","duration_seconds":71.3,"play_once":true,"auto_start":true,"toefl_stimulus":"listen_academic_talk","speakers":["f_us2"],"context":"Listen to a talk in an economics class."}'::jsonb,1,'{"toefl_stimulus":"listen_academic_talk","original_slug":"talk-practice-5"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('fe2268ed-2caf-4928-8d74-3db406a4bdb8','{"transcript":[{"speaker":"Narrator","text":"Listen to a talk in an economics class."},{"speaker":"Speaker","text":"Today''s concept is the network effect. A product has a network effect when it becomes more valuable to each user as more people use it. The classic example is the telephone. If you owned the only telephone in the world, it would be useless. Who would you call? But every new phone owner made everyone else''s phone a little more useful. You see the same pattern today with messaging apps and online marketplaces. A marketplace with lots of sellers attracts buyers, and lots of buyers attract more sellers. Network effects have some important consequences. One is that markets with strong network effects often end up dominated by one or two big players. Once a platform has most of the users, it''s very hard for a newcomer to compete, even with a better product, because people don''t want to leave the place where everyone else already is. Economists call this lock-in. Another consequence is that companies in these markets are often willing to lose money for years. They give the product away or sell it cheaply, hoping to grow big enough that the network effect takes over. It''s a risky bet. If they never reach that size, the money is simply gone."}]}'::jsonb,'{"source":"original-schood-toefl-2026"}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('b1298681-1e28-4fdf-9e30-c7dcaaaa740e','4f480322-a8a4-4255-add1-0de19a9cc2c7','question_single_choice','{"prompt":"What is the talk mainly about?","options":[{"id":"A","label":"The invention of the telephone"},{"id":"B","label":"How online marketplaces set prices"},{"id":"C","label":"Products that become more valuable as more people use them"},{"id":"D","label":"Why most companies lose money"}]}'::jsonb,2,'{"toefl_task":"listen_academic_talk","original_slug":"talk-practice-5","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":1}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('b1298681-1e28-4fdf-9e30-c7dcaaaa740e','{"option_id":"C"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The talk defines the network effect and describes its consequences."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('603ec559-1e5c-4121-aa2a-354235d0c0f2','4f480322-a8a4-4255-add1-0de19a9cc2c7','question_single_choice','{"prompt":"Why does the speaker mention owning the only telephone in the world?","options":[{"id":"A","label":"To illustrate that a product can be useless without other users"},{"id":"B","label":"To describe the history of telephone companies"},{"id":"C","label":"To show that early phones were expensive"},{"id":"D","label":"To compare telephones with messaging apps"}]}'::jsonb,3,'{"toefl_task":"listen_academic_talk","original_slug":"talk-practice-5","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":2}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('603ec559-1e5c-4121-aa2a-354235d0c0f2','{"option_id":"A"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"With nobody to call, a single phone would be useless, which shows how value depends on other users."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('25959be1-a525-48d6-b115-c440815f15c8','4f480322-a8a4-4255-add1-0de19a9cc2c7','question_single_choice','{"prompt":"According to the speaker, why is it hard for a new company to compete in these markets?","options":[{"id":"A","label":"New companies are not allowed to give products away."},{"id":"B","label":"Users don''t want to leave a platform where most people already are."},{"id":"C","label":"Big companies always have better products."},{"id":"D","label":"Governments protect large companies."}]}'::jsonb,4,'{"toefl_task":"listen_academic_talk","original_slug":"talk-practice-5","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":3}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('25959be1-a525-48d6-b115-c440815f15c8','{"option_id":"B"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Even with a better product, newcomers struggle because people stay where everyone else is, which is called lock-in."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('32666fd5-eb4e-462e-93c1-95de1668358b','4f480322-a8a4-4255-add1-0de19a9cc2c7','question_single_choice','{"prompt":"What does the speaker imply about companies that sell products cheaply to grow?","options":[{"id":"A","label":"They always end up dominating the market."},{"id":"B","label":"They are breaking economic rules."},{"id":"C","label":"They usually have the best products."},{"id":"D","label":"Their strategy may fail and lose all their investment."}]}'::jsonb,5,'{"toefl_task":"listen_academic_talk","original_slug":"talk-practice-5","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":4}'::jsonb) on conflict (id) do nothing;
