insert into public.parts(id,section_id,name,display_order,metadata) values('1025709c-1acd-44c5-82dc-c83f6e7040d5','755a64ee-f865-46c4-ae7a-3ca9d1c3b38f','Listen to an Academic Talk',6,'{"toefl_task":"listen_academic_talk"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('d1073f54-1746-48c5-9dcf-7803fc5503e1','1025709c-1acd-44c5-82dc-c83f6e7040d5','audio','{"url":"/media/toefl-2026/talk-practice-6.mp3","duration_seconds":82.9,"play_once":true,"auto_start":true,"toefl_stimulus":"listen_academic_talk","speakers":["m_us1"],"context":"Listen to a talk in a botany class."}'::jsonb,1,'{"toefl_stimulus":"listen_academic_talk","original_slug":"talk-practice-6"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('d1073f54-1746-48c5-9dcf-7803fc5503e1','{"transcript":[{"speaker":"Narrator","text":"Listen to a talk in a botany class."},{"speaker":"Speaker","text":"Carnivorous plants, like the Venus flytrap or the pitcher plant, tend to fascinate people because they turn the usual food chain upside down. But I want you to think about why a plant would evolve to eat insects in the first place. After all, these plants still have green leaves and still make their own sugar through photosynthesis. They don''t need insects for energy. What they need is nutrients, especially nitrogen. Carnivorous plants almost always grow in places like bogs and wet sandy soils, where nitrogen is extremely scarce. In those conditions, an insect is basically a tiny package of fertilizer. Catching and digesting one gives the plant nitrogen that its roots simply can''t find in the ground. This also explains why you don''t see carnivorous plants taking over forests or fields. Building traps and producing digestive fluids costs the plant a lot of energy. In rich soil, ordinary plants can get the same nutrients cheaply through their roots, and they grow faster. So carnivory only pays off where the soil is poor. Here''s a practical tip if you ever keep one at home: don''t give it regular plant fertilizer. Its roots aren''t adapted to rich soil, and too much can actually kill it."}]}'::jsonb,'{"source":"original-schood-toefl-2026"}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('82b10b4f-14ec-47a6-9b52-8242ab72673f','1025709c-1acd-44c5-82dc-c83f6e7040d5','question_single_choice','{"prompt":"What is the main topic of the talk?","options":[{"id":"A","label":"How to grow plants at home"},{"id":"B","label":"How insects avoid carnivorous plants"},{"id":"C","label":"The discovery of the Venus flytrap"},{"id":"D","label":"Why some plants evolved to catch insects"}]}'::jsonb,2,'{"toefl_task":"listen_academic_talk","original_slug":"talk-practice-6","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":1}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('82b10b4f-14ec-47a6-9b52-8242ab72673f','{"option_id":"D"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The speaker asks why a plant would evolve to eat insects and explains the answer: nitrogen in poor soil."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('a43d9abe-2e07-4e4f-82b4-c68c5e91488a','1025709c-1acd-44c5-82dc-c83f6e7040d5','question_single_choice','{"prompt":"According to the speaker, what do carnivorous plants mainly get from insects?","options":[{"id":"A","label":"Water"},{"id":"B","label":"Sugar for energy"},{"id":"C","label":"Nitrogen"},{"id":"D","label":"Protection from other plants"}]}'::jsonb,3,'{"toefl_task":"listen_academic_talk","original_slug":"talk-practice-6","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":2}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('a43d9abe-2e07-4e4f-82b4-c68c5e91488a','{"option_id":"C"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"They make their own sugar through photosynthesis; what they need from insects is nutrients, especially nitrogen."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('64a50024-5cae-4cbc-b8f7-dcd75919b6d2','1025709c-1acd-44c5-82dc-c83f6e7040d5','question_single_choice','{"prompt":"Why are carnivorous plants uncommon in rich soil?","options":[{"id":"A","label":"Ordinary plants get nutrients more cheaply there and grow faster."},{"id":"B","label":"Insects are rare in rich soil."},{"id":"C","label":"Rich soil damages their traps."},{"id":"D","label":"They cannot perform photosynthesis there."}]}'::jsonb,4,'{"toefl_task":"listen_academic_talk","original_slug":"talk-practice-6","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":3}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('64a50024-5cae-4cbc-b8f7-dcd75919b6d2','{"option_id":"A"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Traps are costly, and in rich soil ordinary plants get the same nutrients cheaply through their roots and grow faster."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('ba86f72a-4295-4992-b16a-723f3fe3ede6','1025709c-1acd-44c5-82dc-c83f6e7040d5','question_single_choice','{"prompt":"Why does the speaker mention plant fertilizer at the end?","options":[{"id":"A","label":"To recommend a fertilizer for home use"},{"id":"B","label":"To give advice that follows from how these plants are adapted"},{"id":"C","label":"To compare bogs with forests"},{"id":"D","label":"To explain how traps are built"}]}'::jsonb,5,'{"toefl_task":"listen_academic_talk","original_slug":"talk-practice-6","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":4}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('ba86f72a-4295-4992-b16a-723f3fe3ede6','{"option_id":"B"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Because their roots are adapted to poor soil, ordinary fertilizer can harm them, so the tip follows from the main explanation."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.parts(id,section_id,name,display_order,metadata) values('b9a8005d-adb8-47d0-9b76-ecdb88643e8a','755a64ee-f865-46c4-ae7a-3ca9d1c3b38f','Listen to an Academic Talk',7,'{"toefl_task":"listen_academic_talk"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('6a1cbba4-9213-4221-becb-c47cc19581dc','b9a8005d-adb8-47d0-9b76-ecdb88643e8a','audio','{"url":"/media/toefl-2026/talk-practice-7.mp3","duration_seconds":73.3,"play_once":true,"auto_start":true,"toefl_stimulus":"listen_academic_talk","speakers":["f_uk"],"context":"Listen to a talk in a world history class."}'::jsonb,1,'{"toefl_stimulus":"listen_academic_talk","original_slug":"talk-practice-7"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('6a1cbba4-9213-4221-becb-c47cc19581dc','{"transcript":[{"speaker":"Narrator","text":"Listen to a talk in a world history class."},{"speaker":"Speaker","text":"When people hear the term Silk Road, they often picture a single highway with caravans traveling all the way from China to the Mediterranean. That image is misleading in a couple of ways. First, it wasn''t one road. It was a shifting web of routes, over land and by sea, that changed as empires rose and fell and as some passes became too dangerous to use. Second, very few individual traders ever traveled the whole length. Goods moved in relays. A merchant might carry silk a few hundred miles to a market town, sell it to another merchant, and head home. The silk would change hands many times before it reached its final buyer, getting more expensive at every stage. Oh, and the name itself is fairly recent. It was coined by a German geographer in the nineteenth century. The people who actually used these routes didn''t call them that. And silk was only one item among many. Spices, glass, paper, horses, and metals all moved along the same networks. Arguably, the most important things that traveled weren''t goods at all, but ideas: religions, technologies, and even diseases spread along these routes. So when historians talk about the Silk Road today, they really mean a whole system of exchange."}]}'::jsonb,'{"source":"original-schood-toefl-2026"}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('2bf40840-9cd3-4024-a9c9-720adc1ec89b','b9a8005d-adb8-47d0-9b76-ecdb88643e8a','question_single_choice','{"prompt":"What is the main purpose of the talk?","options":[{"id":"A","label":"To correct a common image of the Silk Road"},{"id":"B","label":"To describe the life of a German geographer"},{"id":"C","label":"To explain how silk is produced"},{"id":"D","label":"To compare land and sea trade"}]}'::jsonb,2,'{"toefl_task":"listen_academic_talk","original_slug":"talk-practice-7","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":1}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('2bf40840-9cd3-4024-a9c9-720adc1ec89b','{"option_id":"A"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The speaker says the popular picture is misleading and explains why, point by point."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('ad880239-67a6-4a01-ae31-58d3c7b9a17e','b9a8005d-adb8-47d0-9b76-ecdb88643e8a','question_single_choice','{"prompt":"According to the speaker, how did most goods travel along the routes?","options":[{"id":"A","label":"In large caravans that made the full journey"},{"id":"B","label":"Mainly by sea"},{"id":"C","label":"Under the protection of government soldiers"},{"id":"D","label":"Through a series of traders over shorter distances"}]}'::jsonb,3,'{"toefl_task":"listen_academic_talk","original_slug":"talk-practice-7","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":2}'::jsonb) on conflict (id) do nothing;
