insert into public.content_units(id,part_id,type,data,display_order,metadata) values('a08a8759-fd08-4475-8949-6c22aba00d7d','b9a8005d-adb8-47d0-9b76-ecdb88643e8a','question_single_choice','{"prompt":"Why does the speaker mention a German geographer?","options":[{"id":"A","label":"To explain who first mapped the routes"},{"id":"B","label":"To give an example of a long-distance traveler"},{"id":"C","label":"To point out that the name Silk Road is fairly modern"},{"id":"D","label":"To describe how the routes were protected"}]}'::jsonb,4,'{"toefl_task":"listen_academic_talk","original_slug":"talk-practice-7","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":3}'::jsonb) on conflict (id) do nothing;
