insert into public.content_units(id,part_id,type,data,display_order,metadata) values('a97319f2-f2a5-4f41-8105-d7ef9e15007d','b9a8005d-adb8-47d0-9b76-ecdb88643e8a','question_single_choice','{"prompt":"What can be inferred about the price of silk?","options":[{"id":"A","label":"It was the same everywhere along the routes."},{"id":"B","label":"It was higher by the time it reached distant buyers."},{"id":"C","label":"It dropped when spices became popular."},{"id":"D","label":"It was set by the Chinese government."}]}'::jsonb,5,'{"toefl_task":"listen_academic_talk","original_slug":"talk-practice-7","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":4}'::jsonb) on conflict (id) do nothing;
