insert into public.content_units(id,part_id,type,data,display_order,metadata) values('b7940bc3-4959-47f6-a3e8-4784f775e74c','9935054f-051d-4c20-8972-b27cec0328eb','audio','{"url":"/media/toefl-2026/talk-practice-8.mp3","duration_seconds":63.8,"play_once":true,"auto_start":true,"toefl_stimulus":"listen_academic_talk","speakers":["m_us2"],"context":"Listen to a talk in an astronomy class."}'::jsonb,1,'{"toefl_stimulus":"listen_academic_talk","original_slug":"talk-practice-8"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('b7940bc3-4959-47f6-a3e8-4784f775e74c','{"transcript":[{"speaker":"Narrator","text":"Listen to a talk in an astronomy class."},{"speaker":"Speaker","text":"Here''s a question that might seem simple: why do we always see the same side of the Moon? The Moon does rotate, but it turns exactly once for every trip it makes around Earth. Because those two motions match, the same face always points toward us. Astronomers call this tidal locking. It didn''t start out this way. Billions of years ago, the Moon spun faster. But Earth''s gravity pulls slightly harder on the near side of the Moon than on the far side, stretching it into a very slightly oval shape. These bulges acted like a brake. As the Moon rotated, Earth''s pull kept tugging the bulge back into line, gradually slowing the spin until the rotation matched the orbit. Once that happened, there was nothing left to slow down, and the Moon settled into the state we see now. This isn''t unusual, by the way. Many moons in our solar system are tidally locked to their planets. And the effect works both ways. The Moon is slowly lengthening Earth''s day, too, though only by a tiny fraction of a second every century. So in the very distant future, Earth''s days will be noticeably longer than they are today."}]}'::jsonb,'{"source":"original-schood-toefl-2026"}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('2ec563cd-8d45-4551-9e5c-47c89159f29d','9935054f-051d-4c20-8972-b27cec0328eb','question_single_choice','{"prompt":"What is the talk mainly about?","options":[{"id":"A","label":"How the Moon was formed"},{"id":"B","label":"Why the same side of the Moon always faces Earth"},{"id":"C","label":"The shape of Earth''s orbit"},{"id":"D","label":"How tides affect the ocean"}]}'::jsonb,2,'{"toefl_task":"listen_academic_talk","original_slug":"talk-practice-8","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":1}'::jsonb) on conflict (id) do nothing;
