insert into public.content_units(id,part_id,type,data,display_order,metadata) values('7cbd5017-d1b1-4287-a14d-51c201b69792','9935054f-051d-4c20-8972-b27cec0328eb','question_single_choice','{"prompt":"According to the speaker, what slowed the Moon''s rotation?","options":[{"id":"A","label":"Earth''s gravity pulling on bulges in the Moon"},{"id":"B","label":"Collisions with other objects"},{"id":"C","label":"The Moon moving farther from the Sun"},{"id":"D","label":"Heat from the Moon''s surface"}]}'::jsonb,3,'{"toefl_task":"listen_academic_talk","original_slug":"talk-practice-8","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":2}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('7cbd5017-d1b1-4287-a14d-51c201b69792','{"option_id":"A"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Earth''s pull kept tugging the Moon''s bulge back into line, acting like a brake."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('df6bfde4-c131-4365-af3b-8c0652b5e212','9935054f-051d-4c20-8972-b27cec0328eb','question_single_choice','{"prompt":"Why does the speaker say that tidal locking isn''t unusual?","options":[{"id":"A","label":"To show that Earth is also tidally locked"},{"id":"B","label":"To explain why the Moon is oval"},{"id":"C","label":"To suggest that the theory is uncertain"},{"id":"D","label":"To point out that many other moons behave the same way"}]}'::jsonb,4,'{"toefl_task":"listen_academic_talk","original_slug":"talk-practice-8","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":3}'::jsonb) on conflict (id) do nothing;
