insert into public.content_units(id,part_id,type,data,display_order,metadata) values('17e1a788-14bf-49ee-ad54-c2590f1d45c6','9935054f-051d-4c20-8972-b27cec0328eb','question_single_choice','{"prompt":"According to the speaker, what will happen to Earth''s days in the very distant future?","options":[{"id":"A","label":"They will be shorter than today."},{"id":"B","label":"They will stay exactly the same."},{"id":"C","label":"They will be noticeably longer than today."},{"id":"D","label":"They will match the Moon''s orbit within a century."}]}'::jsonb,5,'{"toefl_task":"listen_academic_talk","original_slug":"talk-practice-8","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":4}'::jsonb) on conflict (id) do nothing;
