insert into public.content_units(id,part_id,type,data,display_order,metadata) values('b8512749-d0a3-43aa-8573-f74329e0a351','901a6730-74ac-420d-b893-987b9a164987','audio','{"url":"/media/toefl-2026/talk-practice-9.mp3","duration_seconds":79.4,"play_once":true,"auto_start":true,"toefl_stimulus":"listen_academic_talk","speakers":["f_us1"],"context":"Listen to a talk in a psychology class."}'::jsonb,1,'{"toefl_stimulus":"listen_academic_talk","original_slug":"talk-practice-9"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('b8512749-d0a3-43aa-8573-f74329e0a351','{"transcript":[{"speaker":"Narrator","text":"Listen to a talk in a psychology class."},{"speaker":"Speaker","text":"I want to talk about a bias that shows up constantly in negotiations, and that''s anchoring. Anchoring describes our tendency to rely too heavily on the first number we hear when making a judgment. In a common type of experiment, people are asked to estimate something, say the price of a used car, right after seeing a random number. Those who saw a high number tend to give higher estimates, even when they know the number had nothing to do with the car. The first figure acts like an anchor. People adjust away from it, but not nearly enough. In negotiation, this has a clear implication. Whoever names the first price often shapes the whole conversation. If a seller opens high, the final deal tends to land higher than it otherwise would, because the buyer''s counteroffers are pulled toward that opening figure. That''s why some negotiation coaches advise making the first offer, as long as you''ve done your research. But there''s a catch. If your opening number is wildly unrealistic, you can lose credibility, and the other side may simply walk away. So the advice isn''t to be outrageous; it''s to be ambitious but defensible. And if the other party anchors first, one tactic is to openly set their number aside and refocus the discussion on objective information, like market prices."}]}'::jsonb,'{"source":"original-schood-toefl-2026"}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('2f68a967-3229-4259-8d6b-304c2c71c481','901a6730-74ac-420d-b893-987b9a164987','question_single_choice','{"prompt":"What is the talk mainly about?","options":[{"id":"A","label":"How to buy a used car"},{"id":"B","label":"Why negotiations often fail"},{"id":"C","label":"How the first number mentioned can influence judgments and deals"},{"id":"D","label":"The history of negotiation coaching"}]}'::jsonb,2,'{"toefl_task":"listen_academic_talk","original_slug":"talk-practice-9","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":1}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('2f68a967-3229-4259-8d6b-304c2c71c481','{"option_id":"C"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The talk explains anchoring and what it means for negotiations. The used car is only an example."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('413032d7-b1e5-4a79-8371-578a1c38788e','901a6730-74ac-420d-b893-987b9a164987','question_single_choice','{"prompt":"According to the speaker, what happens when people adjust away from an anchor?","options":[{"id":"A","label":"They ignore it completely."},{"id":"B","label":"They do not adjust enough."},{"id":"C","label":"They move too far in the opposite direction."},{"id":"D","label":"They ask for more information."}]}'::jsonb,3,'{"toefl_task":"listen_academic_talk","original_slug":"talk-practice-9","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":2}'::jsonb) on conflict (id) do nothing;
