insert into public.content_units(id,part_id,type,data,display_order,metadata) values('09191b78-f58f-478b-b287-879b8156d67a','901a6730-74ac-420d-b893-987b9a164987','question_single_choice','{"prompt":"What does the speaker mean when she says an opening offer should be ''ambitious but defensible''?","options":[{"id":"A","label":"It should be high but still supported by good reasons."},{"id":"B","label":"It should be the lowest possible price."},{"id":"C","label":"It should be kept secret until the end."},{"id":"D","label":"It should be outrageous to surprise the other side."}]}'::jsonb,4,'{"toefl_task":"listen_academic_talk","original_slug":"talk-practice-9","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":3}'::jsonb) on conflict (id) do nothing;
