insert into public.content_units(id,part_id,type,data,display_order,metadata) values('d8d3c4b3-bc0d-4039-bb89-754bb058fc0e','901a6730-74ac-420d-b893-987b9a164987','question_single_choice','{"prompt":"According to the speaker, what can a negotiator do if the other side anchors first?","options":[{"id":"A","label":"Make an even more extreme offer"},{"id":"B","label":"End the negotiation immediately"},{"id":"C","label":"Accept the first offer to build trust"},{"id":"D","label":"Shift attention to objective information such as market prices"}]}'::jsonb,5,'{"toefl_task":"listen_academic_talk","original_slug":"talk-practice-9","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":4}'::jsonb) on conflict (id) do nothing;
