insert into public.content_units(id,part_id,type,data,display_order,metadata) values('44bd6e7a-116c-4475-8591-beb622fbbb87','76596d2b-beec-4821-9f6d-b0f7445c4986','audio','{"url":"/media/toefl-2026/talk-practice-10.mp3","duration_seconds":63.8,"play_once":true,"auto_start":true,"toefl_stimulus":"listen_academic_talk","speakers":["m_us3"],"context":"Listen to a talk in an architecture class."}'::jsonb,1,'{"toefl_stimulus":"listen_academic_talk","original_slug":"talk-practice-10"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('44bd6e7a-116c-4475-8591-beb622fbbb87','{"transcript":[{"speaker":"Narrator","text":"Listen to a talk in an architecture class."},{"speaker":"Speaker","text":"Let''s look at how Gothic cathedrals managed to have such tall walls and enormous windows. Earlier churches in Europe, in what we call the Romanesque style, had thick, heavy walls with fairly small windows. That wasn''t just a matter of taste. A stone roof, especially a vaulted one, pushes outward on the walls, and thick walls were needed to resist that push. If you cut big openings for windows, you weakened the walls, and the building could collapse. Gothic builders solved this with a few innovations working together. One was the pointed arch, which directs more of the weight downward rather than outward. Another was the flying buttress. Picture a stone arm reaching from the upper wall out to a heavy pillar standing outside the building. The buttress catches the outward push and carries it down to the ground, away from the wall. With the walls no longer doing all the work, builders could open them up and fill them with stained glass. So when you stand inside a great cathedral and see walls that seem to be made of colored light, remember that the secret is mostly on the outside, in those stone arms you can''t see from within."}]}'::jsonb,'{"source":"original-schood-toefl-2026"}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('642d965e-ce99-4971-93fe-c4fa9aea2249','76596d2b-beec-4821-9f6d-b0f7445c4986','question_single_choice','{"prompt":"What is the talk mainly about?","options":[{"id":"A","label":"The history of stained glass making"},{"id":"B","label":"Why Romanesque churches were more popular"},{"id":"C","label":"How cathedrals were decorated inside"},{"id":"D","label":"How Gothic builders were able to create tall walls with large windows"}]}'::jsonb,2,'{"toefl_task":"listen_academic_talk","original_slug":"talk-practice-10","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":1}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('642d965e-ce99-4971-93fe-c4fa9aea2249','{"option_id":"D"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The speaker explains the structural innovations, the pointed arch and flying buttress, that allowed tall walls and big windows."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('c8d3bfc1-83bc-4a7b-8161-5d1f679e451d','76596d2b-beec-4821-9f6d-b0f7445c4986','question_single_choice','{"prompt":"According to the speaker, why did Romanesque churches have small windows?","options":[{"id":"A","label":"Builders preferred dark interiors."},{"id":"B","label":"Glass was too expensive."},{"id":"C","label":"Large openings would have weakened the walls."},{"id":"D","label":"Windows were reserved for royal buildings."}]}'::jsonb,3,'{"toefl_task":"listen_academic_talk","original_slug":"talk-practice-10","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":2}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('c8d3bfc1-83bc-4a7b-8161-5d1f679e451d','{"option_id":"C"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The thick walls had to resist the roof''s outward push, and big openings would have weakened them. The speaker says it wasn''t just taste."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('348fbdf2-1055-4ffe-9a99-ea8f4dd21a15','76596d2b-beec-4821-9f6d-b0f7445c4986','question_single_choice','{"prompt":"What is the purpose of a flying buttress?","options":[{"id":"A","label":"To support the roof from inside"},{"id":"B","label":"To carry the outward push of the walls down to the ground"},{"id":"C","label":"To hold stained glass windows in place"},{"id":"D","label":"To make the building look taller"}]}'::jsonb,4,'{"toefl_task":"listen_academic_talk","original_slug":"talk-practice-10","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":3}'::jsonb) on conflict (id) do nothing;
