insert into public.content_units(id,part_id,type,data,display_order,metadata) values('b947488f-9010-4c0c-8be0-afe90a850adf','76596d2b-beec-4821-9f6d-b0f7445c4986','question_single_choice','{"prompt":"Why does the speaker say that the secret is mostly on the outside?","options":[{"id":"A","label":"The supports that make the large windows possible stand outside the building."},{"id":"B","label":"The windows are cleaned from outside."},{"id":"C","label":"Visitors usually enter from the side."},{"id":"D","label":"The best decorations are on the outer walls."}]}'::jsonb,5,'{"toefl_task":"listen_academic_talk","original_slug":"talk-practice-10","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":4}'::jsonb) on conflict (id) do nothing;
