insert into public.content_units(id,part_id,type,data,display_order,metadata) values('060be35b-8df1-4b3f-93a6-54ce44ff0f4d','b8b826bd-51e4-445b-b49d-15cb32397268','question_text','{"task_type":"toefl_email","prompt":"You signed up to volunteer at your campus book swap next Saturday. You have just learned that a make-up exam has been scheduled for the same morning.\n\nWrite an email to Hana Kim. In your email, do the following:\n- Explain why you cannot attend the full event.\n- Offer another way you could help.\n- Ask about future volunteer opportunities.\n\nWrite as much as you can and in complete sentences.","scenario":"You signed up to volunteer at your campus book swap next Saturday. You have just learned that a make-up exam has been scheduled for the same morning.","to":"Hana Kim","to_address":"h.kim@university.example","subject":"Volunteering at the book swap","goals":["Explain why you cannot attend the full event.","Offer another way you could help.","Ask about future volunteer opportunities."],"task_seconds":420,"rows":12,"show_word_count":true,"placeholder":"Write your email here."}'::jsonb,1,'{"toefl_task":"write_email","original_slug":"email-practice-1","difficulty":null,"difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1"}'::jsonb) on conflict (id) do nothing;
