insert into public.content_units(id,part_id,type,data,display_order,metadata) values('3787e2f8-184c-4554-8a9c-50deb9300f86','be3c21a6-9e41-45ae-b8ef-3a5e7ed09706','question_text','{"task_type":"toefl_academic_discussion","prompt":"Your professor is teaching a class on education. Write a post responding to the professor''s question. In your response, you should express and support your opinion and make a contribution to the discussion in your own words. An effective response will contain at least 100 words.\n\nDr. Varga: Many universities require first-year students to live in campus housing. The idea is that living on campus helps new students make friends, get involved in activities, and adjust to academic life more quickly. However, campus housing can be expensive, and some students would rather live at home with their families or find cheaper options nearby. What is your view? Should universities require first-year students to live on campus? Explain your reasoning.\n\nLucia: I support the requirement. During my first semester, I met almost all of my close friends in the dormitory, often just by chatting in the hallway or studying together late at night. Students who commute miss many of those small moments, and they may end up feeling isolated.\n\nKenji: I understand the social benefits, but I think the rule is unfair to students with limited budgets. Living at home allowed my older sister to graduate without much debt. Universities could offer more evening events and study spaces for commuters instead of pushing everyone into expensive housing.","course":"education","professor":{"name":"Dr. Varga","text":"Many universities require first-year students to live in campus housing. The idea is that living on campus helps new students make friends, get involved in activities, and adjust to academic life more quickly. However, campus housing can be expensive, and some students would rather live at home with their families or find cheaper options nearby. What is your view? Should universities require first-year students to live on campus? Explain your reasoning."},"students":[{"name":"Lucia","text":"I support the requirement. During my first semester, I met almost all of my close friends in the dormitory, often just by chatting in the hallway or studying together late at night. Students who commute miss many of those small moments, and they may end up feeling isolated."},{"name":"Kenji","text":"I understand the social benefits, but I think the rule is unfair to students with limited budgets. Living at home allowed my older sister to graduate without much debt. Universities could offer more evening events and study spaces for commuters instead of pushing everyone into expensive housing."}],"task_seconds":600,"min_words":100,"rows":12,"show_word_count":true,"placeholder":"Write your post here."}'::jsonb,1,'{"toefl_task":"write_academic_discussion","original_slug":"disc-practice-1","difficulty":null,"difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1"}'::jsonb) on conflict (id) do nothing;
insert into public.parts(id,section_id,name,display_order,metadata) values('264ce978-bba8-4566-b244-0e59443beca5','f516ebf4-ee01-462b-a1d9-b2b21538c82e','Academic Discussion 2',2,'{"toefl_task":"write_academic_discussion","task_seconds":600}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('f6edbbba-7fc3-4de2-bffe-6d739881c6ba','264ce978-bba8-4566-b244-0e59443beca5','question_text','{"task_type":"toefl_academic_discussion","prompt":"Your professor is teaching a class on business management. Write a post responding to the professor''s question. In your response, you should express and support your opinion and make a contribution to the discussion in your own words. An effective response will contain at least 100 words.\n\nProfessor Adeyemi: Several companies have experimented with a four-day work week, in which employees work fewer days but receive the same salary. Some managers report that workers are happier and just as productive. Others worry that customers will be frustrated when offices are closed, or that employees will feel pressure to fit five days of work into four. Do you think a four-day work week is a good idea for most businesses? Why or why not?\n\nSofia: I think it could work well for many businesses. When people have an extra day to rest, run errands, or spend time with family, they come back to work more focused. A rested team usually makes fewer mistakes, so the company may actually save money in the long run.\n\nMalik: It sounds attractive, but I doubt it suits most businesses. My uncle runs a small repair shop, and his customers expect him to be available throughout the week. If he closed an extra day, they would simply go somewhere else. It may fit office jobs, but not service work.","course":"business management","professor":{"name":"Professor Adeyemi","text":"Several companies have experimented with a four-day work week, in which employees work fewer days but receive the same salary. Some managers report that workers are happier and just as productive. Others worry that customers will be frustrated when offices are closed, or that employees will feel pressure to fit five days of work into four. Do you think a four-day work week is a good idea for most businesses? Why or why not?"},"students":[{"name":"Sofia","text":"I think it could work well for many businesses. When people have an extra day to rest, run errands, or spend time with family, they come back to work more focused. A rested team usually makes fewer mistakes, so the company may actually save money in the long run."},{"name":"Malik","text":"It sounds attractive, but I doubt it suits most businesses. My uncle runs a small repair shop, and his customers expect him to be available throughout the week. If he closed an extra day, they would simply go somewhere else. It may fit office jobs, but not service work."}],"task_seconds":600,"min_words":100,"rows":12,"show_word_count":true,"placeholder":"Write your post here."}'::jsonb,1,'{"toefl_task":"write_academic_discussion","original_slug":"disc-practice-2","difficulty":null,"difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1"}'::jsonb) on conflict (id) do nothing;
insert into public.parts(id,section_id,name,display_order,metadata) values('0e16b3b9-b7af-4468-8da3-9bcf8429b5cd','f516ebf4-ee01-462b-a1d9-b2b21538c82e','Academic Discussion 3',3,'{"toefl_task":"write_academic_discussion","task_seconds":600}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('d236ed7a-b4b4-48c9-8e34-82c1e2545722','0e16b3b9-b7af-4468-8da3-9bcf8429b5cd','question_text','{"task_type":"toefl_academic_discussion","prompt":"Your professor is teaching a class on media studies. Write a post responding to the professor''s question. In your response, you should express and support your opinion and make a contribution to the discussion in your own words. An effective response will contain at least 100 words.\n\nDr. Petrov: These days, people can follow the news through short updates on their phones throughout the day, or they can read fewer but longer articles that explain events in depth. Short updates keep us informed quickly, while long articles provide background and context that brief summaries often leave out. Which approach do you think helps people understand the world better: following many short updates, or reading a smaller number of in-depth articles? Explain why.\n\nNadia: I prefer in-depth articles. Short updates often report only the most dramatic part of a story, and the full picture comes out later. When I read a longer article, I learn why something happened and what experts think about it, so I am less likely to misunderstand the situation.\n\nRavi: For me, short updates are more useful. I am busy with classes and a part-time job, so I rarely have time for long articles. Quick updates at least keep me aware of what is happening, and if a story seems important, I can always look for more detail later.","course":"media studies","professor":{"name":"Dr. Petrov","text":"These days, people can follow the news through short updates on their phones throughout the day, or they can read fewer but longer articles that explain events in depth. Short updates keep us informed quickly, while long articles provide background and context that brief summaries often leave out. Which approach do you think helps people understand the world better: following many short updates, or reading a smaller number of in-depth articles? Explain why."},"students":[{"name":"Nadia","text":"I prefer in-depth articles. Short updates often report only the most dramatic part of a story, and the full picture comes out later. When I read a longer article, I learn why something happened and what experts think about it, so I am less likely to misunderstand the situation."},{"name":"Ravi","text":"For me, short updates are more useful. I am busy with classes and a part-time job, so I rarely have time for long articles. Quick updates at least keep me aware of what is happening, and if a story seems important, I can always look for more detail later."}],"task_seconds":600,"min_words":100,"rows":12,"show_word_count":true,"placeholder":"Write your post here."}'::jsonb,1,'{"toefl_task":"write_academic_discussion","original_slug":"disc-practice-3","difficulty":null,"difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1"}'::jsonb) on conflict (id) do nothing;
insert into public.parts(id,section_id,name,display_order,metadata) values('e08a17af-8da1-4fc7-b57e-5dc7b4079875','f516ebf4-ee01-462b-a1d9-b2b21538c82e','Academic Discussion 4',4,'{"toefl_task":"write_academic_discussion","task_seconds":600}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('504d2f13-53bf-4d79-a982-99b271b45202','e08a17af-8da1-4fc7-b57e-5dc7b4079875','question_text','{"task_type":"toefl_academic_discussion","prompt":"Your professor is teaching a class on psychology. Write a post responding to the professor''s question. In your response, you should express and support your opinion and make a contribution to the discussion in your own words. An effective response will contain at least 100 words.\n\nDr. Moreau: In our unit on motivation, we have discussed two approaches to setting goals. Some researchers recommend very specific goals, such as studying for exactly two hours every evening. Others suggest flexible goals, such as studying more this month than last month, because they allow people to adjust when life becomes busy. In your opinion, which type of goal is more effective for students who want to improve their study habits? Why?\n\nAma: Specific goals work better for me. When my plan says exactly what to do and when, I cannot easily find excuses. Flexible goals feel too vague, so I tend to postpone my work until the last minute. A clear target also makes it easy to check whether I am making progress.\n\nLukas: I prefer flexible goals. Last year I set a strict schedule, and when I missed a single day because I was sick, I felt like a failure and gave up completely. A flexible goal lets me recover from bad days without losing motivation, which matters more over a whole semester.","course":"psychology","professor":{"name":"Dr. Moreau","text":"In our unit on motivation, we have discussed two approaches to setting goals. Some researchers recommend very specific goals, such as studying for exactly two hours every evening. Others suggest flexible goals, such as studying more this month than last month, because they allow people to adjust when life becomes busy. In your opinion, which type of goal is more effective for students who want to improve their study habits? Why?"},"students":[{"name":"Ama","text":"Specific goals work better for me. When my plan says exactly what to do and when, I cannot easily find excuses. Flexible goals feel too vague, so I tend to postpone my work until the last minute. A clear target also makes it easy to check whether I am making progress."},{"name":"Lukas","text":"I prefer flexible goals. Last year I set a strict schedule, and when I missed a single day because I was sick, I felt like a failure and gave up completely. A flexible goal lets me recover from bad days without losing motivation, which matters more over a whole semester."}],"task_seconds":600,"min_words":100,"rows":12,"show_word_count":true,"placeholder":"Write your post here."}'::jsonb,1,'{"toefl_task":"write_academic_discussion","original_slug":"disc-practice-4","difficulty":null,"difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1"}'::jsonb) on conflict (id) do nothing;
